test('fresh lives have workplace social life guardianship parenting extended family housing justice romance appearance education mobility yearly ambition and persistent variety profiles',()=>{const {run}=game();assert.equal(run('s.version'),73);assert.ok(run('s.variety&&s.variety.ambition&&s.variety.ambition.target>0'));assert.equal(run('s.variety.ambition.year'),run('s.year+s.age'));});
test('variety ambition counts distinct meaningful actions instead of repeated spam',()=>{const {run}=game();run(setup+'s.age=20;s.variety={activityStats:{},recent:[],completed:[],annualHistory:[],rerolls:0,ambition:{id:"variety",title:"Test",desc:"",target:5,progress:0,year:s.year+s.age,done:false,keys:[],reward:{}}};trackLifeVarietyAction({kind:"period",id:"market"});trackLifeVarietyAction({kind:"period",id:"market"});trackLifeVarietyAction({kind:"training",id:"horse"})');assert.equal(run('s.variety.ambition.progress'),2);});
test('seasonal activities rotate with the calendar month',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=10');assert.ok(run('seasonalActivitiesNow().some(x=>x.id==="spring_move")'));run('s.monthsRemaining=5');assert.ok(run('seasonalActivitiesNow().some(x=>x.id==="autumn_store")'));assert.ok(run('!seasonalActivitiesNow().some(x=>x.id==="spring_move")'));});
test('repeating the same period activity is remembered and loses novelty',()=>{const {run}=game();run(setup+'s.age=20;s.variety.recent=[{key:"period:bardlisten",year:s.year+s.age,month:1},{key:"period:bardlisten",year:s.year+s.age,month:2},{key:"period:bardlisten",year:s.year+s.age,month:3}];window.__h=s.happiness;window.__note=periodNoveltyBonus("bardlisten")');assert.ok(run('__note.includes("tekrarlamak")'));assert.equal(run('s.happiness'),run('__h-1'));});
test('v8 saves migrate to v25 with variety profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=8;delete s.variety;save();load()');assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.variety&&s.variety.activityStats&&s.variety.ambition'));});
test('migration destinations expose other settlements available in the current year',()=>{const {run}=game();run(setup+'s.age=20;ensureMobility()');assert.ok(run('migrationDestinations().some(x=>x.place!==s.place)'));assert.ok(run('migrationDestinations().every(x=>realmActiveAt(x.realm,s.year+s.age))'));});
test('household migration moves partner and children while preserving tribe identity',()=>{const {run}=game();run(setup+'s.age=25;s.wealth=200;s.partner=normalizeNPC({name:"Es",gender:"female",age:24,alive:true,rel:80,type:"Eş"});s.children=[normalizeNPC({name:"Cocuk",gender:"male",age:4,alive:true,rel:85,type:"Çocuk"})];window.__tribe=s.tribe;window.__dest=migrationDestinations().find(x=>x.realm===s.realm)||migrationDestinations()[0];Math.random=()=>.999;migrateTo(__dest.realm,__dest.place,"household")');assert.equal(run('s.place'),run('__dest.place'));assert.equal(run('s.tribe'),run('__tribe'));assert.equal(run('s.partner.place'),run('__dest.place'));assert.equal(run('s.children[0].place'),run('__dest.place'));assert.equal(run('s.mobility.moves'),1);});
test('moving alone leaves close family behind and strains the relationship',()=>{const {run}=game();run(setup+'s.age=25;s.wealth=200;s.partner=normalizeNPC({name:"Es",gender:"female",age:24,alive:true,rel:80,type:"Eş",place:s.place,realm:s.realm});window.__rel=s.partner.rel;window.__old=s.place;window.__dest=migrationDestinations().find(x=>x.realm===s.realm);Math.random=()=>.999;migrateTo(__dest.realm,__dest.place,"alone")');assert.equal(run('s.partner.place'),run('__old'));assert.ok(run('s.partner.rel<__rel'));});
test('cross realm migration reduces old political influence but does not rewrite tribe',()=>{const {run}=game();run(setup+'s.age=70;s.wealth=300;ensureStateCourt();s.stateCourt.influence=80;s.stateCourt.councilTrust=70;window.__tribe=s.tribe;window.__dest=migrationDestinations().find(x=>x.realm!==s.realm);Math.random=()=>.999');assert.ok(run('!!__dest'));run('migrateTo(__dest.realm,__dest.place,"alone")');assert.equal(run('s.tribe'),run('__tribe'));assert.ok(run('s.stateCourt.influence<=20'));});
test('v9 saves migrate to v25 with mobility profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=9;delete s.mobility;save();load()');assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.mobility&&Array.isArray(s.mobility.history)&&Number.isFinite(s.mobility.localStanding)'));});
test('studying a path creates a persistent mentor peer group and progress',()=>{const {run}=game();run(setup+'s.age=18;s.monthsRemaining=12;studyEducation("smith")');assert.equal(run('s.education.tracks.smith.months'),1);assert.ok(run('!!educationContact(s.education.tracks.smith.mentorId)'));assert.ok(run('s.education.tracks.smith.peerIds.length>=2'));assert.ok(run('s.skills.craft>100?true:s.skills.craft>=100'));});
test('education ranks advance at persistent month thresholds and record evaluations',()=>{const {run}=game();run(setup+'s.age=18;s.monthsRemaining=12;s.skills.craft=100;ensureEducation();s.education.tracks.smith.months=5;Math.random=()=>0;studyEducation("smith")');assert.equal(run('s.education.tracks.smith.months'),6);assert.equal(run('s.education.tracks.smith.rank'),"Temel Öğrenen");assert.equal(run('s.education.tracks.smith.evaluations'),1);assert.ok(run('s.education.tracks.smith.praise>=1'));});
test('education peers can become lasting friends through repeated bonds',()=>{const {run}=game();run(setup+'s.age=18;ensureEducation();educationPeers("story",1);window.__p=educationContact(s.education.tracks.story.peerIds[0]);__p.rel=70;__p.bonds.trust=65;s.monthsRemaining=12;educationInteraction(ensureEducation().contacts.findIndex(x=>x.id===__p.id),"befriend")');assert.ok(run('s.friends.some(x=>x.id===__p.id)'));});
test('deep education gives a career acceptance bonus without bypassing requirements',()=>{const {run}=game();run(setup+'s.age=25;ensureEducation();s.education.tracks.smith.months=60;s.education.tracks.smith.praise=3;window.__r=D.careers.find(x=>x.id==="smith");window.__b=educationFitBonusForCareer(__r)');assert.ok(run('__b>0'));assert.ok(run('__b<=.14'));run('s.skills.craft=0');assert.ok(run('careerIssue(__r).includes("Zanaat")||careerIssue(__r).includes("zanaat")||careerIssue(__r).includes("craft")'));});
test('v10 saves migrate to v25 with education profile and dedicated backup',()=>{const {run,storage}=game();run('s.version=10;delete s.education;save();load()');assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.education&&s.education.tracks&&Array.isArray(s.education.contacts)'));});
test('education mentor and peer can become direct life-event targets',()=>{const {run}=game();run(setup+'s.age=18;ensureEducation();educationMentor("smith",true);educationPeers("smith",2)');assert.ok(run('eventTargetCandidates("educationMentor").some(x=>x.statusFlags.educationTrack==="smith")'));assert.ok(run('eventTargetCandidates("educationPeer").some(x=>x.statusFlags.educationTrack==="smith")'));});
test('education life event choices improve the matching track skill and NPC bond',()=>{const {run}=game();run(setup+'s.age=18;ensureEducation();window.__m=educationMentor("smith",true);s.pendingEventId="education_mentor_trial";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,kind:"education",targetId:__m.id};window.__skill=s.skills.craft;window.__trust=__m.bonds.trust;chooseContextEvent(0)');assert.ok(run('s.skills.craft>=__skill'));assert.ok(run('__m.bonds.trust>__trust'));assert.equal(run('s.pendingEventId'),null);});
test('fresh appearance profile renders a layered portrait instead of an emoji',()=>{const {run}=game();assert.equal(run('s.version'),73);assert.ok(run('s.appearance&&APPEARANCE_OPTIONS.hair.some(x=>x.id===s.appearance.hair)'));assert.ok(run('appearanceAvatarHtml().includes("portrait-head")&&appearanceAvatarHtml().includes("portrait-hair")'));});
test('hair face and headwear customization persists without spending a month',()=>{const {run}=game();run(setup+'window.__m=s.monthsRemaining;setAppearancePart("hair","braid");setAppearancePart("face","broad");setAppearancePart("headwear","bork")');assert.equal(run('s.appearance.hair'),"braid");assert.equal(run('s.appearance.face'),"broad");assert.equal(run('s.appearance.headwear'),"bork");assert.equal(run('s.monthsRemaining'),run('__m'));});
test('appearance ages gradually and frailty can accelerate greying',()=>{const {run}=game();run(setup+'s.age=30;ensureAppearance();ensureHealthProfile();window.__young=appearanceGreyLevel();s.age=68;s.health=35;s.healthProfile.frailty=75;window.__old=appearanceGreyLevel()');assert.ok(run('__old>__young'));assert.ok(run('appearanceAvatarHtml().includes("age-elder")'));});
