test('deepening a friendship records shared experience and improves trust',()=>{const {run}=game();run(setup+'s.age=20;s.monthsRemaining=12;window.__n=normalizeNPC({name:"Dost",gender:"male",age:20,alive:true,type:"Dost",rel:60,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];ensureSocialLife();window.__t=__n.bonds.trust;friendshipAction(0,"deepen")');assert.equal(run('s.monthsRemaining'),11);assert.ok(run('__n.bonds.trust>__t'));assert.ok(run('ensureFriendProfile(__n).sharedExperiences>=1'));});
test('a highly trusted friend can become an explicit confidant tier',()=>{const {run}=game();run(setup+'s.age=22;s.monthsRemaining=12;window.__n=normalizeNPC({name:"Sirdaş",gender:"female",age:21,alive:true,type:"Dost",rel:85,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=85;ensureSocialLife();friendshipAction(0,"confidant")');assert.equal(run('ensureFriendProfile(__n).chosenConfidant'),true);assert.equal(run('friendTier(__n)'),"Sırdaş");});
test('three strong friends form a circle and a gathering improves mutual NPC links',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;s.friends=[];for(let i=0;i<3;i++){let n=normalizeNPC({name:"F"+i,gender:i%2?"female":"male",age:24+i,alive:true,type:"Dost",rel:80,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");normalizeBonds(n);n.bonds.trust=75;s.friends.push(n)};ensureSocialLife();window.__g=autoCreateFriendCircle();window.__l=socialLinkBetween(s.friends[0],s.friends[1],true);window.__before=__l.score;friendCircleAction(__g.id,"gather")');assert.ok(run('__g&&__g.memberIds.length===3'));assert.ok(run('__l.score>__before'));assert.equal(run('__g.gatherings'),1);});
test('long distance and lack of contact can make a friend distant without deleting them',()=>{const {run}=game();run(setup+'s.age=25;window.__n=normalizeNPC({name:"Uzak",gender:"male",age:25,alive:true,type:"Dost",rel:70,realm:s.realm,place:"Uzak Yer",tribe:s.tribe},"Dost");s.friends=[__n];ensureSocialLife();for(let i=0;i<12;i++)tickFriendshipMonth({kind:"wait"})');assert.equal(run('ensureFriendProfile(__n).status'),"distant");assert.equal(run('s.friends.some(x=>x.id===__n.id)'),true);});
test('reconnecting with a distant loyal friend restores the active friendship',()=>{const {run}=game();run(setup+'s.age=30;s.monthsRemaining=12;window.__n=normalizeNPC({name:"EskiDost",gender:"male",age:30,alive:true,type:"Dost",rel:80,realm:s.realm,place:s.place,tribe:s.tribe,traits:["sadik","sakin"]},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=80;window.__p=ensureFriendProfile(__n);__p.status="distant";__p.monthsDistant=36;Math.random=()=>0;friendshipAction(0,"reconnect")');assert.equal(run('__p.status'),"active");assert.equal(run('__p.monthsDistant'),0);assert.ok(run('s.socialLife.reconnections>=1'));});
test('a career friend referral creates a temporary career-entry bonus',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;window.__n=normalizeNPC({name:"DemirciDost",gender:"male",age:30,alive:true,type:"Dost",rel:80,role:"Demirci",realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=80;ensureSocialLife();friendshipAction(0,"referral");window.__r=D.careers.find(x=>x.id==="smith")');assert.ok(run('friendCareerReferralBonus(__r)>0'));assert.ok(run('s.socialLife.referrals.some(x=>x.friendId===__n.id&&x.path===__r.path)'));});
test('a trusted friend can introduce a partner candidate that remembers who introduced them',()=>{const {run}=game();run(setup+'s.age=24;s.monthsRemaining=12;s.partner=null;s.married=false;window.__n=normalizeNPC({name:"Araci",gender:"male",age:25,alive:true,type:"Dost",rel:80,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=80;ensureSocialLife();friendshipAction(0,"matchmake")');assert.ok(run('!!s.partner'));assert.equal(run('s.partner.statusFlags.introducedByFriend'),run('__n.id'));assert.ok(run('s.romance.current&&s.romance.current.partnerId===s.partner.id'));});
test('a military friend can become the same persistent NPC in the campaign-comrade pool',()=>{const {run}=game();run(setup+'s.age=25;s.monthsRemaining=12;window.__n=normalizeNPC({name:"AlpDost",gender:"male",age:27,alive:true,type:"Dost",rel:80,role:"Alp",realm:s.realm,place:s.place,tribe:s.tribe},"Dost");s.friends=[__n];normalizeBonds(__n);__n.bonds.trust=80;ensureSocialLife();friendshipAction(0,"comrade")');assert.ok(run('s.military.comrades.some(x=>x.id===__n.id)'));assert.equal(run('s.military.comrades.find(x=>x.id===__n.id).id'),run('__n.id'));});
test('friend-circle conflict events directly change the same persistent group tension',()=>{const {run}=game();run(setup+'s.age=25;s.friends=[];for(let i=0;i<3;i++){let n=normalizeNPC({name:"G"+i,gender:"male",age:25+i,alive:true,type:"Dost",rel:80,realm:s.realm,place:s.place,tribe:s.tribe},"Dost");normalizeBonds(n);n.bonds.trust=80;s.friends.push(n)};ensureSocialLife();window.__g=autoCreateFriendCircle();__g.tension=40;window.__n=s.friends[0];window.__before=__g.tension;applyFriendshipEvent("friend_circle_conflict",0,__n)');assert.ok(run('__g.tension<__before'));});
test('v18 saves migrate to v25 with social-life profiles and dedicated backup',()=>{const {run,storage}=game();run('s.version=18;delete s.socialLife;window.__n=normalizeNPC({name:"EskiDost",gender:"male",age:20,alive:true,type:"Dost",rel:70});s.friends=[__n];save();load()');assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.socialLife&&!!s.socialLife.profiles[s.friends[0].id]'));});
