test('entering a career creates one supervisor and peer coworkers as persistent NPCs',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true)');assert.equal(run('s.workplace.roleId'),"smith");assert.equal(run('currentWorkplaceContacts().filter(x=>x.statusFlags.workplacePosition==="supervisor").length'),1);assert.ok(run('workplacePeers().length>=2'));assert.ok(run('currentWorkplaceContacts().every(x=>allNPCs().some(n=>n.id===x.id))'));});
test('collaborating with a coworker improves project progress standing and trust',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);window.__n=workplacePeers()[0];window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);window.__p=s.workplace.projectProgress;window.__st=s.workplace.standing;window.__t=__n.bonds.trust;workplaceAction(__i,"collaborate")');assert.ok(run('s.workplace.projectProgress>__p'));assert.ok(run('s.workplace.standing>__st'));assert.ok(run('__n.bonds.trust>__t'));});
test('a trusted supervisor can sponsor the player for two years without bypassing career requirements',()=>{const {run}=game();run(setup+'window.__r=D.careers.find(x=>x.id==="smith");s.role=__r.name;s.path=__r.path;ensureWorkplaceForRole(true);window.__n=workplaceSupervisor();window.__i=currentWorkplaceContacts().findIndex(x=>x.id===__n.id);__n.rel=95;__n.bonds.trust=95;__n.bonds.respect=95;s.workplace.standing=80;Math.random=()=>0;workplaceAction(__i,"sponsor")');assert.equal(run('s.workplace.sponsorId'),run('__n.id'));assert.ok(run('s.workplace.sponsorUntil>=s.year+s.age+2'));assert.ok(run('workplaceSponsorBonus()>0'));});
