test('remote funeral costs travel wealth but does not migrate the player',()=>{const {run}=game();run(setup+'s.age=30;s.wealth=20;s.monthsRemaining=12;window.__p=s.parents.find(x=>x.alive);__p.rel=95;__p.bonds.trust=90;__p.place=D.realms[s.realm].places.find(x=>x!==s.place)||s.place;window.__place=s.place;window.__loss=registerNPCDeath(__p,"test",{inherit:false});window.__w=s.wealth;window.__m=s.monthsRemaining;window.__g=s.bereavement.grief[__p.id].intensity;bereavementAction(__loss.id,"attend")');assert.equal(run('__loss.funeral.status'),"attended");assert.equal(run('s.place'),run('__place'));assert.equal(run('__w-s.wealth'),run('__loss.funeral.travelCost'));assert.equal(run('__m-s.monthsRemaining'),1);assert.ok(run('s.bereavement.grief[__p.id].intensity<__g'));assert.equal(run('s.bereavement.funeralCount'),1);});

test('remote farewell closes funeral decision without travel cost',()=>{const {run}=game();run(setup+'s.age=30;s.wealth=1;s.monthsRemaining=12;window.__p=s.parents.find(x=>x.alive);__p.rel=90;__p.place=D.realms[s.realm].places.find(x=>x!==s.place)||s.place;window.__loss=registerNPCDeath(__p,"test",{inherit:false});window.__w=s.wealth;bereavementAction(__loss.id,"lament")');assert.equal(run('__loss.funeral.status'),"remote_farewell");assert.equal(run('s.wealth'),run('__w'));assert.ok(run('s.bereavement.grief[__p.id].closure>=10'));});

test('missing funeral deadline records the miss and deepens unresolved grief',()=>{const {run}=game();run(setup+'s.age=30;window.__p=s.parents.find(x=>x.alive);__p.rel=95;window.__loss=registerNPCDeath(__p,"test",{inherit:false});window.__g=s.bereavement.grief[__p.id].intensity;bereavementMonthTick(5,{kind:"wait"})');assert.equal(run('__loss.funeral.status'),"missed");assert.equal(run('s.bereavement.missedFunerals'),1);assert.ok(run('s.bereavement.grief[__p.id].intensity>=__g'));});

test('direct caregiving accumulates care months closure and meaningful strain',()=>{const {run}=game();run(setup+'s.age=30;s.monthsRemaining=12;window.__n=s.parents.find(x=>x.alive);npcWorldTrigger(__n,"illness",{years:2,severity:3,source:"ağır ateş"});__n.health=20;for(let i=0;i<5;i++){s.pendingEventId=null;s.pendingEventContext=null;npcLifeAction(__n.id,"care")}window.__c=caregivingRecord(__n,false)');assert.equal(run('__c.months'),5);assert.ok(run('__c.closure>=20'));assert.ok(run('__c.strain>=25'));assert.equal(run('s.bereavement.careMonths'),5);assert.equal(run('eventRequirementOK(EVENT_DECK.find(e=>e.id==="caregiver_strain_v25"))'),true);});

test('farewell before death reduces initial grief through accumulated closure',()=>{const {run}=game();run(setup+'s.age=30;s.monthsRemaining=12;window.__n=s.parents.find(x=>x.alive);__n.rel=95;__n.bonds.trust=90;npcWorldTrigger(__n,"illness",{years:1,severity:3,source:"ağır hastalık"});__n.health=35;npcLifeAction(__n.id,"farewell");s.pendingEventId=null;s.pendingEventContext=null;window.__raw=deathCloseness(__n);window.__loss=registerNPCDeath(__n,"ağır hastalık",{inherit:false});window.__grief=s.bereavement.grief[__n.id].intensity');assert.ok(run('caregivingRecord(__n,false).closure>=12'));assert.ok(run('__grief<__raw'));});

test('npc death ripples grief memories into connected living family',()=>{const {run}=game();run(setup+'s.age=25;window.__p=s.parents.find(x=>x.alive);window.__sib=s.siblings.find(x=>x.alive);if(!__sib){__sib=normalizeNPC({name:"Kardes",gender:"male",age:20,alive:true,type:"Erkek kardeş",rel:80,parentIds:s.parents.map(x=>x.id),realm:s.realm,place:s.place},"Erkek kardeş");s.siblings.push(__sib)}registerNPCDeath(__p,"test",{inherit:false})');assert.equal(run('__sib.statusFlags.griefFor'),run('__p.id'));assert.ok(run('__sib.memories.some(x=>x.kind==="loss")'));});

test('memorial action can be used once per year and reduces grief',()=>{const {run}=game();run(setup+'s.age=30;s.monthsRemaining=12;window.__p=s.parents.find(x=>x.alive);window.__loss=registerNPCDeath(__p,"test",{inherit:false});window.__g=s.bereavement.grief[__p.id].intensity;bereavementAction(__loss.id,"memorial")');assert.ok(run('s.bereavement.grief[__p.id].intensity<__g'));assert.equal(run('s.bereavement.memorials'),1);assert.ok(run('bereavementActionIssue(__loss.id,"memorial").includes("zaten")'));});

test('v25 grief event can alter persistent grief intensity',()=>{const {run}=game();run(setup+'s.age=30;window.__p=s.parents.find(x=>x.alive);registerNPCDeath(__p,"test",{inherit:false});window.__g=strongestGrief();window.__before=__g.intensity;window.__target=[...s.parents,...s.siblings,...s.children,...s.relatives].find(x=>x.alive);s.pendingEventId="grief_shared_memory_v25";s.pendingEventContext={age:s.age,year:s.year+s.age,month:1,targetId:__target.id};chooseContextEvent(0)');assert.ok(run('__g.intensity<__before'));});

test('v24 saves migrate to v25 with bereavement containers and dedicated backup',()=>{const {run,storage}=game();run('s.version=24;delete s.bereavement;save();load()');assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v37'));assert.ok(run('s.bereavement&&Array.isArray(s.bereavement.losses)&&s.bereavement.grief&&s.bereavement.caregiving'));});


test('v26 fresh lives carry persistent council proposal and policy containers',()=>{const {run}=game();assert.equal(run('s.version'),73);assert.ok(run('s.stateCourt&&Array.isArray(s.stateCourt.activePolicies)&&Array.isArray(s.stateCourt.proposalHistory)&&s.stateCourt.proposalCooldowns'));});

test('opening a council proposal creates stances for real persistent state NPCs and spends a month',()=>{const {run}=game();run(setup+'s.age=36;s.monthsRemaining=12;s.role="Boy Beyi";s.skills.speech=80;s.prestige=80;window.__circle=ensureStateCircle();window.__q=ensureStateCourt();__q.influence=80;__q.councilTrust=80;__q.tribeSupport=80;__q.rivalPressure=10;window.__m=s.monthsRemaining;stateOpenProposal("winter_share");window.__p=currentStateProposal()');assert.equal(run('__p.id'),"winter_share");assert.equal(run('Object.keys(__p.stances).length'),3);assert.ok(run('Object.keys(__p.stances).every(id=>!!npcById(id))'));assert.equal(run('__m-s.monthsRemaining'),1);});

test('high-support council vote passes deterministically and creates a multi-year policy',()=>{const {run}=game();run(setup+'s.age=36;s.monthsRemaining=12;s.role="Boy Beyi";s.skills.speech=90;s.prestige=90;window.__circle=ensureStateCircle();window.__q=ensureStateCourt();__q.influence=90;__q.councilTrust=90;__q.tribeSupport=90;__q.rivalPressure=5;for(const n of [__circle.patron,__circle.rival,__circle.elder]){n.rel=95;n.bonds.trust=95;n.bonds.grudge=0}s.pendingEventId=null;s.pendingDecision=null;stateOpenProposal("winter_share");s.pendingEventId=null;s.pendingDecision=null;window.__t=stateVoteTally();callStateVote()');assert.ok(run('__t.yes>=3'));assert.equal(run('s.stateCourt.proposalHistory[0].passed'),true);assert.equal(run('statePolicyActive("winter_share")'),true);assert.equal(run('s.stateCourt.currentProposal'),null);});

test('lobbying a hostile council member is one-shot and can improve their stance',()=>{const {run}=game();run(setup+'s.age=36;s.monthsRemaining=12;s.role="Boy Beyi";s.skills.speech=100;s.prestige=100;window.__circle=ensureStateCircle();window.__q=ensureStateCourt();__q.influence=90;__q.councilTrust=70;__q.tribeSupport=70;__q.rivalPressure=20;stateOpenProposal("caravan_guard");s.pendingEventId=null;s.pendingDecision=null;window.__p=currentStateProposal();window.__r=__circle.rival;__p.stances[__r.id]=-2;Math.random=()=>0;lobbyStateMember(__r.id)');assert.ok(run('__p.stances[__r.id]>=0'));assert.ok(run('__p.lobbiedIds.includes(__r.id)'));assert.ok(run('stateLobbyIssue(__r.id).includes("zaten")'));});

test('low-support council vote is rejected and records a cooldown instead of silently passing',()=>{const {run}=game();run(setup+'s.age=36;s.monthsRemaining=12;s.role="Boy Beyi";window.__circle=ensureStateCircle();window.__q=ensureStateCourt();__q.influence=55;__q.councilTrust=55;__q.tribeSupport=55;__q.rivalPressure=30;stateOpenProposal("craft_patronage");s.pendingEventId=null;s.pendingDecision=null;window.__p=currentStateProposal();for(const id of Object.keys(__p.stances))__p.stances[id]=-2;__q.influence=10;__q.councilTrust=10;__q.tribeSupport=10;__q.rivalPressure=90;callStateVote()');assert.equal(run('s.stateCourt.proposalHistory[0].passed'),false);assert.ok(run('s.stateCourt.failed>=1'));assert.ok(run('s.stateCourt.proposalCooldowns.craft_patronage>s.year+s.age'));assert.equal(run('statePolicyActive("craft_patronage")'),false);});

test('winter relief policy lowers food pressure and shortage over repeated quarters',()=>{const {run}=game();run(setup+'s.age=30;window.__q=ensureStateCourt();__q.activePolicies=[{id:"winter_share",name:STATE_PROPOSALS.winter_share.name,startedYear:s.year+s.age,expiresYear:s.year+s.age+2}];window.__e=ensureEconomy();__e.foodPressure=80;__e.shortageMonths=2;statePolicyQuarterTick(3);statePolicyQuarterTick(6)');assert.ok(run('__e.foodPressure<=74'));assert.ok(run('__e.shortageMonths<=1'));});

