test('npc property value includes both cash and owned physical assets',()=>{const {run}=game();run(setup+'window.__n=s.parents[0];__n.wealth=20;normalizeNPCEstate(__n).assets=["horse","flock"]');assert.ok(run('npcEstateValue(__n)>20'));assert.ok(run('npcEstateSummary(__n).includes("At")&&npcEstateSummary(__n).includes("Sürü")'));});

test('high-value parent estate with multiple heirs opens a real inheritance dispute',()=>{const {run}=game();run(setup+'s.age=35;window.__p=s.parents[0];__p.rel=95;__p.bonds.trust=90;__p.wealth=60;normalizeNPCEstate(__p).assets=["horse","flock","yurt"];if(!s.siblings.some(x=>x.alive)){const x=normalizeNPC({name:"Kardes",gender:"male",age:30,alive:true,type:"Erkek kardeş",rel:65,parentIds:s.parents.map(p=>p.id),realm:s.realm,place:s.place},"Erkek kardeş");s.siblings.push(x)}window.__e=processNPCEstate(__p)');assert.equal(run('__e.status'),"disputed");assert.equal(run('__e.playerHeir'),true);assert.ok(run('__e.heirs.length>=2'));assert.ok(run('__e.risk>=45'));assert.equal(run('s.npcEstates.disputes'),1);});

test('inheritance mediation settles planned shares and transfers real assets to player and npc heirs',()=>{const {run}=game();run(setup+'s.age=35;s.monthsRemaining=12;s.wealth=5;window.__p=s.parents[0];__p.rel=95;__p.bonds.trust=90;__p.wealth=60;normalizeNPCEstate(__p).assets=["horse","flock","yurt"];if(!s.siblings.some(x=>x.alive)){const x=normalizeNPC({name:"Kardes",gender:"male",age:30,alive:true,type:"Erkek kardeş",rel:65,parentIds:s.parents.map(p=>p.id),realm:s.realm,place:s.place},"Erkek kardeş");s.siblings.push(x)}window.__e=processNPCEstate(__p);window.__w=s.wealth;window.__m=s.monthsRemaining;inheritanceDisputeAction(__e.id,"mediate")');assert.equal(run('__e.status'),"settled");assert.equal(run('__e.resolution'),"mediate");assert.equal(run('__m-s.monthsRemaining'),1);assert.ok(run('s.wealth>__w'));assert.ok(run('__e.transfers.some(x=>x.assets.length>0)'));assert.ok(run('__e.transfers.length>=2'));assert.equal(run('normalizeNPCEstate(__p).assets.length'),0);});

test('claiming a larger inheritance share increases player planned cash but damages family relations',()=>{const {run}=game();run(setup+'s.age=35;s.monthsRemaining=12;window.__p=s.parents[0];__p.wealth=80;__p.rel=95;normalizeNPCEstate(__p).assets=["horse","flock","yurt"];if(!s.siblings.some(x=>x.alive)){const x=normalizeNPC({name:"Kardes",gender:"male",age:30,alive:true,type:"Erkek kardeş",rel:70,parentIds:s.parents.map(p=>p.id),realm:s.realm,place:s.place},"Erkek kardeş");s.siblings.push(x)}window.__sib=s.siblings.find(x=>x.alive);window.__rel=__sib.rel;window.__e=processNPCEstate(__p);window.__base=__e.planned.find(x=>x.heirId===s.id).wealth;inheritanceDisputeAction(__e.id,"claim")');assert.ok(run('__e.playerWealth>__base'));assert.ok(run('__sib.rel<__rel'));assert.ok(run('__sib.bonds.grudge>0'));});

test('yielding inheritance sacrifices part of player share and improves claimant relations',()=>{const {run}=game();run(setup+'s.age=35;s.monthsRemaining=12;window.__p=s.parents[0];__p.wealth=70;__p.rel=95;normalizeNPCEstate(__p).assets=["horse","flock","yurt"];if(!s.siblings.some(x=>x.alive)){const x=normalizeNPC({name:"Kardes",gender:"female",age:28,alive:true,type:"Kız kardeş",rel:60,parentIds:s.parents.map(p=>p.id),realm:s.realm,place:s.place},"Kız kardeş");s.siblings.push(x)}window.__sib=s.siblings.find(x=>x.alive);window.__rel=__sib.rel;window.__e=processNPCEstate(__p);window.__base=__e.planned.find(x=>x.heirId===s.id).wealth;inheritanceDisputeAction(__e.id,"yield")');assert.ok(run('__e.playerWealth<__base'));assert.ok(run('__sib.rel>__rel'));});

