test('v30 family conflict stores cause heat and real npc to npc damage',()=>{const {run}=game();run(setup+'s.age=30;window.__a=s.parents[0];window.__b=s.relatives.find(n=>n.alive&&n.age>=18);window.__before=socialLinkBetween(__a,__b,true,{tags:["kin"]});window.__score=__before.score;window.__grudge=__before.grudge;window.__fc=createFamilyConflict(__a,__b,"household",{heat:55,reason:"Yurt yükünün adil paylaşılmadığını düşünüyorlar."});window.__link=socialLinkBetween(__a,__b)');assert.equal(run('__fc.status'),"active");assert.equal(run('__fc.kind'),"household");assert.equal(run('__fc.heat'),55);assert.ok(run('__link.grudge>__grudge'));assert.ok(run('__link.score<__score'));assert.equal(run('activeFamilyConflicts().some(x=>x.id===__fc.id)'),true);});

