test('v30 taking a side records stance strengthens one tie and worsens the other',()=>{const {run}=game();run(setup+'s.age=30;s.monthsRemaining=12;window.__a=s.parents[0];window.__b=s.relatives.find(n=>n.alive&&n.age>=18);window.__fc=createFamilyConflict(__a,__b,"inheritance",{heat:40});window.__ar=__a.rel;window.__br=__b.rel;familyConflictAction(__fc.id,"side_a")');assert.equal(run('__fc.playerStance'),"a");assert.ok(run('__a.rel>__ar'));assert.ok(run('__b.rel<__br'));assert.ok(run('__fc.heat>40'));assert.equal(run('s.familyDynamics.sidesTaken'),1);});

test('v30 severe sided family feud can spill into public reputation instead of staying invisible',()=>{const {run}=game();run(setup+'s.age=30;window.__a=s.parents[0];window.__b=s.relatives.find(n=>n.alive&&n.age>=18);window.__fc=createFamilyConflict(__a,__b,"reputation",{heat:86});__fc.playerStance="a";__fc.public=false;Math.random=()=>0;familyDynamicsYearTick()');assert.equal(run('__fc.public'),true);assert.ok(run('activeCommunityRumors(-1).some(x=>x.kind==="family_conflict")'));});

test('v30 active family conflict surfaces as a targeted two person context event',()=>{const {run}=game();run(setup+'s.age=30;window.__a=s.parents[0];window.__b=s.relatives.find(n=>n.alive&&n.age>=18);window.__fc=createFamilyConflict(__a,__b,"care",{heat:50,reason:"Bakım yükü yüzünden anlaşamıyorlar."});window.__e=EVENT_DECK.find(x=>x.id==="family_conflict_spillover_v30");window.__sels=eventTargetSelections("familyConflictPair",__e.id);window.__ctx={targetId:__a.id,otherTargetId:__b.id}');assert.equal(run('eventRequirementOK(__e)'),true);assert.ok(run('__sels.some(x=>x.target.id===__a.id&&x.other.id===__b.id)||__sels.some(x=>x.target.id===__b.id&&x.other.id===__a.id)'));assert.ok(run('eventDisplayText(__e,__ctx).includes("Bakım yükü")'));});

test('v30 family reunion can change an existing feud instead of being cosmetic',()=>{const {run}=game();run(setup+'s.age=30;s.skills.speech=100;window.__a=s.parents[0];window.__b=s.relatives.find(n=>n.alive&&n.age>=18);__a.place=s.place;__b.place=s.place;__a.realm=s.realm;__b.realm=s.realm;window.__fc=createFamilyConflict(__a,__b,"household",{heat:55});window.__h=__fc.heat;Math.random=()=>0;window.__impact=familyDynamicsReunionImpact([__a,__b])');assert.ok(run('__fc.heat<__h'));assert.ok(run('__impact.improved>=1'));});

