 run(setup+v45Guild+"window.__d=caravanDiplomacyRecord('river','mountain');__a.rel=80;__b.rel=80;__a.bonds.trust=80;__b.bonds.trust=80;__t.competition.river.sold=2;__t.competition.mountain.sold=0;__t.competition.river.lastCycleSerial=lifeSerial();__t.competition.mountain.lastCycleSerial=lifeSerial();Math.random=()=>0;caravanDiplomacyQuarterTick(3);");
