test('v51 converts old v50 saves without invented theft and creates safety backup',()=>{const {run,storage}=game();run(setup+v50Road+"s.version=50;delete __g.convoys.loot;save();load();");assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v51'));assert.equal(run('ensureCaravanTrade().guild.convoys.loot.length'),0);});
test('v51 trade UI shows recoverable cargo with named thief and two real decisions',()=>{const {run}=game();run(setup+v51Stolen+"window.__ui=caravanConvoySummaryHtml();");assert.ok(run('__ui.includes("Çalınan Yükleri Geri Al")'));assert.ok(run('__ui.includes(__bandit.name)'));assert.ok(run('__ui.includes("Yükü karşılıkla geri al")'));assert.ok(run('__ui.includes("İz sür ve yükü geri al")'));});


/* v52 — NPC-funded trading guild inquiries and patrols. */
const v52Case=v51Stolen+"window.__officer=caravanConvoyUnderwriter(__loot.origin,__loot.dest);";
test('v52 starts without fabricated patrols',()=>{const {run}=game();run(setup+v52Case+"");assert.equal(run('s.version'),73);assert.equal(run('__g.convoys.patrolReports'),0);assert.equal(run('Object.keys(__g.convoys.patrols).length'),0);});
test('v52 tracks robbery geography and investigator',()=>{const {run}=game();run(setup+v52Case+"");assert.equal(run('__loot.origin'),'river');assert.equal(run('__loot.dest'),'mountain');assert.ok(run('__officer.alive'));});
test('v52 refuses when investigator is dead',()=>{const {run}=game();run(setup+v52Case+"__officer.alive=false;window.__why=caravanConvoyPatrolIssue(__loot.id);");assert.ok(run('__why.includes("üçüncü")'));});
test('v52 refuses when player has fewer than two coins',()=>{const {run}=game();run(setup+v52Case+"s.wealth=1;window.__m=s.monthsRemaining;window.__why=caravanConvoyPatrolIssue(__loot.id);window.__ok=caravanConvoyPatrolAction(__loot.id);");assert.equal(run('__ok'),false);assert.ok(run('__why.includes("2 servet")'));assert.equal(run('s.monthsRemaining'),run('__m'));});
test('v52 moves real investigation fee from player to independent NPC',()=>{const {run}=game();run(setup+v52Case+"window.__p=s.wealth;window.__o=__officer.wealth;window.__oldTick=monthlyTick;monthlyTick=()=>{};Math.random=()=>0;window.__ok=caravanConvoyPatrolAction(__loot.id);monthlyTick=__oldTick;");assert.equal(run('__ok'),true);assert.equal(run('s.wealth'),run('__p-2'));assert.equal(run('__officer.wealth'),run('__o+2'));assert.equal(run('__g.convoys.patrolFees'),2);});
test('v52 success creates an officer-led twelve-month patrol',()=>{const {run}=game();run(setup+v52Case+"window.__serial=lifeSerial();window.__oldTick=monthlyTick;monthlyTick=()=>{};Math.random=()=>0;window.__ok=caravanConvoyPatrolAction(__loot.id);monthlyTick=__oldTick;");assert.equal(run('__g.convoys.patrolConvictions'),1);assert.equal(run('__g.convoys.patrols.mountain.startedSerial'),run('__serial'));assert.equal(run('__g.convoys.patrols.mountain.untilSerial'),run('__serial+12'));assert.equal(run('__g.convoys.patrols.mountain.officerId'),run('__officer.id'));});
test('v52 lower road risk applies during an active market patrol',()=>{const {run}=game();run(setup+v52Case+"window.__q={origin:'river',dest:'mountain'};window.__base=caravanConvoyRisk(__q);window.__oldTick=monthlyTick;monthlyTick=()=>{};Math.random=()=>0;window.__ok=caravanConvoyPatrolAction(__loot.id);monthlyTick=__oldTick;window.__safe=caravanConvoyRisk(__q);");assert.ok(run('__safe<__base'));assert.ok(run('__safe>=.015'));});
