/* v55 — insolvency verdict, real NPC-to-NPC payments and court debt ledger. */
const v55Debt=v54Captured+"__bandit.wealth=1;window.__beforeCourtDebtCash=__seller.wealth;window.__oldTick=monthlyTick;monthlyTick=()=>{};window.__opened=caravanBanditCourtAction('debt','mountain',__loot.id);monthlyTick=__oldTick;s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;window.__debt=ensureCaravanTrade().guild.convoys.loot.find(x=>x.id===__loot.id);";
const v55Insured=v54Insured+"__robber.wealth=1;window.__oldTick=monthlyTick;monthlyTick=()=>{};window.__opened=caravanBanditCourtAction('debt','mountain',__loot.id);monthlyTick=__oldTick;s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;window.__debt=ensureCaravanTrade().guild.convoys.loot.find(x=>x.id===__loot.id);";
test('v55 empty save has zero debt counters',()=>{const {run}=game();run(setup+v52Case+"");assert.equal(run('s.version'),73);assert.equal(run('__g.convoys.courtDebtsOpened'),0);assert.equal(run('__g.convoys.courtDebtInstallments'),0);});
test('v55 cannot declare debt against a robber who has not been arrested',()=>{const {run}=game();run(setup+v52Case+"window.__issue=caravanBanditCourtIssue('debt','mountain',__loot.id);");assert.ok(run('__issue.includes("yakalanmış")'));});
test('v55 insolvency makes a valid theft debt judgment possible',()=>{const {run}=game();run(setup+v54Captured+"__bandit.wealth=1;window.__issue=caravanBanditCourtIssue('debt','mountain',__loot.id);");assert.equal(run('__issue'),'');});
test('v55 solvent bandit must pay full compensation instead of evading it through debt',()=>{const {run}=game();run(setup+v54Captured+"window.__why=caravanBanditCourtIssue('debt','mountain',__loot.id);");assert.ok(run('__why.includes("doğrudan tazminat")'));});
test('v55 court debt opening pays exactly one real coin to the seller',()=>{const {run}=game();run(setup+v55Debt+"");assert.equal(run('__opened'),true);assert.equal(run('__bandit.wealth'),0);assert.equal(run('__seller.wealth'),run('__beforeCourtDebtCash+1'));assert.equal(run('__g.convoys.courtRestitutionPaid'),1);});
test('v55 court debt ledger records total paid remaining and opening month',()=>{const {run}=game();run(setup+v55Debt+"");assert.equal(run('__debt.status'),'debt');assert.equal(run('__debt.method'),'debt');assert.equal(run('__debt.debt.total'),run('__loot.unitCost'));assert.equal(run('__debt.debt.paid'),1);assert.equal(run('__debt.debt.openedSerial'),run('lifeSerial()-1'));});
test('v55 court judgement counts exactly one civil case and one debt opening',()=>{const {run}=game();run(setup+v55Debt+"");assert.equal(run('__g.convoys.courtCases'),1);assert.equal(run('__g.convoys.courtDebtsOpened'),1);assert.equal(run('__g.convoys.courtDebtInstallments'),0);assert.equal(run('ensureCaravanTrade().guild.convoys.patrols.mountain.verdict.mode'),'debt');});
test('v55 court debt cannot create physical merchant stock or insurance claims',()=>{const {run}=game();run(setup+v55Debt+"");assert.equal(run('caravanRivalUnits(__sr)'),1);assert.equal(run('__g.convoys.claimsPaid'),0);assert.equal(run('__g.convoys.lootRecovered'),0);});
test('v55 debt claim blocks duplicate physical salvage',()=>{const {run}=game();run(setup+v55Debt+"window.__why=caravanConvoyLootIssue('track',__loot.id);");assert.ok(run('__why.includes("takip hakkı")'));});
test('v55 debt claim blocks paying ransom on same stolen goods',()=>{const {run}=game();run(setup+v55Debt+"window.__coins=s.wealth;window.__ok=caravanConvoyLootAction('ransom',__loot.id);");assert.equal(run('__ok'),false);assert.equal(run('s.wealth'),run('__coins'));});
test('v55 a court cannot open the same debt twice and duplicate first payment',()=>{const {run}=game();run(setup+v55Debt+"window.__prev=__seller.wealth;window.__ok=caravanBanditCourtAction('debt','mountain',__loot.id);");assert.equal(run('__ok'),false);assert.equal(run('__seller.wealth'),run('__prev'));assert.equal(run('__g.convoys.courtDebtsOpened'),1);});
test('v55 debtor with no available coins cannot pay another installment',()=>{const {run}=game();run(setup+v55Debt+"window.__m=s.monthsRemaining;window.__issue=caravanBanditDebtCollectIssue(__loot.id);window.__ok=caravanBanditDebtCollectAction(__loot.id);");assert.equal(run('__ok'),false);assert.ok(run('__issue.includes("serveti yok")'));assert.equal(run('s.monthsRemaining'),run('__m'));});
test('v55 collect transfers only available real debtor assets to creditor',()=>{const {run}=game();run(setup+v55Debt+"__bandit.wealth=2;window.__p=s.wealth;window.__cash=__seller.wealth;window.__oldTick=monthlyTick;monthlyTick=()=>{};window.__ok=caravanBanditDebtCollectAction(__loot.id);monthlyTick=__oldTick;");assert.equal(run('__ok'),true);assert.equal(run('__bandit.wealth'),0);assert.equal(run('__seller.wealth'),run('__cash+2'));assert.equal(run('s.wealth'),run('__p'));});
test('v55 partial installment does not clear debt prematurely',()=>{const {run}=game();run(setup+v55Debt+"__bandit.wealth=2;window.__oldTick=monthlyTick;monthlyTick=()=>{};caravanBanditDebtCollectAction(__loot.id);monthlyTick=__oldTick;");assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].status'),'debt');assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].debt.paid'),3);assert.equal(run('__g.convoys.courtDebtInstallments'),1);});
test('v55 final installment clears debt with no new loot unit',()=>{const {run}=game();run(setup+v55Debt+"__bandit.wealth=3;window.__oldTick=monthlyTick;monthlyTick=()=>{};caravanBanditDebtCollectAction(__loot.id);monthlyTick=__oldTick;");assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].status'),'compensated');assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].debt.paid'),4);assert.equal(run('__g.convoys.courtRestitutions'),1);assert.equal(run('caravanRivalUnits(__sr)'),1);});
test('v55 completed debt cannot withdraw a second installment',()=>{const {run}=game();run(setup+v55Debt+"__bandit.wealth=3;window.__oldTick=monthlyTick;monthlyTick=()=>{};caravanBanditDebtCollectAction(__loot.id);s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;window.__once=__seller.wealth;window.__again=caravanBanditDebtCollectAction(__loot.id);monthlyTick=__oldTick;");assert.equal(run('__again'),false);assert.equal(run('__seller.wealth'),run('__once'));assert.equal(run('__g.convoys.courtDebtInstallments'),1);});
test('v55 two installments reduce outstanding claim without minting cash',()=>{const {run}=game();run(setup+v55Debt+"__bandit.wealth=2;window.__oldTick=monthlyTick;monthlyTick=()=>{};caravanBanditDebtCollectAction(__loot.id);s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;__bandit.wealth=1;caravanBanditDebtCollectAction(__loot.id);monthlyTick=__oldTick;");assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].status'),'compensated');assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].debt.paid'),4);assert.equal(run('__g.convoys.courtDebtInstallments'),2);assert.equal(run('__g.convoys.courtRestitutionPaid'),4);});
test('v55 zero cash on sentencing is a valid zero-paid opening',()=>{const {run}=game();run(setup+v54Captured+"__bandit.wealth=0;window.__oldTick=monthlyTick;monthlyTick=()=>{};window.__ok=caravanBanditCourtAction('debt','mountain',__loot.id);monthlyTick=__oldTick;");assert.equal(run('__ok'),true);assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].debt.paid'),0);assert.equal(run('__g.convoys.courtRestitutionPaid'),0);});
test('v55 insurance beneficiary receives direct debt payment not original seller',()=>{const {run}=game();run(setup+v55Insured+"");assert.equal(run('__debt.recipientId'),run('__ins.id'));assert.equal(run('__g.convoys.claimsPaid'),4);assert.equal(run('__debt.status'),'debt');});
test('v55 insured installments go only to the same living underwriter',()=>{const {run}=game();run(setup+v55Insured+"__robber.wealth=3;window.__priorIns=__ins.wealth;window.__priorSeller=__seller.wealth;window.__claims=__g.convoys.claimsPaid;window.__oldTick=monthlyTick;monthlyTick=()=>{};caravanBanditDebtCollectAction(__loot.id);monthlyTick=__oldTick;");assert.equal(run('__ins.wealth'),run('__priorIns+3'));assert.equal(run('__seller.wealth'),run('__priorSeller'));assert.equal(run('__g.convoys.claimsPaid'),run('__claims'));});
test('v55 dead accused cannot be charged after death',()=>{const {run}=game();run(setup+v55Debt+"__bandit.alive=false;window.__why=caravanBanditDebtCollectIssue(__loot.id);");assert.ok(run('__why.includes("hayatta değil")'));});
test('v55 dead creditor cannot collect imaginary compensation',()=>{const {run}=game();run(setup+v55Debt+"__seller.alive=false;window.__why=caravanBanditDebtCollectIssue(__loot.id);");assert.ok(run('__why.includes("hak sahibi")'));});
test('v55 debt after its three-year window cannot be collected',()=>{const {run}=game();run(setup+v55Debt+"__debt.lostSerial=lifeSerial()-45;__debt.debt.openedSerial=lifeSerial()-37;window.__why=caravanBanditDebtCollectIssue(__loot.id);");assert.ok(run('__why.includes("üç yıllık")'));});
test('v55 fake absent court debt id is rejected',()=>{const {run}=game();run(setup+v55Debt+"window.__why=caravanBanditDebtCollectIssue('not-real');");assert.ok(run('__why.includes("bulunamadı")'));});
test('v55 unexpected collection action does not bypass access policy',()=>{const {run}=game();run(setup+v55Debt+"window.__why=accessIssue({kind:'caravanDebt',id:'print',lootId:__loot.id});");assert.ok(run('__why.includes("Bilinmeyen")'));});
test('v55 current signed debt and NPC names appear in trade user interface',()=>{const {run}=game();run(setup+v55Debt+"window.__html=caravanConvoySummaryHtml();");assert.ok(run('__html.includes("Töre Borçlarını Tahsil Et")'));assert.ok(run('__html.includes(__bandit.name)'));assert.ok(run('__html.includes("Töre borcunu tahsil et")'));});
test('v55 insolvent criminal is offered a debt judgement in court UI',()=>{const {run}=game();run(setup+v54Captured+"__bandit.wealth=1;window.__html=caravanConvoySummaryHtml();");assert.ok(run('__html.includes("borç hükmü aç")'));});
test('v55 solvent criminal still gets immediate full restitution option',()=>{const {run}=game();run(setup+v54Captured+"window.__html=caravanConvoySummaryHtml();");assert.ok(run('__html.includes("bedelini tahsil et")'));assert.equal(run('__html.includes("borç hükmü aç")'),false);});
test('v55 save load preserves open outstanding debt and named creditor',()=>{const {run}=game();run(setup+v55Debt+"window.__id=__loot.id;save();load();");assert.equal(run('ensureCaravanTrade().guild.convoys.loot.find(x=>x.id===__id).status'),'debt');assert.equal(run('ensureCaravanTrade().guild.convoys.loot.find(x=>x.id===__id).debt.paid'),1);assert.equal(run('ensureCaravanTrade().guild.convoys.patrols.mountain.verdict.mode'),'debt');});
test('v55 save load maintains closed installment ledger without reopening',()=>{const {run}=game();run(setup+v55Debt+"__bandit.wealth=3;window.__oldTick=monthlyTick;monthlyTick=()=>{};caravanBanditDebtCollectAction(__loot.id);monthlyTick=__oldTick;save();load();");assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].status'),'compensated');assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].debt.paid'),4);assert.equal(run('__g.convoys.courtDebtInstallments'),1);});
test('v55 old v54 saves migrate without inventing any court debts',()=>{const {run}=game();run(setup+v54Captured+"s.version=54;delete __g.convoys.courtDebtsOpened;delete __g.convoys.courtDebtInstallments;save();load();");assert.equal(run('s.version'),73);assert.equal(run('ensureCaravanTrade().guild.convoys.courtDebtsOpened'),0);assert.equal(run('ensureCaravanTrade().guild.convoys.courtDebtInstallments'),0);});
test('v55 invalid fraudulent court debt record cannot survive normalization',()=>{const {run}=game();run(setup+v55Debt+"ensureCaravanTrade().guild.convoys.loot[0].debt.paid=90000;ensureCaravanTrade();");assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].status'),'abandoned');});
test('v55 bad debt judgment not backed by lawful arrest is erased on load',()=>{const {run}=game();run(setup+v53Patrol+"ensureCaravanTrade().guild.convoys.patrols.mountain.verdict={mode:'debt',serial:lifeSerial(),amount:0,lootId:'fake',recipientId:'fake'};ensureCaravanTrade();");assert.equal(run('ensureCaravanTrade().guild.convoys.patrols.mountain.verdict'),null);});
test('v55 personal debt claims are not wrongly inherited by next player',()=>{const {run}=game();run(setup+v55Debt+"window.__heir=caravanInheritance(s,{assets:['caravan_share']});");assert.equal(run('__heir.guild.convoys.loot[0].status'),'abandoned');assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].status'),'debt');});


/* v56 — real guild NPC collectors with monthly capped restitution. */
