const v56Insured=v55Insured+"window.__collector=caravanDebtCollectorOfficer(__debt);window.__oldTick=monthlyTick;monthlyTick=()=>{};window.__hired=caravanDebtCollectorAction('hire',__loot.id);monthlyTick=__oldTick;s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;";
