test('v56 cannot hire for a missing or recovered claim',()=>{const {run}=game();run(setup+v52Case+"window.__why=caravanDebtCollectorIssue('hire','absent');");assert.ok(run('__why.includes("açık bir Töre borcu yok")'));});
