test('v56 hiring pays exactly two real coins to the appointed NPC',()=>{const {run}=game();run(setup+v56Hired+"");assert.equal(run('__hired'),true);assert.equal(run('__g.convoys.debtCollectorHires'),1);assert.equal(run('__g.convoys.debtCollectorFees'),2);assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].debt.collector.collectorId'),run('__collector.id'));});
test('v56 hiring is charged to player rather than creditor or debtor',()=>{const {run}=game();run(setup+v55Debt+"window.__collector=caravanDebtCollectorOfficer(__debt);window.__p=s.wealth;window.__c=__collector.wealth;window.__owner=__seller.wealth;window.__oldTick=monthlyTick;monthlyTick=()=>{};caravanDebtCollectorAction('hire',__loot.id);monthlyTick=__oldTick;");assert.equal(run('s.wealth'),run('__p-2'));assert.equal(run('__collector.wealth'),run('__c+2'));assert.equal(run('__seller.wealth'),run('__owner'));});
test('v56 cannot hire twice for the same remaining debtor debt',()=>{const {run}=game();run(setup+v56Hired+"window.__cash=s.wealth;window.__again=caravanDebtCollectorAction('hire',__loot.id);");assert.equal(run('__again'),false);assert.equal(run('s.wealth'),run('__cash'));assert.equal(run('__g.convoys.debtCollectorHires'),1);});
test('v56 monthly auto collector moves at most two real coins to creditor',()=>{const {run}=game();run(setup+v56Hired+"__bandit.wealth=3;window.__debtor=__bandit.wealth;window.__creditor=__seller.wealth;caravanDebtCollectorMonthTick();");assert.equal(run('__bandit.wealth'),run('__debtor-2'));assert.equal(run('__seller.wealth'),run('__creditor+2'));assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].debt.paid'),3);});
test('v56 one month can only trigger one automatic collection per claim',()=>{const {run}=game();run(setup+v56Hired+"__bandit.wealth=6;caravanDebtCollectorMonthTick();window.__cash=__bandit.wealth;window.__paid=__g.convoys.debtCollectorPaid;caravanDebtCollectorMonthTick();");assert.equal(run('__bandit.wealth'),run('__cash'));assert.equal(run('__g.convoys.debtCollectorPaid'),run('__paid'));assert.equal(run('__g.convoys.debtCollectorPayments'),1);});
test('v56 subsequent month collects again only when actual NPC income appears',()=>{const {run}=game();run(setup+v56Hired+"__bandit.wealth=1;caravanDebtCollectorMonthTick();s.monthsRemaining--;__bandit.wealth=2;caravanDebtCollectorMonthTick();");assert.equal(run('ensureCaravanTrade().guild.convoys.loot[0].debt.paid'),4);assert.equal(run('__g.convoys.debtCollectorPayments'),2);assert.equal(run('__g.convoys.debtCollectorPaid'),3);});
