/* v57 — elderly parents, consenting adult children, care visits and real household transfer. */
const v57Family="s.age=65;s.health=70;s.wealth=5;s.monthsRemaining=12;window.__kid=normalizeNPC({name:'Yetişkin Çocuk',age:30,gender:'female',alive:true,type:'Çocuk',rel:90,health:100,wealth:20,traits:['sadik','merhametli'],realm:s.realm,place:s.place},'Çocuk');s.children=[__kid];normalizeBonds(__kid);__kid.bonds.trust=90;ensureParenting();ensureFamilyBranches();window.__profile=ensureAdultChildProfile(__kid);window.__oldTick=monthlyTick;monthlyTick=()=>{};";
const v57Consent=v57Family+"Math.random=()=>0;window.__supportOk=adultChildAction(__kid.id,'askSupport');";
test('v57 new lives begin with no imaginary parental support',()=>{const {run}=game();run(setup+v57Family+"");assert.equal(run('s.version'),73);assert.equal(run('ensureFamilyBranches().elderPaid'),0);assert.equal(run('ensureFamilyBranches().elderVisits'),0);assert.equal(run('__profile.elderCare.active'),false);});
test('v57 one year allowance can be requested by elderly parent',()=>{const {run}=game();run(setup+v57Family+"window.__why=adultChildActionIssue(__kid.id,'askSupport');");assert.equal(run('__why'),'');});
test('v57 healthy young parent cannot exploit elderly allowance',()=>{const {run}=game();run(setup+v57Family+"s.age=45;s.health=90;window.__why=adultChildActionIssue(__kid.id,'askSupport');");assert.ok(run('__why.includes("60 yaşında")'));});
test('v57 seriously ill younger parent can request genuine help',()=>{const {run}=game();run(setup+v57Family+"s.age=45;s.health=45;window.__why=adultChildActionIssue(__kid.id,'askSupport');");assert.equal(run('__why'),'');});
test('v57 wealthy parent cannot seek needless recurring assistance',()=>{const {run}=game();run(setup+v57Family+"s.wealth=16;window.__why=adultChildActionIssue(__kid.id,'askSupport');");assert.ok(run('__why.includes("15")'));});
test('v57 adult child must have actual resources before approval',()=>{const {run}=game();run(setup+v57Family+"__kid.wealth=5;window.__why=adultChildActionIssue(__kid.id,'askSupport');");assert.ok(run('__why.includes("6 servet")'));});
test('v57 recurring family support needs child trust not just parent demand',()=>{const {run}=game();run(setup+v57Family+"__kid.bonds.trust=54;window.__why=adultChildActionIssue(__kid.id,'askSupport');");assert.ok(run('__why.includes("güven")'));});
test('v57 accepted request starts bounded twelve month financial plan',()=>{const {run}=game();run(setup+v57Consent+"");assert.equal(run('__supportOk'),true);assert.equal(run('ensureAdultChildProfile(__kid).elderCare.active'),true);assert.equal(run('ensureAdultChildProfile(__kid).elderCare.untilSerial-ensureAdultChildProfile(__kid).elderCare.startedSerial'),12);assert.equal(run('ensureFamilyBranches().elderPlans'),1);});
test('v57 accepting plan does not instantly mint or transfer wealth',()=>{const {run}=game();run(setup+v57Family+"window.__p=s.wealth;window.__w=__kid.wealth;Math.random=()=>0;adultChildAction(__kid.id,'askSupport');");assert.equal(run('s.wealth'),run('__p'));assert.equal(run('__kid.wealth'),run('__w'));});
test('v57 support request consumes one of twelve annual action rights',()=>{const {run}=game();run(setup+v57Consent+"");assert.equal(run('s.monthsRemaining'),11);assert.equal(run('ensureFamilyBranches().elderRequests'),1);});
test('v57 declined plan leaves the child free of financial obligations',()=>{const {run}=game();run(setup+v57Family+"Math.random=()=>.99;window.__p=__kid.wealth;window.__ok=adultChildAction(__kid.id,'askSupport');");assert.equal(run('__ok'),true);assert.equal(run('ensureAdultChildProfile(__kid).elderCare.active'),false);assert.equal(run('ensureFamilyBranches().elderDeclines'),1);assert.equal(run('__kid.wealth'),run('__p'));});
test('v57 cannot pressure the same child for support twice in a year',()=>{const {run}=game();run(setup+v57Consent+"window.__p=s.wealth;window.__again=adultChildAction(__kid.id,'askSupport');");assert.equal(run('__again'),false);assert.equal(run('s.wealth'),run('__p'));assert.equal(run('ensureFamilyBranches().elderRequests'),1);});
test('v57 next month moves one real coin from child to parent',()=>{const {run}=game();run(setup+v57Consent+"window.__p=s.wealth;window.__w=__kid.wealth;familyElderCareMonthTick();");assert.equal(run('s.wealth'),run('__p+1'));assert.equal(run('__kid.wealth'),run('__w-1'));assert.equal(run('ensureFamilyBranches().elderPaid'),1);});
test('v57 second tick in same month cannot pay twice',()=>{const {run}=game();run(setup+v57Consent+"familyElderCareMonthTick();window.__paid=ensureFamilyBranches().elderPaid;window.__p=s.wealth;familyElderCareMonthTick();");assert.equal(run('ensureFamilyBranches().elderPaid'),run('__paid'));assert.equal(run('s.wealth'),run('__p'));});
test('v57 next month transfers another real coin if help still needed',()=>{const {run}=game();run(setup+v57Consent+"familyElderCareMonthTick();s.monthsRemaining--;familyElderCareMonthTick();");assert.equal(run('ensureFamilyBranches().elderPaid'),2);assert.equal(run('ensureAdultChildProfile(__kid).elderCare.monthsPaid'),2);});
test('v57 parent wealthy again pauses transfer but not consent',()=>{const {run}=game();run(setup+v57Consent+"s.wealth=20;window.__cash=__kid.wealth;familyElderCareMonthTick();");assert.equal(run('__kid.wealth'),run('__cash'));assert.equal(run('ensureAdultChildProfile(__kid).elderCare.active'),true);});
test('v57 when parent becomes needy again transfers resume in next month',()=>{const {run}=game();run(setup+v57Consent+"s.wealth=20;familyElderCareMonthTick();s.wealth=10;s.monthsRemaining--;familyElderCareMonthTick();");assert.equal(run('s.wealth'),11);assert.equal(run('ensureFamilyBranches().elderPaid'),1);});
test('v57 child with fewer than two coins does not subsidize parent below reserve',()=>{const {run}=game();run(setup+v57Consent+"__kid.wealth=1;window.__cash=s.wealth;familyElderCareMonthTick();");assert.equal(run('s.wealth'),run('__cash'));assert.equal(run('__kid.wealth'),1);});
test('v57 dead adult child provides no continuing invisible income',()=>{const {run}=game();run(setup+v57Consent+"__kid.alive=false;window.__cash=s.wealth;familyElderCareMonthTick();");assert.equal(run('s.wealth'),run('__cash'));});
test('v57 age support stops after twelve months and records the ending',()=>{const {run}=game();run(setup+v57Consent+"window.__c=ensureAdultChildProfile(__kid).elderCare;__c.untilSerial=lifeSerial()-1;__c.startedSerial=__c.untilSerial-12;familyElderCareMonthTick();");assert.equal(run('ensureAdultChildProfile(__kid).elderCare.active'),false);assert.equal(run('ensureFamilyBranches().elderEnds'),1);});
test('v57 parent can voluntarily end active consent at any time',()=>{const {run}=game();run(setup+v57Consent+"window.__ok=adultChildAction(__kid.id,'endSupport');");assert.equal(run('__ok'),true);assert.equal(run('ensureAdultChildProfile(__kid).elderCare.active'),false);assert.equal(run('ensureFamilyBranches().elderEnds'),1);});
test('v57 cannot end already stopped plan again',()=>{const {run}=game();run(setup+v57Consent+"adultChildAction(__kid.id,'endSupport');window.__again=adultChildAction(__kid.id,'endSupport');");assert.equal(run('__again'),false);assert.equal(run('ensureFamilyBranches().elderEnds'),1);});
test('v57 elder health visit is available if care is needed',()=>{const {run}=game();run(setup+v57Family+"window.__issue=adultChildActionIssue(__kid.id,'askCare');");assert.equal(run('__issue'),'');});
test('v57 ill parent can request care before age fifty-five',()=>{const {run}=game();run(setup+v57Family+"s.age=40;s.health=60;window.__issue=adultChildActionIssue(__kid.id,'askCare');");assert.equal(run('__issue'),'');});
test('v57 healthy younger player cannot solicit unnecessary elder care',()=>{const {run}=game();run(setup+v57Family+"s.age=40;s.health=90;window.__issue=adultChildActionIssue(__kid.id,'askCare');");assert.ok(run('__issue.includes("55 yaşında")'));});
test('v57 near full health disallows elder care exploit',()=>{const {run}=game();run(setup+v57Family+"s.health=95;window.__issue=adultChildActionIssue(__kid.id,'askCare');");assert.ok(run('__issue.includes("ihtiyacın yok")'));});
test('v57 injured child cannot be forced into visiting parent',()=>{const {run}=game();run(setup+v57Family+"__kid.health=29;window.__issue=adultChildActionIssue(__kid.id,'askCare');");assert.ok(run('__issue.includes("sağlığı")'));});
test('v57 consenting child visit heals real elderly parent',()=>{const {run}=game();run(setup+v57Family+"window.__prior=s.health;Math.random=()=>0;window.__ok=adultChildAction(__kid.id,'askCare');");assert.equal(run('__ok'),true);assert.equal(run('s.health'),run('__prior+7'));assert.equal(run('ensureFamilyBranches().elderVisits'),1);});
test('v57 elder visit cannot mint currency or change independent child wealth',()=>{const {run}=game();run(setup+v57Family+"window.__p=s.wealth;window.__c=__kid.wealth;Math.random=()=>0;adultChildAction(__kid.id,'askCare');");assert.equal(run('s.wealth'),run('__p'));assert.equal(run('__kid.wealth'),run('__c'));});
test('v57 child has the right to refuse elder care without free recovery',()=>{const {run}=game();run(setup+v57Family+"window.__prior=s.health;Math.random=()=>.99;adultChildAction(__kid.id,'askCare');");assert.equal(run('s.health'),run('__prior'));assert.equal(run('ensureFamilyBranches().elderDeclines'),1);});
test('v57 one year permits at most one visit request per child',()=>{const {run}=game();run(setup+v57Family+"Math.random=()=>0;adultChildAction(__kid.id,'askCare');window.__again=adultChildAction(__kid.id,'askCare');");assert.equal(run('__again'),false);assert.equal(run('ensureFamilyBranches().elderVisits'),1);});
test('v57 elder support plan and care visit are separate decisions',()=>{const {run}=game();run(setup+v57Consent+"window.__issue=adultChildActionIssue(__kid.id,'askCare');Math.random=()=>0;adultChildAction(__kid.id,'askCare');");assert.equal(run('__issue'),'');assert.equal(run('ensureFamilyBranches().elderPlans'),1);assert.equal(run('ensureFamilyBranches().elderVisits'),1);});
test('v57 UI displays allowance plans, care visits and actions',()=>{const {run}=game();run(setup+v57Consent+"window.__ui=adultChildrenSummaryHtml();");assert.ok(run('__ui.includes("Hane desteğini durdur")'));assert.ok(run('__ui.includes("Yaşlılık bakımına çağır")'));assert.ok(run('__ui.includes("ebeveyne katkısı")'));});
test('v57 profile normalization rejects forged endless support plans',()=>{const {run}=game();run(setup+v57Consent+"window.__p=ensureAdultChildProfile(__kid);__p.elderCare.untilSerial+=200;ensureAdultChildProfile(__kid);");assert.equal(run('ensureAdultChildProfile(__kid).elderCare.active'),false);});
test('v57 elder consent and payments survive browser save and reload',()=>{const {run}=game();run(setup+v57Consent+"familyElderCareMonthTick();window.__kidId=__kid.id;save();load();");assert.equal(run('ensureAdultChildProfile(s.children.find(x=>x.id===__kidId)).elderCare.supportPaid'),1);assert.equal(run('ensureFamilyBranches().elderPaid'),1);});
test('v57 older v56 save safely migrates without fabricating child payments',()=>{const {run}=game();run(setup+v57Family+"s.version=56;delete s.familyBranches.children[__kid.id].elderCare;save();load();");assert.equal(run('s.version'),73);assert.equal(run('ensureFamilyBranches().elderPaid'),0);assert.equal(run('ensureAdultChildProfile(s.children[0]).elderCare.active'),false);});
test('v57 unrelated adult child support and succession flows are retained',()=>{const {run}=game();run(setup+v57Family+"window.__p=s.wealth;adultChildAction(__kid.id,'support');");assert.equal(run('__p-s.wealth'),4);assert.equal(run('ensureAdultChildProfile(__kid).supportGiven'),4);});

/* v58 — consenting sibling care council, rotating quarterly care and safe legacy saves. */
const v58Family=v57Family+"window.__kid2=normalizeNPC({name:'İkinci Yetişkin',age:28,gender:'male',alive:true,type:'Çocuk',rel:92,health:100,wealth:18,traits:['sadik','merhametli'],realm:s.realm,place:s.place},'Çocuk');normalizeBonds(__kid2);__kid2.bonds.trust=91;s.children.push(__kid2);ensureFamilyBranches();window.__profile2=ensureAdultChildProfile(__kid2);";
const v58Circle=v58Family+"Math.random=()=>0;window.__started=familyCareCircleAction('start');window.__rota=ensureFamilyBranches().careCircle;";
test('v58 new game begins without fictitious sibling care rota',()=>{const {run}=game();run(setup+v58Family+"");assert.equal(run('s.version'),73);assert.equal(run('ensureFamilyBranches().careCircle'),null);assert.equal(run('ensureFamilyBranches().careCircleVisits'),0);});
test('v58 two nearby adult children can be eligible for voluntary care',()=>{const {run}=game();run(setup+v58Family+"");assert.equal(run('familyCareCircleCandidates().length'),2);assert.equal(run('familyCareCircleIssue("start")'),'');});
test('v58 younger healthy parent cannot request sibling elderly care',()=>{const {run}=game();run(setup+v58Family+"s.age=40;s.health=90;window.__why=familyCareCircleIssue('start');");assert.ok(run('__why.includes("yaşlı")'));});
test('v58 younger seriously ill parent is eligible for care meeting',()=>{const {run}=game();run(setup+v58Family+"s.age=40;s.health=55;");assert.equal(run('familyCareCircleIssue("start")'),'');});
test('v58 near complete health prevents opportunistic rota healing',()=>{const {run}=game();run(setup+v58Family+"s.health=95;");assert.ok(run('familyCareCircleIssue("start").includes("ihtiyacın yok")'));});
test('v58 a single adult child is insufficient to establish shared duty',()=>{const {run}=game();run(setup+v58Family+"s.children=[__kid];window.__why=familyCareCircleIssue('start');");assert.ok(run('__why.includes("en az iki")'));});
test('v58 underage sibling cannot be counted as adult participant',()=>{const {run}=game();run(setup+v58Family+"__kid2.age=17;window.__why=familyCareCircleIssue('start');");assert.ok(run('__why.includes("en az iki")'));});
test('v58 sick sibling cannot be pressured to join care',()=>{const {run}=game();run(setup+v58Family+"__kid2.health=39;window.__why=familyCareCircleIssue('start');");assert.ok(run('__why.includes("en az iki")'));});
test('v58 separated town makes sibling temporarily ineligible',()=>{const {run}=game();run(setup+v58Family+"__kid2.place='uzak';window.__why=familyCareCircleIssue('start');");assert.ok(run('__why.includes("yakınında")'));});
test('v58 mistrust excludes sibling until their bonds recover',()=>{const {run}=game();run(setup+v58Family+"__kid2.bonds.trust=54;window.__why=familyCareCircleIssue('start');");assert.ok(run('__why.includes("güven")'));});
test('v58 both independent adult children may accept on own decision',()=>{const {run}=game();run(setup+v58Circle+"");assert.equal(run('__started'),true);assert.equal(run('ensureFamilyBranches().careCircles'),1);assert.equal(run('ensureFamilyBranches().careCircle.childIds.length'),2);assert.equal(run('ensureFamilyBranches().careCircle.active'),true);});
test('v58 successful council opens precisely twelve months',()=>{const {run}=game();run(setup+v58Circle+"");assert.equal(run('ensureFamilyBranches().careCircle.untilSerial-ensureFamilyBranches().careCircle.startedSerial'),12);assert.equal(run('s.monthsRemaining'),11);});
test('v58 starting council cannot generate instant health or money',()=>{const {run}=game();run(setup+v58Family+"window.__cash=s.wealth;window.__h=s.health;window.__first=__kid.wealth;window.__second=__kid2.wealth;Math.random=()=>0;familyCareCircleAction('start');");assert.equal(run('s.wealth'),run('__cash'));assert.equal(run('__kid.wealth'),run('__first'));assert.equal(run('__kid2.wealth'),run('__second'));assert.equal(run('s.health'),run('__h'));});
test('v58 first sibling may decline and prevent nonconsensual rota',()=>{const {run}=game();run(setup+v58Family+"Math.random=()=>.99;familyCareCircleAction('start');");assert.equal(run('ensureFamilyBranches().careCircle'),null);assert.equal(run('ensureFamilyBranches().careCircles'),0);assert.ok(run('ensureFamilyBranches().careCircleDeclines>=1'));});
test('v58 one consenting and one declining child do not make a rota',()=>{const {run}=game();run(setup+v58Family+"window.__count=0;Math.random=()=>[0,.99][__count++%2];familyCareCircleAction('start');");assert.equal(run('ensureFamilyBranches().careCircle'),null);assert.equal(run('ensureFamilyBranches().careCircles'),0);});
test('v58 no repeated pressure can occur within same year',()=>{const {run}=game();run(setup+v58Circle+"window.__before=s.monthsRemaining;window.__again=familyCareCircleAction('start');");assert.equal(run('__again'),false);assert.equal(run('s.monthsRemaining'),run('__before'));assert.equal(run('ensureFamilyBranches().careCircles'),1);});
test('v58 one year allows one council attempt even if everyone refused',()=>{const {run}=game();run(setup+v58Family+"Math.random=()=>.99;familyCareCircleAction('start');window.__try=familyCareCircleAction('start');");assert.equal(run('__try'),false);assert.equal(run('ensureFamilyBranches().lastCareCircleYear'),run('s.year+s.age'));});
test('v58 first quarterly sibling visit heals parent with a real care burden',()=>{const {run}=game();run(setup+v58Circle+"s.monthsRemaining=9;familyCareCircleMonthTick();");assert.equal(run('s.health'),73);assert.equal(run('__kid.health'),99);assert.equal(run('__kid2.health'),100);assert.equal(run('ensureFamilyBranches().careCircleVisits'),1);});
test('v58 second quarterly visit rotates duty to second sibling',()=>{const {run}=game();run(setup+v58Circle+"s.monthsRemaining=9;familyCareCircleMonthTick();s.monthsRemaining=6;familyCareCircleMonthTick();");assert.equal(run('ensureAdultChildProfile(__kid).elderCare.sharedVisits'),1);assert.equal(run('ensureAdultChildProfile(__kid2).elderCare.sharedVisits'),1);assert.equal(run('ensureFamilyBranches().careCircleVisits'),2);});
test('v58 third quarter returns turn to first volunteer',()=>{const {run}=game();run(setup+v58Circle+"for(const m of [9,6,3]){s.monthsRemaining=m;familyCareCircleMonthTick();}");assert.equal(run('ensureAdultChildProfile(__kid).elderCare.sharedVisits'),2);assert.equal(run('ensureAdultChildProfile(__kid2).elderCare.sharedVisits'),1);});
test('v58 same quarterly month cannot repeat healing twice',()=>{const {run}=game();run(setup+v58Circle+"s.monthsRemaining=9;familyCareCircleMonthTick();window.__h=s.health;window.__counter=ensureFamilyBranches().careCircleVisits;familyCareCircleMonthTick();");assert.equal(run('s.health'),run('__h'));assert.equal(run('ensureFamilyBranches().careCircleVisits'),run('__counter'));});
test('v58 not due month produces no visit or NPC fatigue',()=>{const {run}=game();run(setup+v58Circle+"s.monthsRemaining=10;familyCareCircleMonthTick();");assert.equal(run('ensureFamilyBranches().careCircleVisits'),0);assert.equal(run('__kid.health'),100);});
test('v58 sick first child lets second sibling cover the quarter',()=>{const {run}=game();run(setup+v58Circle+"__kid.health=39;s.monthsRemaining=9;familyCareCircleMonthTick();");assert.equal(run('ensureAdultChildProfile(__kid).elderCare.sharedVisits'),0);assert.equal(run('ensureAdultChildProfile(__kid2).elderCare.sharedVisits'),1);});
test('v58 distant first child does not get forced into caregiving',()=>{const {run}=game();run(setup+v58Circle+"__kid.place='distant';s.monthsRemaining=9;familyCareCircleMonthTick();");assert.equal(run('ensureAdultChildProfile(__kid2).elderCare.sharedVisits'),1);assert.equal(run('__kid.health'),100);});
test('v58 both absent children cause skipped visit rather than magical recovery',()=>{const {run}=game();run(setup+v58Circle+"__kid.place='distant';__kid2.place='distant';s.monthsRemaining=9;window.__prior=s.health;familyCareCircleMonthTick();");assert.equal(run('s.health'),run('__prior'));assert.equal(run('ensureFamilyBranches().careCircleMissed'),1);});
test('v58 full-health parent receives no unnecessary extra healing',()=>{const {run}=game();run(setup+v58Circle+"s.health=100;s.monthsRemaining=9;window.__prior=__kid.health;familyCareCircleMonthTick();");assert.equal(run('s.health'),100);assert.equal(run('__kid.health'),run('__prior'));assert.equal(run('ensureFamilyBranches().careCircleMissed'),1);});
test('v58 loss of a participating sibling closes shared rota',()=>{const {run}=game();run(setup+v58Circle+"__kid2.alive=false;s.monthsRemaining=9;familyCareCircleMonthTick();");assert.equal(run('ensureFamilyBranches().careCircle.active'),false);assert.equal(run('ensureFamilyBranches().careCircleEnds'),1);assert.equal(run('ensureFamilyBranches().careCircleVisits'),0);});
test('v58 expired rota no longer heals the parent',()=>{const {run}=game();run(setup+v58Circle+"s.monthsRemaining=0;window.__end=ensureFamilyBranches().careCircle;__end.startedSerial=lifeSerial()-13;__end.untilSerial=__end.startedSerial+12;window.__h=s.health;familyCareCircleMonthTick();");assert.equal(run('ensureFamilyBranches().careCircle.active'),false);assert.equal(run('s.health'),run('__h'));});
