test('v58 sibling care keeps ordinary financial allowance entirely separate',()=>{const {run}=game();run(setup+v58Circle+"window.__p=s.wealth;window.__first=__kid.wealth;s.monthsRemaining=9;familyCareCircleMonthTick();");assert.equal(run('s.wealth'),run('__p'));assert.equal(run('__kid.wealth'),run('__first'));assert.equal(run('ensureFamilyBranches().elderPaid'),0);});
