test('v58 version 57 save migrates without inventing care rota',()=>{const {run}=game();run(setup+v58Family+"s.version=57;delete s.familyBranches.careCircle;delete s.familyBranches.careCircleVisits;save();load();");assert.equal(run('s.version'),73);assert.equal(run('ensureFamilyBranches().careCircle'),null);assert.equal(run('ensureFamilyBranches().careCircleVisits'),0);});
test('v58 fraudulent duration is rejected during normalization',()=>{const {run}=game();run(setup+v58Circle+"ensureFamilyBranches().careCircle.untilSerial+=120;ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().careCircle'),null);});
test('v58 duplicate participants in a tampered rota cannot become a real plan',()=>{const {run}=game();run(setup+v58Circle+"ensureFamilyBranches().careCircle.childIds=[__kid.id,__kid.id];ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().careCircle'),null);});
test('v58 existing v57 support remains valid alongside v58 care circle',()=>{const {run}=game();run(setup+v58Family+"window.__oldTick=monthlyTick;monthlyTick=()=>{};Math.random=()=>0;adultChildAction(__kid.id,'askSupport');monthlyTick=__oldTick;s.pendingEventId=null;s.pendingDecision=null;s.pendingEventContext=null;window.__worked=familyCareCircleAction('start');");assert.equal(run('__worked'),true);assert.equal(run('ensureFamilyBranches().careCircle.active'),true);assert.equal(run('ensureAdultChildProfile(__kid).elderCare.active'),true);});


/* v59 — cumulative care load, inter-sibling relationship costs and voluntary relief. */
const v59Circle=v58Circle;
const v59Unfair=v59Circle+"__kid2.health=39;for(const m of [9,6]){s.monthsRemaining=m;familyCareCircleMonthTick();}";
test('v59 fresh lives begin at save version 59 with no elder fatigue',()=>{const {run}=game();run(setup+v58Family);assert.equal(run('s.version'),73);assert.equal(run('ensureAdultChildProfile(__kid).elderCare.careFatigue'),0);});
test('v59 voluntary rota begins without invented shifts or dispute',()=>{const {run}=game();run(setup+v59Circle);assert.equal(run('ensureFamilyBranches().careCircle.visitsByChild[__kid.id]'),0);assert.equal(run('ensureFamilyBranches().careCircle.disputeOpen'),false);});
test('v59 first quarterly visit increases strain only for the actual caregiver',()=>{const {run}=game();run(setup+v59Circle+"s.monthsRemaining=9;familyCareCircleMonthTick();");assert.equal(run('ensureAdultChildProfile(__kid).elderCare.careFatigue'),18);assert.equal(run('ensureAdultChildProfile(__kid2).elderCare.careFatigue'),0);});
test('v59 fair second shift does not create false sibling conflict',()=>{const {run}=game();run(setup+v59Circle+"for(const m of [9,6]){s.monthsRemaining=m;familyCareCircleMonthTick();}");assert.equal(run('ensureFamilyBranches().careCircleDisputes'),0);assert.equal(run('ensureFamilyBranches().careCircle.visitsByChild[__kid2.id]'),1);});
test('v59 sick sibling can be skipped but creates two to zero duty imbalance',()=>{const {run}=game();run(setup+v59Unfair);assert.equal(run('ensureFamilyBranches().careCircle.visitsByChild[__kid.id]'),2);assert.equal(run('ensureFamilyBranches().careCircle.visitsByChild[__kid2.id]'),0);assert.equal(run('ensureFamilyBranches().careCircleDisputes'),1);});
test('v59 uneven caregiving opens a persistent family dispute',()=>{const {run}=game();run(setup+v59Unfair);assert.equal(run('ensureFamilyBranches().careCircle.disputeOpen'),true);assert.ok(run('ensureFamilyBranches().history.some(h=>h.type==="care_circle_dispute")'));});
test('v59 same month cannot trigger a second dispute or second visit',()=>{const {run}=game();run(setup+v59Unfair+"familyCareCircleMonthTick();");assert.equal(run('ensureFamilyBranches().careCircleDisputes'),1);assert.equal(run('ensureFamilyBranches().careCircleVisits'),2);});
test('v59 mediation is unavailable before genuine unequal shifts',()=>{const {run}=game();run(setup+v59Circle+"window.__m=s.monthsRemaining;window.__ok=familyCareCircleAction('mediate');");assert.equal(run('__ok'),false);assert.equal(run('s.monthsRemaining'),run('__m'));});
test('v59 mediation consumes a month and resolves actual dispute',()=>{const {run}=game();run(setup+v59Unfair+"window.__m=s.monthsRemaining;window.__ok=familyCareCircleAction('mediate');");assert.equal(run('__ok'),true);assert.equal(run('s.monthsRemaining'),run('__m-1'));assert.equal(run('ensureFamilyBranches().careCircle.disputeOpen'),false);assert.equal(run('ensureFamilyBranches().careCircleMediations'),1);});
test('v59 mediation restores some trust without changing participant consent',()=>{const {run}=game();run(setup+v59Unfair+"window.__before=__kid.bonds.trust;familyCareCircleAction('mediate');");assert.ok(run('__kid.bonds.trust>=__before'));assert.equal(run('ensureFamilyBranches().careCircle.childIds.length'),2);});
test('v59 one rota cannot yield repeat mediation rewards',()=>{const {run}=game();run(setup+v59Unfair+"familyCareCircleAction('mediate');window.__again=familyCareCircleAction('mediate');");assert.equal(run('__again'),false);assert.equal(run('ensureFamilyBranches().careCircleMediations'),1);});
test('v59 overworked child gets optional funded respite',()=>{const {run}=game();run(setup+v59Circle+"s.monthsRemaining=9;familyCareCircleMonthTick();window.__before=s.wealth;window.__ok=familyCareCircleAction('respite',__kid.id);");assert.equal(run('__ok'),true);assert.equal(run('s.wealth'),run('__before-3'));assert.equal(run('ensureAdultChildProfile(__kid).elderCare.careFatigue'),0);assert.equal(run('ensureFamilyBranches().careCircleRespite'),1);});
test('v59 respite cannot be bought for unburdened child',()=>{const {run}=game();run(setup+v59Circle+"window.__before=s.wealth;window.__ok=familyCareCircleAction('respite',__kid2.id);");assert.equal(run('__ok'),false);assert.equal(run('s.wealth'),run('__before'));});
test('v59 respite cannot be bought for unrelated or forged child IDs',()=>{const {run}=game();run(setup+v59Circle+"window.__ok=familyCareCircleAction('respite','not-a-child');");assert.equal(run('__ok'),false);assert.equal(run('ensureFamilyBranches().careCircleRespite'),0);});
test('v59 respite cannot duplicate payment in the same year',()=>{const {run}=game();run(setup+v59Circle+"s.monthsRemaining=9;familyCareCircleMonthTick();familyCareCircleAction('respite',__kid.id);window.__before=s.wealth;window.__again=familyCareCircleAction('respite',__kid.id);");assert.equal(run('__again'),false);assert.equal(run('s.wealth'),run('__before'));});
test('v59 respite requires actual parental funds and does not mint child money',()=>{const {run}=game();run(setup+v59Circle+"s.monthsRemaining=9;familyCareCircleMonthTick();s.wealth=2;window.__before=__kid.wealth;window.__ok=familyCareCircleAction('respite',__kid.id);");assert.equal(run('__ok'),false);assert.equal(run('s.wealth'),2);assert.equal(run('__kid.wealth'),run('__before'));});
test('v59 exhausted but healthy sibling is never coerced into a shift',()=>{const {run}=game();run(setup+v59Circle+"ensureAdultChildProfile(__kid).elderCare.careFatigue=70;s.monthsRemaining=9;familyCareCircleMonthTick();");assert.equal(run('ensureAdultChildProfile(__kid).elderCare.sharedVisits'),0);assert.equal(run('ensureAdultChildProfile(__kid2).elderCare.sharedVisits'),1);});
test('v59 rest recovery occurs once in each quarter after rota stops',()=>{const {run}=game();run(setup+v59Circle+"ensureAdultChildProfile(__kid).elderCare.careFatigue=40;familyCareCircleAction('stop');s.monthsRemaining=9;familyCareCircleMonthTick();window.__once=ensureAdultChildProfile(__kid).elderCare.careFatigue;familyCareCircleMonthTick();");assert.equal(run('__once'),36);assert.equal(run('ensureAdultChildProfile(__kid).elderCare.careFatigue'),36);});
test('v59 family UI exposes child load, fatigue and mediation after an unfair shift',()=>{const {run}=game();run(setup+v59Unfair+"window.__html=adultChildrenSummaryHtml();");assert.ok(run('__html.includes("yorgunluk")'));assert.ok(run('__html.includes("arabuluculuk yap")'));assert.ok(run('__html.includes("Dinlenme desteği")'));});
test('v59 tampered negative duty counters normalize to zero',()=>{const {run}=game();run(setup+v59Circle+"ensureFamilyBranches().careCircle.visitsByChild[__kid.id]=-9;ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().careCircle.visitsByChild[__kid.id]'),0);});
test('v59 previous v58 saves migrate with separate backup and no fabricated conflict',()=>{const {run,storage}=game();run(setup+v59Circle+"s.version=58;delete s.familyBranches.careCircle.visitsByChild;delete s.familyBranches.careCircle.disputeOpen;save();load();");assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v59'));assert.equal(run('ensureFamilyBranches().careCircleDisputes'),0);assert.equal(run('ensureFamilyBranches().careCircle.disputeOpen'),false);});
test('v59 save load retains caregiver fatigue, duty record and mediator eligibility',()=>{const {run}=game();run(setup+v59Unfair+"window.__id=__kid.id;save();load();");assert.equal(run('ensureFamilyBranches().careCircle.visitsByChild[__id]'),2);assert.equal(run('ensureFamilyBranches().careCircle.disputeOpen'),true);assert.ok(run('ensureAdultChildProfile(s.children.find(c=>c.id===__id)).elderCare.careFatigue>0'));});

/* v60 — family care aftershocks, will reactions and persistence. */
const v60Unfair=v59Unfair+"familyCareCircleAction('stop');window.__legacy=ensureFamilyBranches().careLegacies[0];";
const v60Balanced=v59Circle+"for(const m of [9,6]){s.monthsRemaining=m;familyCareCircleMonthTick();}familyCareCircleAction('stop');window.__legacy=ensureFamilyBranches().careLegacies[0];";
test("v60 fresh family life has empty archive",()=>{const {run,storage}=game();run(setup+v58Family+"");assert.equal(run('s.version'),73);assert.equal(run('ensureFamilyBranches().careLegacies.length'),0);});
test("v60 manual rota closure records real participant IDs and contributions",()=>{const {run,storage}=game();run(setup+v60Unfair+"");assert.equal(run('__legacy.visitsByChild[__kid.id]'),2);assert.equal(run('__legacy.visitsByChild[__kid2.id]'),0);});
test("v60 unmediated dispute survives after care closes",()=>{const {run,storage}=game();run(setup+v60Unfair+"");assert.equal(run('__legacy.status'),'tense');assert.equal(run('ensureFamilyBranches().careCircle.active'),false);});
test("v60 equally shared care has settled memory",()=>{const {run,storage}=game();run(setup+v60Balanced+"");assert.equal(run('__legacy.status'),'settled');assert.equal(run('ensureFamilyBranches().careCircleDisputes'),0);});
test("v60 same rota cannot produce duplicate archives",()=>{const {run,storage}=game();run(setup+v60Unfair+"familyCareLegacyClose('again');familyCareLegacyClose('again');");assert.equal(run('ensureFamilyBranches().careLegacies.length'),1);});
test("v60 archival action never mints currency",()=>{const {run,storage}=game();run(setup+v59Unfair+"window.__old=s.wealth;familyCareCircleAction('stop');");assert.equal(run('s.wealth'),run('__old'));});
test("v60 expired rota is archived",()=>{const {run,storage}=game();run(setup+v59Unfair+"window.__r=ensureFamilyBranches().careCircle;__r.startedSerial=lifeSerial()-13;__r.untilSerial=__r.startedSerial+12;familyCareCircleMonthTick();");assert.equal(run('ensureFamilyBranches().careLegacies[0].status'),'tense');});
test("v60 lost co-volunteer closes rota with archived contributions",()=>{const {run,storage}=game();run(setup+v59Unfair+"__kid2.alive=false;s.monthsRemaining=3;familyCareCircleMonthTick();");assert.equal(run('ensureFamilyBranches().careLegacies.length'),1);});
test("v60 sibling relation decays after a year of unresolved care tension",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__trust=socialLinkBetween(__kid,__kid2,true).trust;s.age++;familyCareLegacyYearTick();");assert.ok(run('socialLinkBetween(__kid,__kid2,true).trust<__trust'));});
test("v60 only one annual aftereffect per calendar year",()=>{const {run,storage}=game();run(setup+v60Unfair+"s.age++;familyCareLegacyYearTick();window.__trust=socialLinkBetween(__kid,__kid2,true).trust;familyCareLegacyYearTick();");assert.equal(run('socialLinkBetween(__kid,__kid2,true).trust'),run('__trust'));});
test("v60 aftershocks end after three years",()=>{const {run,storage}=game();run(setup+v60Unfair+"for(let i=0;i<5;i++){s.age++;familyCareLegacyYearTick();}");assert.equal(run('ensureFamilyBranches().careLegacies[0].status'),'lasting');});
test("v60 lasting memory causes no automatic fourth-year damage",()=>{const {run,storage}=game();run(setup+v60Unfair+"for(let i=0;i<5;i++){s.age++;familyCareLegacyYearTick();}window.__trust=socialLinkBetween(__kid,__kid2,true).trust;s.age++;familyCareLegacyYearTick();");assert.equal(run('socialLinkBetween(__kid,__kid2,true).trust'),run('__trust'));});
test("v60 deceased participant cannot be penalized",()=>{const {run,storage}=game();run(setup+v60Unfair+"__kid2.alive=false;s.age++;familyCareLegacyYearTick();");assert.equal(run('ensureFamilyBranches().careLegacies[0].status'),'bereaved');});
test("v60 family view shows past contributions",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__html=adultChildrenSummaryHtml();");assert.ok(run('__html.includes("Bakım Emeğinin Aile Hatırası")'));assert.ok(run('__html.includes("2 nöbet")'));});
test("v60 family view offers voluntary late conversation",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__html=adultChildrenSummaryHtml();");assert.ok(run('__html.includes("Eski bakım kırgınlığını konuş")'));});
test("v60 unknown late conversation mode fails access check",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__err=accessIssue({kind:'familyCareLegacy',legacyId:__legacy.id,id:'forced'});");assert.ok(run('__err.includes("Bilinmeyen")'));});
test("v60 missing legacy ID cannot consume month",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__old=s.monthsRemaining;window.__ok=familyCareLegacyAction('fake');");assert.equal(run('__ok'),false);assert.equal(run('s.monthsRemaining'),run('__old'));});
test("v60 distant participant cannot be teleported into family meeting",()=>{const {run,storage}=game();run(setup+v60Unfair+"__kid2.place='away';window.__err=familyCareLegacyIssue(__legacy.id);");assert.ok(run('__err.includes("aynı yerde")'));});
test("v60 mutual choice can settle lasting grievance",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__ok=familyCareLegacyAction(__legacy.id);");assert.equal(run('__ok'),true);assert.equal(run('ensureFamilyBranches().careLegacies[0].status'),'settled');});
test("v60 consensual family dialogue improves harmony",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__old=ensureSuccession().familyHarmony;familyCareLegacyAction(__legacy.id);");assert.equal(run('ensureSuccession().familyHarmony'),run('__old+3'));});
test("v60 late reconciliation spends exactly one monthly action",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__old=s.monthsRemaining;familyCareLegacyAction(__legacy.id);");assert.equal(run('s.monthsRemaining'),run('__old-1'));});
test("v60 repeated settlement cannot farm points",()=>{const {run,storage}=game();run(setup+v60Unfair+"familyCareLegacyAction(__legacy.id);window.__h=ensureSuccession().familyHarmony;window.__repeat=familyCareLegacyAction(__legacy.id);");assert.equal(run('__repeat'),false);assert.equal(run('ensureSuccession().familyHarmony'),run('__h'));});
test("v60 refusal is recorded and not mistaken for consent",()=>{const {run,storage}=game();run(setup+v60Unfair+"Math.random=()=>.99;window.__h=ensureSuccession().familyHarmony;familyCareLegacyAction(__legacy.id);");assert.equal(run('ensureFamilyBranches().careLegacies[0].status'),'tense');assert.equal(run('ensureSuccession().familyHarmony'),run('__h'));});
test("v60 declined invitation can be retried next year only",()=>{const {run,storage}=game();run(setup+v60Unfair+"Math.random=()=>.99;familyCareLegacyAction(__legacy.id);window.__repeat=familyCareLegacyAction(__legacy.id);");assert.equal(run('__repeat'),false);});
test("v60 settlement prevents future aftershocks",()=>{const {run,storage}=game();run(setup+v60Unfair+"familyCareLegacyAction(__legacy.id);window.__trust=socialLinkBetween(__kid,__kid2,true).trust;s.age++;familyCareLegacyYearTick();");assert.equal(run('socialLinkBetween(__kid,__kid2,true).trust'),run('__trust'));});
test("v60 ignoring primary caregiver in will lowers trust",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__trust=__kid.bonds.trust;setWill(__kid2.id);");assert.ok(run('__kid.bonds.trust<__trust'));assert.ok(run('ensureFamilyBranches().history.some(h=>h.type==="care_legacy_will")'));});
test("v60 rewarding contributor keeps real will and wealth unchanged",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__money=s.wealth;setWill(__kid.id);");assert.equal(run('s.wealth'),run('__money'));assert.equal(run('s.will'),run('__kid.id'));});
test("v60 equal will choice is respected",()=>{const {run,storage}=game();run(setup+v60Unfair+"setWill('equal');");assert.equal(run('s.will'),'equal');assert.equal(run('ensureFamilyBranches().careLegacies[0].lastWillYear'),run('s.year+s.age'));});
test("v60 one legacy can react to will only once per year",()=>{const {run,storage}=game();run(setup+v60Unfair+"setWill(__kid2.id);window.__trust=__kid.bonds.trust;setWill(__kid2.id);");assert.equal(run('__kid.bonds.trust'),run('__trust'));assert.equal(run('ensureFamilyBranches().history.filter(h=>h.type==="care_legacy_will").length'),1);});
test("v60 ordinary will behavior unaffected without grievance",()=>{const {run,storage}=game();run(setup+v60Balanced+"window.__h=ensureSuccession().familyHarmony;setWill(__kid.id);");assert.equal(run('ensureSuccession().familyHarmony'),run('__h-2'));});
test("v60 save reload retains years and duties",()=>{const {run,storage}=game();run(setup+v60Unfair+"window.__id=__kid.id;save();load();");assert.equal(run('ensureFamilyBranches().careLegacies[0].visitsByChild[__id]'),2);assert.equal(run('ensureFamilyBranches().careLegacies[0].status'),'tense');});
test("v60 v59 migration creates v60 backup",()=>{const {run,storage}=game();run(setup+v60Unfair+"s.version=59;save();load();");assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v60'));});
test("v60 inactive v59 rota converts into legacy",()=>{const {run,storage}=game();run(setup+v60Unfair+"s.version=59;delete s.familyBranches.careLegacies;save();load();");assert.equal(run('ensureFamilyBranches().careLegacies[0].status'),'tense');});
test("v60 malformed duplicate participant record is rejected",()=>{const {run,storage}=game();run(setup+v60Unfair+"ensureFamilyBranches().careLegacies[0].childIds=[__kid.id,__kid.id];ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().careLegacies.length'),0);});
test("v60 death record contains archived care work",()=>{const {run,storage}=game();run(setup+v60Unfair+"die();");assert.equal(run('s.deathRecord.familyCareLegacy[0].status'),'tense');});
test("v60 chosen heir inherits memory of parent care",()=>{const {run,storage}=game();run(setup+v60Unfair+"die();continueAsHeir(0);");assert.equal(run('s.lastInheritance.familyCareLegacy[0].visitsByChild[__kid.id]'),2);});


/* v61 — autonomous NPC siblings and ancestral caregiving memory */
const v61Sibling=v58Family+"Math.random=()=>0;";
const v61Ancestry=v60Unfair+"__kid.descendants=[normalizeNPC({id:'grand_v61',name:'Genç Torun',age:8,gender:'female',alive:true,type:'Çocuk',rel:80,health:100,realm:s.realm,place:s.place},'Çocuk')];die();continueAsHeir(0);window.__junior=s.children[0];window.__relative=s.siblings[0];";
test("v61 new saves use 61 and old archives remain empty",()=>{const {run,storage}=game();run(setup+v61Sibling+"");assert.equal(run('s.version'),73);assert.equal(run('ensureFamilyBranches().siblingBonds.length'),0);});
test("v61 siblings autonomously help each other",()=>{const {run,storage}=game();run(setup+v61Sibling+"familySiblingYearTick();");assert.equal(run('ensureFamilyBranches().siblingBonds[0].cooperation'),1);});
test("v61 autonomous support changes real NPC social score",()=>{const {run,storage}=game();run(setup+v61Sibling+"familySiblingYearTick();");assert.equal(run('socialLinkBetween(__kid,__kid2).score'),4);});
test("v61 support changes NPC trust too",()=>{const {run,storage}=game();run(setup+v61Sibling+"familySiblingYearTick();");assert.equal(run('socialLinkBetween(__kid,__kid2).trust'),53);});
test("v61 support writes a family timeline event",()=>{const {run,storage}=game();run(setup+v61Sibling+"familySiblingYearTick();");assert.equal(run('ensureFamilyBranches().history[0].type'),'sibling_support');});
test("v61 pair is processed only once in same year",()=>{const {run,storage}=game();run(setup+v61Sibling+"familySiblingYearTick();familySiblingYearTick();");assert.equal(run('ensureFamilyBranches().siblingBonds[0].cooperation'),1);});
test("v61 pair can have another independent experience next year",()=>{const {run,storage}=game();run(setup+v61Sibling+"familySiblingYearTick();s.age++;familySiblingYearTick();");assert.equal(run('ensureFamilyBranches().siblingBonds[0].cooperation'),2);});
test("v61 refusal to engage produces no invented relationship event",()=>{const {run,storage}=game();run(setup+v61Sibling+"Math.random=()=>1;familySiblingYearTick();");assert.equal(run('ensureFamilyBranches().siblingBonds[0].cooperation'),0);assert.equal(run('ensureFamilyBranches().siblingBonds[0].rivalry'),0);});
test("v61 a refusal also consumes that year's spontaneous opportunity",()=>{const {run,storage}=game();run(setup+v61Sibling+"Math.random=()=>1;familySiblingYearTick();Math.random=()=>0;familySiblingYearTick();");assert.equal(run('ensureFamilyBranches().siblingBonds[0].cooperation'),0);});
test("v61 a voluntary quarrel affects actual trust",()=>{const {run,storage}=game();run(setup+v61Sibling+"Math.random=(()=>{let q=[0,.99];return ()=>q.shift()??0;})();familySiblingYearTick();");assert.equal(run('ensureFamilyBranches().siblingBonds[0].rivalry'),1);assert.equal(run('socialLinkBetween(__kid,__kid2).trust'),47);});
test("v61 quarrel keeps meaningful relationship memory",()=>{const {run,storage}=game();run(setup+v61Sibling+"Math.random=(()=>{let q=[0,.99];return ()=>q.shift()??0;})();familySiblingYearTick();");assert.ok(run('ensureFamilyBranches().history.some(r=>r.type==="sibling_rivalry")'));});
