test("v61 inheriting a life carries archived care story",()=>{const {run,storage}=game();run(setup+v61Ancestry+"");assert.equal(run('ensureFamilyBranches().ancestralCare.records[0].visitsByChild[s.id]'),2);});
test("v61 inheriting story retains original ancestor identity",()=>{const {run,storage}=game();run(setup+v61Ancestry+"");assert.equal(run('ensureFamilyBranches().ancestralCare.originName'),run('s.lastInheritance.from'));});
test("v61 child eight years old learns family story once",()=>{const {run,storage}=game();run(setup+v61Ancestry+"familyAncestralMemoryYearTick();");assert.equal(run('ensureFamilyBranches().ancestralCare.stories'),1);});
test("v61 younger descendants cannot receive story before eight",()=>{const {run,storage}=game();run(setup+v61Ancestry+"__junior.age=7;familyAncestralMemoryYearTick();");assert.equal(run('ensureFamilyBranches().ancestralCare.stories'),0);});
test("v61 distant aunt cannot influence child through ancestral story",()=>{const {run,storage}=game();run(setup+v61Ancestry+"__relative.place='distant';familyAncestralMemoryYearTick();");assert.equal(run('ensureFamilyBranches().ancestralCare.stories'),0);});
test("v61 deceased uncle cannot share an ancestor story",()=>{const {run,storage}=game();run(setup+v61Ancestry+"__relative.alive=false;familyAncestralMemoryYearTick();");assert.equal(run('ensureFamilyBranches().ancestralCare.stories'),0);});
test("v61 unresolved past may lower younger generations kin trust",()=>{const {run,storage}=game();run(setup+v61Ancestry+"window.__trust=socialLinkBetween(__junior,__relative,true).trust;familyAncestralMemoryYearTick();");assert.equal(run('socialLinkBetween(__junior,__relative).trust'),run('__trust-2'));});
test("v61 remembered elderly help can improve aunt and child bond",()=>{const {run,storage}=game();run(setup+v61Ancestry+"window.__ac=ensureFamilyBranches().ancestralCare;__ac.records[0].visitsByChild[s.id]=0;__ac.records[0].visitsByChild[__relative.id]=2;window.__trust=socialLinkBetween(__junior,__relative,true).trust;familyAncestralMemoryYearTick();");assert.equal(run('socialLinkBetween(__junior,__relative).trust'),run('__trust+4'));});
test("v61 no second story in same year",()=>{const {run,storage}=game();run(setup+v61Ancestry+"familyAncestralMemoryYearTick();familyAncestralMemoryYearTick();");assert.equal(run('ensureFamilyBranches().ancestralCare.stories'),1);});
test("v61 no repeated same story years later",()=>{const {run,storage}=game();run(setup+v61Ancestry+"familyAncestralMemoryYearTick();s.age++;familyAncestralMemoryYearTick();");assert.equal(run('ensureFamilyBranches().ancestralCare.stories'),1);});
test("v61 storytelling never mints wealth or assets",()=>{const {run,storage}=game();run(setup+v61Ancestry+"window.__m=s.wealth;window.__assets=s.assets.length;familyAncestralMemoryYearTick();");assert.equal(run('s.wealth'),run('__m'));assert.equal(run('s.assets.length'),run('__assets'));});
test("v61 family screen shows generational ancestry",()=>{const {run,storage}=game();run(setup+v61Ancestry+"familyAncestralMemoryYearTick();window.__panel=familyGenerationsSummaryHtml();");assert.ok(run('__panel.includes("Atalardan Gelen Bakım Hikâyeleri")'));assert.ok(run('__panel.includes("anlatılan 1")'));});
test("v61 save reload retains sibling annual achievements",()=>{const {run,storage}=game();run(setup+v61Sibling+"familySiblingYearTick();save();load();");assert.equal(run('ensureFamilyBranches().siblingBonds[0].cooperation'),1);});
test("v61 save reload retains ancestral taught IDs",()=>{const {run,storage}=game();run(setup+v61Ancestry+"familyAncestralMemoryYearTick();save();load();");assert.equal(run('ensureFamilyBranches().ancestralCare.toldToIds.length'),1);});
test("v61 old v60 saves migrate into v61 safely",()=>{const {run,storage}=game();run(setup+v61Sibling+"s.version=60;save();load();");assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v61'));});
test("v61 malformed sibling bonds are filtered on normalization",()=>{const {run,storage}=game();run(setup+v61Sibling+"s.familyBranches.siblingBonds=[{aId:'same',bId:'same'},{aId:'a',bId:'b',cooperation:-6}];ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().siblingBonds.length'),1);assert.equal(run('ensureFamilyBranches().siblingBonds[0].cooperation'),0);});
test("v61 missing ancestor archive remains valid",()=>{const {run,storage}=game();run(setup+v61Sibling+"familyAncestralMemoryYearTick();");assert.equal(run('ensureFamilyBranches().ancestralCare'),null);});
test("v61 ancestral memories stay identity bound across normalization",()=>{const {run,storage}=game();run(setup+v61Ancestry+"familyAncestralMemoryYearTick();ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().ancestralCare.toldToIds[0]'),run('__junior.id'));});


/* v62: sibling wealth, gifts, debt payments, player guarantee and save migration. */
const v62Base=v58Family+"s.age=65;__kid.wealth=20;__kid2.wealth=2;Math.random=()=>0;";
const v62Loan=v62Base+"familySiblingEconomyYearTick();window.__loan=ensureFamilyBranches().siblingEconomy.loans[0];";
const v62Gift=v58Family+"s.age=65;__kid.wealth=20;__kid2.wealth=0;Math.random=()=>0;familySiblingEconomyYearTick();";
const v62Decline=v62Base+"Math.random=()=>.99;familySiblingEconomyYearTick();";
test("v62 new game has v62 empty economy",()=>{const {run,storage}=game();run(setup+v58Family+"");assert.equal(run('s.version'),73);assert.equal(run('ensureFamilyBranches().siblingEconomy.loans.length'),0);});
test("v62 voluntary lending transfers exactly three coins",()=>{const {run,storage}=game();run(setup+v62Loan+"");assert.equal(run('__kid.wealth'),17);assert.equal(run('__kid2.wealth'),5);});
test("v62 total NPC wealth conserved by sibling loan",()=>{const {run,storage}=game();run(setup+v62Loan+"");assert.equal(run('__kid.wealth+__kid2.wealth'),22);});
test("v62 loan has real lender borrower identities",()=>{const {run,storage}=game();run(setup+v62Loan+"");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].lenderId'),run('__kid.id'));assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].borrowerId'),run('__kid2.id'));});
test("v62 loan starts with debt and three year deadline",()=>{const {run,storage}=game();run(setup+v62Loan+"");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].remaining'),3);assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].dueYear'),run('s.year+s.age+3'));});
test("v62 help request counter increments once",()=>{const {run,storage}=game();run(setup+v62Loan+"");assert.equal(run('ensureFamilyBranches().siblingEconomy.requests'),1);assert.equal(run('ensureFamilyBranches().siblingEconomy.transfers'),3);});
test("v62 player wealth unchanged by adult sibling loan",()=>{const {run,storage}=game();run(setup+v62Loan+"");assert.equal(run('s.wealth'),5);});
test("v62 same year does not create a second loan",()=>{const {run,storage}=game();run(setup+v62Loan+"familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans.length'),1);assert.equal(run('ensureFamilyBranches().siblingEconomy.transfers'),3);});
test("v62 refusal keeps all participant wealth",()=>{const {run,storage}=game();run(setup+v62Decline+"");assert.equal(run('__kid.wealth'),20);assert.equal(run('__kid2.wealth'),2);});
test("v62 refusal counts a request without fake debt",()=>{const {run,storage}=game();run(setup+v62Decline+"");assert.equal(run('ensureFamilyBranches().siblingEconomy.declines'),1);assert.equal(run('ensureFamilyBranches().siblingEconomy.loans.length'),0);});
test("v62 refusal does not retry same year",()=>{const {run,storage}=game();run(setup+v62Decline+"Math.random=()=>0;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.requests'),1);});
test("v62 zero-wealth needy sibling can receive mercy gift",()=>{const {run,storage}=game();run(setup+v62Gift+"");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans.length'),0);assert.equal(run('ensureFamilyBranches().siblingEconomy.transfers'),3);});
test("v62 gift debits giver and credits recipient exactly",()=>{const {run,storage}=game();run(setup+v62Gift+"");assert.equal(run('__kid.wealth'),17);assert.equal(run('__kid2.wealth'),3);});
test("v62 gift changes sibling relationship",()=>{const {run,storage}=game();run(setup+v62Gift+"");assert.ok(run('socialLinkBetween(__kid,__kid2).score>0'));});
test("v62 wealthy sibling keeps an eight coin reserve",()=>{const {run,storage}=game();run(setup+v62Base+"__kid.wealth=12;familySiblingEconomyYearTick();");assert.equal(run('__kid.wealth'),9);});
test("v62 nonpoor borrower does not ask for charity",()=>{const {run,storage}=game();run(setup+v62Base+"__kid2.wealth=4;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.requests'),0);});
test("v62 poor donor below threshold is not forced",()=>{const {run,storage}=game();run(setup+v62Base+"__kid.wealth=11;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.transfers'),0);});
test("v62 siblings in different places cannot transfer remotely",()=>{const {run,storage}=game();run(setup+v62Base+"__kid2.place='another-place';familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.requests'),0);});
test("v62 dead donor cannot lend",()=>{const {run,storage}=game();run(setup+v62Base+"__kid.alive=false;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.transfers'),0);});
test("v62 teenager sibling cannot borrow",()=>{const {run,storage}=game();run(setup+v62Base+"__kid2.age=16;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.transfers'),0);});
test("v62 year later borrower pays only available real wealth",()=>{const {run,storage}=game();run(setup+v62Loan+"s.age++;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].remaining'),1);assert.equal(run('__kid.wealth'),19);assert.equal(run('__kid2.wealth'),3);});
test("v62 annual repayment conserves total NPC money",()=>{const {run,storage}=game();run(setup+v62Loan+"s.age++;familySiblingEconomyYearTick();");assert.equal(run('__kid.wealth+__kid2.wealth'),22);});
test("v62 no twice yearly repayment",()=>{const {run,storage}=game();run(setup+v62Loan+"s.age++;familySiblingEconomyYearTick();familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.repayments'),2);});
test("v62 repayments are permanently settled when fully funded",()=>{const {run,storage}=game();run(setup+v62Loan+"s.age++;familySiblingEconomyYearTick();__kid2.wealth=6;s.age++;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].remaining'),0);assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].status'),'repaid');});
test("v62 no new immediate loan for recently repaid pair",()=>{const {run,storage}=game();run(setup+v62Loan+"s.age++;familySiblingEconomyYearTick();__kid2.wealth=3;s.age++;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans.length'),1);});
test("v62 borrower retains two coin safety buffer",()=>{const {run,storage}=game();run(setup+v62Loan+"__kid2.wealth=2;s.age++;familySiblingEconomyYearTick();");assert.equal(run('__kid2.wealth'),2);assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].remaining'),3);});
test("v62 deceased debtor is not charged after death",()=>{const {run,storage}=game();run(setup+v62Loan+"__kid2.alive=false;s.age++;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].status'),'forgiven');assert.equal(run('__kid.wealth'),17);});
test("v62 deceased creditor's wealth is not credited",()=>{const {run,storage}=game();run(setup+v62Loan+"__kid.alive=false;s.age++;familySiblingEconomyYearTick();");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].status'),'forgiven');assert.equal(run('__kid2.wealth'),5);});
test("v62 unpaid loan eventually defaults with social damage",()=>{const {run,storage}=game();run(setup+v62Loan+"__kid2.wealth=2;for(let i=0;i<7;i++){s.age++;familySiblingEconomyYearTick();}");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].status'),'defaulted');});
test("v62 defaulted borrower does not automatically get another loan",()=>{const {run,storage}=game();run(setup+v62Loan+"__kid2.wealth=2;for(let i=0;i<8;i++){s.age++;familySiblingEconomyYearTick();}");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans.length'),1);});
test("v62 parent may guarantee a real outstanding debt",()=>{const {run,storage}=game();run(setup+v62Loan+"window.__ok=familySiblingGuaranteeAction(__loan.id);");assert.equal(run('__ok'),true);assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].status'),'guaranteed');});
test("v62 guarantee credits lender from player wealth only",()=>{const {run,storage}=game();run(setup+v62Loan+"window.__old=s.wealth;window.__lender=__kid.wealth;familySiblingGuaranteeAction(__loan.id);");assert.equal(run('s.wealth'),run('__old-3'));assert.equal(run('__kid.wealth'),run('__lender+3'));});
test("v62 guarantee does not debit debtor a second time",()=>{const {run,storage}=game();run(setup+v62Loan+"window.__cash=__kid2.wealth;familySiblingGuaranteeAction(__loan.id);");assert.equal(run('__kid2.wealth'),run('__cash'));});
test("v62 guarantee consumes one monthly action",()=>{const {run,storage}=game();run(setup+v62Loan+"window.__m=s.monthsRemaining;familySiblingGuaranteeAction(__loan.id);");assert.equal(run('s.monthsRemaining'),run('__m-1'));});
test("v62 duplicate guarantee cannot mint funds",()=>{const {run,storage}=game();run(setup+v62Loan+"familySiblingGuaranteeAction(__loan.id);window.__lender=__kid.wealth;window.__again=familySiblingGuaranteeAction(__loan.id);");assert.equal(run('__again'),false);assert.equal(run('__kid.wealth'),run('__lender'));});
test("v62 guarantee denies insufficient parent wealth",()=>{const {run,storage}=game();run(setup+v62Loan+"s.wealth=1;window.__ok=familySiblingGuaranteeAction(__loan.id);");assert.equal(run('__ok'),false);assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].remaining'),3);});
test("v62 guarantee disallows remote participants",()=>{const {run,storage}=game();run(setup+v62Loan+"__kid2.place='away';window.__err=familySiblingGuaranteeIssue(__loan.id);");assert.ok(run('__err.includes("yanında")'));});
test("v62 unknown guarantee ID is rejected in central access gate",()=>{const {run,storage}=game();run(setup+v62Loan+"window.__err=accessIssue({kind:'familySiblingGuarantee',loanId:'fake'});");assert.ok(run('__err.includes("açık")'));});
test("v62 household economy card lists actual debtor and lender",()=>{const {run,storage}=game();run(setup+v62Loan+"window.__html=familySiblingEconomySummaryHtml();");assert.ok(run('__html.includes("Kardeşler Arası Borç")'));assert.ok(run('__html.includes("kalan 3/3")'));});
test("v62 family card includes household economy history",()=>{const {run,storage}=game();run(setup+v62Loan+"window.__html=adultChildrenSummaryHtml();");assert.ok(run('__html.includes("Kardeşlerin Hane Ekonomisi")'));});
test("v62 loan registry survives save and load",()=>{const {run,storage}=game();run(setup+v62Loan+"save();load();");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].remaining'),3);});
test("v62 guaranteed debt stays closed after loading",()=>{const {run,storage}=game();run(setup+v62Loan+"familySiblingGuaranteeAction(__loan.id);save();load();");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].status'),'guaranteed');});
test("v62 v61 save migration produces v62 safety backup",()=>{const {run,storage}=game();run(setup+v62Loan+"s.version=61;save();load();");assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v62'));});
test("v62 corrupt loan where borrower equals lender is discarded",()=>{const {run,storage}=game();run(setup+v62Loan+"ensureFamilyBranches().siblingEconomy.loans[0].borrowerId=__kid.id;ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().siblingEconomy.loans.length'),0);});
test("v62 history is finite and prevents nonsensical negative amounts",()=>{const {run,storage}=game();run(setup+v62Loan+"ensureFamilyBranches().siblingEconomy.transfers=-20;ensureFamilyBranches().siblingEconomy.loans[0].remaining=-5;ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().siblingEconomy.transfers'),0);assert.equal(run('ensureFamilyBranches().siblingEconomy.loans[0].remaining'),0);});
test("v62 automatic annual transactions do not use player's month quota",()=>{const {run,storage}=game();run(setup+v62Base+"window.__m=s.monthsRemaining;familySiblingEconomyYearTick();");assert.equal(run('s.monthsRemaining'),run('__m'));});


/* v63: household hardship, work interruption, family relief and older-save migration. */
const v63Job=v58Family+"s.age=65;s.wealth=10;__kid.wealth=20;__kid2.wealth=18;__kid.role='Demirci';Math.random=()=>.99;window.__case=familyHouseholdCrisisStart(__kid,'job_loss');";
const v63Shortage=v58Family+"s.age=65;s.wealth=10;__kid.wealth=20;__kid2.wealth=18;Math.random=()=>.99;window.__case=familyHouseholdCrisisStart(__kid,'shortage');";
test("v63 fresh v63 registry is empty",()=>{const {run,storage}=game();run(setup+v58Family+"");assert.equal(run("s.version"),73);assert.equal(run("ensureFamilyBranches().householdCrises.cases.length"),0);});
test("v63 job loss stores original career",()=>{const {run,storage}=game();run(setup+v63Job+"");assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].pastRole"),"Demirci");});
test("v63 job loss changes real NPC occupation",()=>{const {run,storage}=game();run(setup+v63Job+"");assert.equal(run("__kid.role"),"İşsiz");});
test("v63 job loss costs only NPC cash",()=>{const {run,storage}=game();run(setup+v63Job+"");assert.equal(run("__kid.wealth"),16);assert.equal(run("s.wealth"),10);});
test("v63 shortage deducts limited wealth without altering occupation",()=>{const {run,storage}=game();run(setup+v63Shortage+"");assert.equal(run("__kid.wealth"),17);assert.equal(run("__kid.role==='İşsiz'"),false);});
test("v63 one crisis creates one bounded event",()=>{const {run,storage}=game();run(setup+v63Job+"");assert.equal(run("ensureFamilyBranches().householdCrises.started"),1);});
test("v63 active crisis cannot be restarted",()=>{const {run,storage}=game();run(setup+v63Job+"window.__repeat=familyHouseholdCrisisStart(__kid,'shortage');");assert.equal(run("__repeat"),null);assert.equal(run("ensureFamilyBranches().householdCrises.cases.length"),1);});
test("v63 minors cannot receive adult crisis",()=>{const {run,storage}=game();run(setup+v58Family+"__kid.age=15;window.__repeat=familyHouseholdCrisisStart(__kid,'job_loss');");assert.equal(run("__repeat"),null);});
test("v63 deceased child cannot get household crisis",()=>{const {run,storage}=game();run(setup+v58Family+"__kid.alive=false;window.__repeat=familyHouseholdCrisisStart(__kid,'job_loss');");assert.equal(run("__repeat"),null);});
test("v63 outsider never enters a child's crisis register",()=>{const {run,storage}=game();run(setup+v58Family+"window.__outsider=normalizeNPC({id:'outsider63',age:40,alive:true,wealth:20});window.__repeat=familyHouseholdCrisisStart(__outsider,'job_loss');");assert.equal(run("__repeat"),null);});
test("v63 unknown crisis type is rejected",()=>{const {run,storage}=game();run(setup+v58Family+"window.__repeat=familyHouseholdCrisisStart(__kid,'alien');");assert.equal(run("__repeat"),null);});
test("v63 low NPC wealth never goes negative",()=>{const {run,storage}=game();run(setup+v58Family+"__kid.wealth=1;familyHouseholdCrisisStart(__kid,'job_loss');");assert.equal(run("__kid.wealth"),0);});
test("v63 year tick never costs player months",()=>{const {run,storage}=game();run(setup+v63Job+"window.__months=s.monthsRemaining;familyHouseholdCrisisYearTick();");assert.equal(run("s.monthsRemaining"),12);});
test("v63 annual state cannot update twice in the same year",()=>{const {run,storage}=game();run(setup+v63Job+"familyHouseholdCrisisYearTick();window.__hard=ensureFamilyBranches().householdCrises.cases[0].hardship;familyHouseholdCrisisYearTick();");assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].hardship"),48);});
test("v63 unsupported year makes hardship heavier",()=>{const {run,storage}=game();run(setup+v63Job+"s.age++;familyHouseholdCrisisYearTick();");assert.ok(run("ensureFamilyBranches().householdCrises.cases[0].hardship>48"));});
test("v63 recovery does not occur at initial job-loss instant",()=>{const {run,storage}=game();run(setup+v63Job+"Math.random=()=>0;familyHouseholdCrisisYearTick();");assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].status"),"active");});
test("v63 job recovery can restore old work after two years",()=>{const {run,storage}=game();run(setup+v63Job+"s.age+=2;Math.random=(()=>{let i=0;return ()=>i++===0?0:.99;})();familyHouseholdCrisisYearTick();");assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].status"),"resolved");assert.equal(run("__kid.role"),"Demirci");});
test("v63 successful recovery logs end year and counter",()=>{const {run,storage}=game();run(setup+v63Job+"s.age+=2;Math.random=(()=>{let i=0;return ()=>i++===0?0:.99;})();familyHouseholdCrisisYearTick();");assert.equal(run("ensureFamilyBranches().householdCrises.recovered"),1);assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].endedYear"),run('s.year+s.age'));});
test("v63 economic shortage resolves without job loss",()=>{const {run,storage}=game();run(setup+v63Shortage+"window.__role=__kid.role;s.age+=2;Math.random=(()=>{let i=0;return ()=>i++===0?0:.99;})();familyHouseholdCrisisYearTick();");assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].status"),"resolved");assert.equal(run("__kid.role"),run('__role'));});
test("v63 recovery never overrides externally changed role",()=>{const {run,storage}=game();run(setup+v63Job+"__kid.role='Ozan';s.age+=2;Math.random=(()=>{let i=0;return ()=>i++===0?0:.99;})();familyHouseholdCrisisYearTick();");assert.equal(run("__kid.role"),"Ozan");});
test("v63 recently recovered household cannot immediately re-crash",()=>{const {run,storage}=game();run(setup+v63Job+"s.age+=2;Math.random=(()=>{let i=0;return ()=>i++===0?0:.99;})();familyHouseholdCrisisYearTick();window.__repeat=familyHouseholdCrisisStart(__kid,'shortage');");assert.equal(run("__repeat"),null);});
test("v63 death resolves active crisis without removing identity",()=>{const {run,storage}=game();run(setup+v63Job+"__kid.alive=false;s.age++;familyHouseholdCrisisYearTick();");assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].status"),"resolved");});
test("v63 relief moves exactly three actual player coins",()=>{const {run,storage}=game();run(setup+v63Job+"window.__money=s.wealth;window.__childMoney=__kid.wealth;familyHouseholdCrisisAction(__kid.id,'relief');");assert.equal(run("s.wealth"),7);assert.equal(run("__kid.wealth"),19);});
test("v63 direct relief conserves total player and child coins",()=>{const {run,storage}=game();run(setup+v63Job+"window.__total=s.wealth+__kid.wealth;familyHouseholdCrisisAction(__kid.id,'relief');");assert.equal(run("s.wealth+__kid.wealth"),26);});
test("v63 direct relief spends one annual action",()=>{const {run,storage}=game();run(setup+v63Job+"familyHouseholdCrisisAction(__kid.id,'relief');");assert.equal(run("s.monthsRemaining"),11);});
test("v63 relief lowers hardship and raises support",()=>{const {run,storage}=game();run(setup+v63Job+"familyHouseholdCrisisAction(__kid.id,'relief');");assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].hardship"),36);assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].assistance"),5);});
test("v63 job referral helps without moving money",()=>{const {run,storage}=game();run(setup+v63Job+"familyHouseholdCrisisAction(__kid.id,'referral');");assert.equal(run("s.wealth"),10);assert.equal(run("__kid.wealth"),16);assert.equal(run("ensureFamilyBranches().householdCrises.cases[0].assistance"),4);});
test("v63 job referral increases career momentum",()=>{const {run,storage}=game();run(setup+v63Job+"window.__before=ensureAdultChildProfile(__kid).careerMomentum;familyHouseholdCrisisAction(__kid.id,'referral');");assert.ok(run("ensureAdultChildProfile(__kid).careerMomentum>__before"));});
test("v63 shortage does not qualify for job referral",()=>{const {run,storage}=game();run(setup+v63Shortage+"window.__result=familyHouseholdCrisisAction(__kid.id,'referral');");assert.equal(run("__result"),false);assert.equal(run("s.monthsRemaining"),12);});
