/* v64: adult marriage, dependents, spousal wallets, household budget and migration. */
const v64Married=v58Family+"s.age=65;s.wealth=10;__kid.wealth=20;__kid.role='Demirci';window.__spouse=normalizeNPC({id:'v64_spouse',name:'Eş',age:30,alive:true,gender:'male',wealth:12,realm:s.realm,place:s.place},'Çocuk Eşi');registerAdultChildPartner(__kid,__spouse);__kid.descendants=[];ensureAdultChildProfile(__kid).careerMomentum=50;Math.random=()=>0;";
const v64Dependents=v64Married+"__kid.descendants=[normalizeNPC({id:'v64_child_a',name:'Torun A',age:4,alive:true,realm:s.realm,place:s.place},'Çocuk'),normalizeNPC({id:'v64_child_b',name:'Torun B',age:7,alive:true,realm:s.realm,place:s.place},'Çocuk')];";
const v64SpousePay=v64Dependents+"__kid.wealth=0;__kid.role='İşsiz';";
const v64Single=v58Family+"s.age=65;__kid.wealth=8;__kid.role='İşsiz';__kid.partner=null;__kid.descendants=[normalizeNPC({id:'v64_single_child',name:'Torun',age:5,alive:true,realm:s.realm,place:s.place},'Çocuk')];Math.random=()=>0;";
test("v64 new game has version 64 and clean budgets",()=>{const {run,storage}=game();run(setup+v58Family+"");assert.equal(run("s.version"),73);assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.expenses"),0);});
test("v64 married household has one annual expense",()=>{const {run,storage}=game();run(setup+v64Married+"");assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),1);});
test("v64 married household receives one unit of documented work income",()=>{const {run,storage}=game();run(setup+v64Married+"familyBudgetYearTick();");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.earned"),1);});
test("v64 basic wage and marriage expense balance for working child",()=>{const {run,storage}=game();run(setup+v64Married+"familyBudgetYearTick();");assert.equal(run("__kid.wealth"),20);});
test("v64 married child cost is tracked in household budget",()=>{const {run,storage}=game();run(setup+v64Married+"familyBudgetYearTick();");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.expenses"),1);});
test("v64 two minor dependents increase household cost",()=>{const {run,storage}=game();run(setup+v64Dependents+"");assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),2);});
test("v64 minor dependents cause real extra expense",()=>{const {run,storage}=game();run(setup+v64Dependents+"familyBudgetYearTick();");assert.equal(run("__kid.wealth"),19);});
test("v64 minor dependent count is persisted in history",()=>{const {run,storage}=game();run(setup+v64Dependents+"familyBudgetYearTick();");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.lastDependents"),2);});
test("v64 one minor creates one extra expense",()=>{const {run,storage}=game();run(setup+v64Married+"__kid.descendants=[normalizeNPC({id:'alone64',age:3,alive:true},'Çocuk')];");assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),2);});
test("v64 three dependents require three total expense units",()=>{const {run,storage}=game();run(setup+v64Dependents+"__kid.descendants.push(normalizeNPC({id:'third64',age:2,alive:true},'Çocuk'));");assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),3);});
test("v64 grown descendants do not increase minor upkeep",()=>{const {run,storage}=game();run(setup+v64Dependents+"__kid.descendants[0].age=19;__kid.descendants[1].age=20;");assert.equal(run("familyBudgetDependents(__kid)"),0);assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),1);});
test("v64 deceased grandchild does not increase upkeep",()=>{const {run,storage}=game();run(setup+v64Dependents+"__kid.descendants[0].alive=false;");assert.equal(run("familyBudgetDependents(__kid)"),1);});
test("v64 single parent pays childcare expenses without spouse",()=>{const {run,storage}=game();run(setup+v64Single+"familyBudgetYearTick();");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.lastExpense"),1);assert.equal(run("__kid.wealth"),7);});
test("v64 childless unmarried adult child has no recurring budget charge",()=>{const {run,storage}=game();run(setup+v58Family+"window.__money=__kid.wealth;familyBudgetYearTick();");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.expenses"),0);assert.equal(run("__kid.wealth"),run('__money'));});
test("v64 unemployed child does not receive invented wage",()=>{const {run,storage}=game();run(setup+v64SpousePay+"familyBudgetYearTick();");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.lastIncome"),0);});
test("v64 spouse pays shortfall directly from own real wealth",()=>{const {run,storage}=game();run(setup+v64SpousePay+"familyBudgetYearTick();");assert.equal(run("__kid.partner.wealth"),10);assert.equal(run("__kid.wealth"),0);});
