test("v64 next year can add a separate annual account",()=>{const {run,storage}=game();run(setup+v64Dependents+"familyBudgetYearTick();s.age++;familyBudgetYearTick();");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.history.length"),2);});
