test("v64 high career momentum improves capped wage",()=>{const {run,storage}=game();run(setup+v64Dependents+"ensureAdultChildProfile(__kid).careerMomentum=70;familyBudgetYearTick();");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.earned"),2);});
