test("v64 ongoing job loss blocks earned income",()=>{const {run,storage}=game();run(setup+v64Dependents+"familyHouseholdCrisisStart(__kid,'job_loss');familyBudgetYearTick();");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.earned"),0);});
