test("v65 next year approved caregiver cuts one unit of household cost",()=>{const {run,storage}=game();run(setup+v65Plan+"s.age++;");assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),1);});
test("v65 future care credits parent's budget but not caregiver wallet",()=>{const {run,storage}=game();run(setup+v65Serve+"");assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.lastExpense"),1);assert.equal(run("__kid2.wealth"),18);});
test("v65 caregiver improves grandchild annual learning",()=>{const {run,storage}=game();run(setup+v65Serve+"");assert.equal(run("ensureFamilyBranches().grandchildLearning.students.find(x=>x.grandId===__kid.descendants[0].id).progress"),4);});
test("v65 care shifts register meaningful intergenerational learning",()=>{const {run,storage}=game();run(setup+v65Serve+"");assert.equal(run("ensureFamilyBranches().grandchildLearning.sharedCareYears"),1);});
test("v65 future childcare gives relative real social kin link",()=>{const {run,storage}=game();run(setup+v65Serve+"");assert.ok(run("socialLinkBetween(__kid.descendants[0],__kid2).trust>50"));});
test("v65 annual care is never processed twice",()=>{const {run,storage}=game();run(setup+v65Serve+"familyGrandchildEducationYearTick();familyBudgetYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.sharedCareYears"),1);assert.equal(run("ensureAdultChildProfile(__kid).householdBudget.history.length"),1);});
test("v65 care promise cannot be reused two years later",()=>{const {run,storage}=game();run(setup+v65Plan+"s.age+=2;");assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),2);});
test("v65 caregiver refusal is preserved",()=>{const {run,storage}=game();run(setup+v65Reject+"");assert.equal(run("ensureFamilyBranches().grandchildLearning.refusals"),1);assert.equal(run("ensureFamilyBranches().grandchildLearning.accepted"),0);});
test("v65 refused caregiver cannot reduce next year budget",()=>{const {run,storage}=game();run(setup+v65Reject+"s.age++;");assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),2);});
test("v65 one grandchild care invitation consumes a month",()=>{const {run,storage}=game();run(setup+v65Plan+"");assert.equal(run("s.monthsRemaining"),11);});
test("v65 rejected invitation also costs one month",()=>{const {run,storage}=game();run(setup+v65Reject+"");assert.equal(run("s.monthsRemaining"),11);});
test("v65 same grandchild cannot be invited twice that year",()=>{const {run,storage}=game();run(setup+v65Plan+"window.__ok=familyGrandchildCareAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);assert.equal(run("ensureFamilyBranches().grandchildLearning.invitations"),1);});
test("v65 same helper cannot promise second grandchild",()=>{const {run,storage}=game();run(setup+v65Plan+"window.__ok=familyGrandchildCareAction(__kid.descendants[1].id,__kid2.id);");assert.equal(run("__ok"),false);});
test("v65 younger caregiver sibling cannot be asked",()=>{const {run,storage}=game();run(setup+v65Family+"__kid2.age=16;window.__ok=familyGrandchildCareAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);});
test("v65 parent cannot volunteer for own child's aunt uncle shift",()=>{const {run,storage}=game();run(setup+v65Family+"window.__ok=familyGrandchildCareAction(__kid.descendants[0].id,__kid.id);");assert.equal(run("__ok"),false);});
test("v65 dead helper sibling cannot volunteer",()=>{const {run,storage}=game();run(setup+v65Family+"__kid2.alive=false;window.__ok=familyGrandchildCareAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);});
test("v65 distant helper sibling cannot volunteer",()=>{const {run,storage}=game();run(setup+v65Family+"__kid2.place='other';window.__ok=familyGrandchildCareAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);});
test("v65 low-trust helper cannot volunteer",()=>{const {run,storage}=game();run(setup+v65Family+"__kid2.bonds.trust=20;window.__ok=familyGrandchildCareAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);});
test("v65 helper who relocates before shift no longer discounts care",()=>{const {run,storage}=game();run(setup+v65Plan+"s.age++;__kid2.place='away';");assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),2);});
test("v65 dead helper never provides future budget subsidy",()=>{const {run,storage}=game();run(setup+v65Plan+"s.age++;__kid2.alive=false;");assert.equal(run("familyBudgetExpense(__kid,ensureAdultChildProfile(__kid))"),2);});
