test("v65 recorded special lesson survives save and load",()=>{const {run,storage}=game();run(setup+v65Lesson+"save();load();");assert.equal(run("ensureFamilyBranches().grandchildLearning.lessons"),1);});
test("v65 accepted childcare agreement survives save and load",()=>{const {run,storage}=game();run(setup+v65Plan+"save();load();");assert.equal(run("ensureFamilyBranches().grandchildLearning.accepted"),1);});
test("v65 v64 save migrates and writes v65 safety snapshot",()=>{const {run,storage}=game();run(setup+v65Family+"s.version=64;save();load();");assert.equal(run("s.version"),73);assert.ok(run("localStorage.getItem('yazgi_before_v65')!==null"));});
test("v65 malformed education field removed at load normalization",()=>{const {run,storage}=game();run(setup+v65Lesson+"s.familyBranches.grandchildLearning.students.push({grandId:'other',parentId:'x',field:'unknown'});ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().grandchildLearning.students.length"),1);});
test("v65 education progress and metrics are bounded",()=>{const {run,storage}=game();run(setup+v65Lesson+"s.familyBranches.grandchildLearning.students[0].progress=999;ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().grandchildLearning.students[0].progress"),100);});
test("v65 history is limited to thirty two meaningful records",()=>{const {run,storage}=game();run(setup+v65Plan+"s.familyBranches.grandchildLearning.history=Array.from({length:90},()=>({year:1,note:'test',type:'lesson'}));ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().grandchildLearning.history.length"),32);});


/* v66: teenage family apprenticeships, consent, real skills, and save migration. */
const v66Family=v65Family+"__kid.goal='family';__kid.descendants[0].age=13;__kid.descendants[0].skills.riding=18;__kid2.skills.riding=28;";
const v66Plan=v66Family+"familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);";
const v66Serve=v66Plan+"s.age++;familyGrandchildApprenticeshipYearTick();";
test("v66 starts with an empty apprenticeship registry",()=>{const {run}=game();run(setup+v66Family);assert.equal(run("s.version"),73);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships.length"),0);});
test("v66 teenager may start voluntary apprenticeship with skilled relative",()=>{const {run}=game();run(setup+v66Plan);assert.equal(run("ensureFamilyBranches().grandchildLearning.placements"),1);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].status"),"active");});
test("v66 family apprenticeship uses one monthly action",()=>{const {run}=game();run(setup+v66Plan);assert.equal(run("s.monthsRemaining"),11);});
test("v66 acceptance starts with zero training sessions",()=>{const {run}=game();run(setup+v66Plan);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].sessions"),0);});
test("v66 next year trains real grandchild riding skill",()=>{const {run}=game();run(setup+v66Serve);assert.equal(run("__kid.descendants[0].skills.riding"),22);});
test("v66 next year counts one real mentorship session",()=>{const {run}=game();run(setup+v66Serve);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),1);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].sessions"),1);});
test("v66 mentoring adds education progress to same child's ledger",()=>{const {run}=game();run(setup+v66Serve);assert.equal(run("ensureFamilyBranches().grandchildLearning.students.find(r=>r.grandId===__kid.descendants[0].id).progress"),4);});
test("v66 no yearly duplicated sessions or skill gains",()=>{const {run}=game();run(setup+v66Serve+"familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),1);assert.equal(run("__kid.descendants[0].skills.riding"),22);});
test("v66 next year adds another genuine session",()=>{const {run}=game();run(setup+v66Serve+"s.age++;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),2);});
test("v66 caretaker's relocation pauses mentorship",()=>{const {run}=game();run(setup+v66Plan+"s.age++;__kid2.place='distant';familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),0);});
test("v66 deceased mentor cannot train teenager",()=>{const {run}=game();run(setup+v66Plan+"s.age++;__kid2.alive=false;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),0);});
test("v66 declined apprenticeship never grants free training",()=>{const {run}=game();run(setup+v66Family+"Math.random=()=>.99;familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);s.age++;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeRefusals"),1);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),0);});
test("v66 rejected application cannot be spammed in same year",()=>{const {run}=game();run(setup+v66Family+"Math.random=()=>.99;familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);window.__again=familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__again"),false);assert.equal(run("s.monthsRemaining"),11);});
test("v66 no second active placement for same grandchild",()=>{const {run}=game();run(setup+v66Plan+"window.__again=familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__again"),false);});
test("v66 mentor cannot be assigned a second teenager simultaneously",()=>{const {run}=game();run(setup+v66Plan+"__kid.descendants[1].age=13;__kid.descendants[1].skills.riding=20;window.__again=familyGrandchildApprenticeAction(__kid.descendants[1].id,__kid2.id);");assert.equal(run("__again"),false);});
test("v66 under-twelve grandchild cannot start apprenticeship",()=>{const {run}=game();run(setup+v66Family+"__kid.descendants[0].age=11;window.__ok=familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),12);});
test("v66 adult grandchild is past apprenticeship entry age",()=>{const {run}=game();run(setup+v66Family+"__kid.descendants[0].age=18;window.__ok=familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);});
test("v66 unskilled student cannot start apprenticeship",()=>{const {run}=game();run(setup+v66Family+"__kid.descendants[0].skills.riding=2;window.__ok=familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);});
test("v66 unskilled relative cannot act as mentor",()=>{const {run}=game();run(setup+v66Family+"__kid2.skills.riding=0;window.__ok=familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);});
test("v66 unknown mentor cannot consume a game month",()=>{const {run}=game();run(setup+v66Family+"window.__ok=familyGrandchildApprenticeAction(__kid.descendants[0].id,'unknown');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),12);});
test("v66 direct action bypass is stopped by central permission guard",()=>{const {run}=game();run(setup+v66Family+"window.__issue=accessIssue({kind:'grandchildApprentice',grandId:__kid.descendants[0].id,mentorId:'unknown'});");assert.ok(run("__issue.length>0"));});
test("v66 same-place real NPC conditions are checked",()=>{const {run}=game();run(setup+v66Family+"__kid2.place='another';window.__ok=familyGrandchildApprenticeAction(__kid.descendants[0].id,__kid2.id);");assert.equal(run("__ok"),false);});
test("v66 adult transition marks a trained apprenticeship completed once",()=>{const {run}=game();run(setup+v66Serve+"__kid.descendants[0].age=18;familyGrandchildApprenticeshipYearTick();familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.completions"),1);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].status"),"completed");});
test("v66 adult transition never grants an extra training session",()=>{const {run}=game();run(setup+v66Serve+"__kid.descendants[0].age=18;s.age++;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),1);});
test("v66 family panel shows apprenticeship invitations and mentor",()=>{const {run}=game();run(setup+v66Plan+"window.__html=familyGrandchildLearningHtml();");assert.ok(run("__html.includes('Çıraklık')"));assert.ok(run("__html.includes(__kid2.name)"));});
test("v66 apprenticeship survives save and reload",()=>{const {run}=game();run(setup+v66Plan+"save();load();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].status"),"active");});
test("v66 apprenticeship sessions survive save and reload",()=>{const {run}=game();run(setup+v66Serve+"save();load();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),1);});
test("v66 migrating v65 save retains study history and creates backup",()=>{const {run,storage}=game();run(setup+v66Family+"familyGrandchildEducationYearTick();s.version=65;save();load();");assert.equal(run("s.version"),73);assert.ok(storage.has("yazgi_before_v66"));assert.ok(run("ensureFamilyBranches().grandchildLearning.students.length>0"));});
test("v66 corrupted apprenticeship field is sanitized",()=>{const {run}=game();run(setup+v66Plan+"s.familyBranches.grandchildLearning.apprenticeships.push({grandId:'fake',parentId:'p',mentorId:'m',field:'hack',startedYear:1,status:'active'});ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships.length"),1);});
test("v66 tampered and infinite session counts are bounded",()=>{const {run}=game();run(setup+v66Plan+"s.familyBranches.grandchildLearning.apprenticeships[0].sessions=Infinity;ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].sessions"),0);});

/* v67: interruption, voluntary exits, tutor transfer and independent adult career choice. */
const v67Ready=v66Plan+"s.age++;familyGrandchildApprenticeshipYearTick();";
const v67Mentor=v67Ready+"window.__kid3=normalizeNPC({id:'v67-mentor',name:'Yeni Aile Ustası',age:32,gender:'female',alive:true,type:'Çocuk',rel:90,health:90,wealth:20,realm:s.realm,place:s.place,skills:{riding:45,craft:48,literacy:48}},'Çocuk');normalizeBonds(__kid3);__kid3.bonds.trust=90;s.children.push(__kid3);";
const v67Two=v67Ready+"s.age++;familyGrandchildApprenticeshipYearTick();";
test("v67 new game begins at save version 67",()=>{const {run}=game();assert.equal(run("s.version"),73);});
test("v67 initial apprenticeship record keeps legacy progress",()=>{const {run}=game();run(setup+v67Ready);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].sessions"),1);});
test("v67 player can end an active apprenticeship voluntarily",()=>{const {run}=game();run(setup+v67Ready+"window.__ok=familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'leave');");assert.equal(run("__ok"),true);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].status"),"ended");});
test("v67 voluntary exit records reason and counter",()=>{const {run}=game();run(setup+v67Ready+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'leave');");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].reason"),"voluntary");assert.equal(run("ensureFamilyBranches().grandchildLearning.withdrawals"),1);});
test("v67 voluntary departure does not undo earned NPC skills",()=>{const {run}=game();run(setup+v67Ready+"window.__before=__kid.descendants[0].skills.riding;familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'leave');");assert.equal(run("__kid.descendants[0].skills.riding"),run("__before"));});
test("v67 voluntary exit costs one month",()=>{const {run}=game();run(setup+v67Ready+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'leave');");assert.equal(run("s.monthsRemaining"),10);});
test("v67 cannot repeatedly end a departed apprenticeship",()=>{const {run}=game();run(setup+v67Ready+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'leave');window.__ok=familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'leave');");assert.equal(run("__ok"),false);assert.equal(run("ensureFamilyBranches().grandchildLearning.withdrawals"),1);});
test("v67 departure prevents later apprenticeship sessions",()=>{const {run}=game();run(setup+v67Ready+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'leave');s.age++;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),1);});
test("v67 mentor death closes active training safely",()=>{const {run}=game();run(setup+v67Ready+"__kid2.alive=false;s.age++;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].reason"),"lost");});
test("v67 death cannot repeatedly count interruption",()=>{const {run}=game();run(setup+v67Ready+"__kid2.alive=false;s.age++;familyGrandchildApprenticeshipYearTick();familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.interruptions"),1);});
test("v67 mentor relocation counts just one missed year",()=>{const {run}=game();run(setup+v67Ready+"__kid2.place='elsewhere';s.age++;familyGrandchildApprenticeshipYearTick();familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].missed"),1);});
test("v67 one missed year leaves apprenticeship recoverable",()=>{const {run}=game();run(setup+v67Ready+"__kid2.place='elsewhere';s.age++;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].status"),"active");});
test("v67 two missing training years end arrangement",()=>{const {run}=game();run(setup+v67Ready+"__kid2.place='elsewhere';s.age++;familyGrandchildApprenticeshipYearTick();s.age++;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].reason"),"absence");});
test("v67 returning mentor resets absence counter",()=>{const {run}=game();run(setup+v67Ready+"__kid2.place='elsewhere';s.age++;familyGrandchildApprenticeshipYearTick();__kid2.place=s.place;s.age++;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].missed"),0);});
test("v67 voluntary mentor change preserves training sessions",()=>{const {run}=game();run(setup+v67Mentor+"window.__before=ensureFamilyBranches().grandchildLearning.apprenticeships[0].sessions;familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].sessions"),run("__before"));});
test("v67 accepted new mentor changes actual mentor ID",()=>{const {run}=game();run(setup+v67Mentor+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].mentorId"),run("__kid3.id"));});
test("v67 changed mentor is recorded with old identity",()=>{const {run}=game();run(setup+v67Mentor+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].mentorHistory[0].id"),run("__kid2.id"));});
test("v67 accepted change uses a single month",()=>{const {run}=game();run(setup+v67Mentor+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);");assert.equal(run("s.monthsRemaining"),10);});
test("v67 no second mentor transfer in same year",()=>{const {run}=game();run(setup+v67Mentor+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);window.__ok=familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid2.id);");assert.equal(run("__ok"),false);});
test("v67 transfer refusal leaves the old mentor in place",()=>{const {run}=game();run(setup+v67Mentor+"Math.random=()=>.99;familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].mentorId"),run("__kid2.id"));assert.equal(run("ensureFamilyBranches().grandchildLearning.changeRefusals"),1);});
test("v67 refused mentor transfer still spends one month",()=>{const {run}=game();run(setup+v67Mentor+"Math.random=()=>.99;familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);");assert.equal(run("s.monthsRemaining"),10);});
test("v67 invalid mentor may not consume month",()=>{const {run}=game();run(setup+v67Mentor+"window.__ok=familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change','fake');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),11);});
test("v67 same mentor cannot be selected as replacement",()=>{const {run}=game();run(setup+v67Mentor+"window.__ok=familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid2.id);");assert.equal(run("__ok"),false);});
test("v67 unskilled replacement mentor cannot be chosen",()=>{const {run}=game();run(setup+v67Mentor+"__kid3.skills.riding=0;window.__ok=familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);");assert.equal(run("__ok"),false);});
test("v67 changed mentor can actually teach in following year",()=>{const {run}=game();run(setup+v67Mentor+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);s.age++;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeshipSessions"),2);});
test("v67 two years of training can lead to an NPC career",()=>{const {run}=game();run(setup+v67Two+"__kid.descendants[0].age=18;familyGrandchildApprenticeshipYearTick();");assert.equal(run("__kid.descendants[0].role"),"At Bakıcısı");assert.equal(run("ensureFamilyBranches().grandchildLearning.careers"),1);});
test("v67 adult career is recorded as independently selected",()=>{const {run}=game();run(setup+v67Two+"__kid.descendants[0].age=18;familyGrandchildApprenticeshipYearTick();");assert.equal(run("__kid.descendants[0].roleHistory.at(-1).source"),"family_apprenticeship");});
test("v67 adult may refuse an apprenticeship-based career",()=>{const {run}=game();run(setup+v67Two+"__kid.descendants[0].age=18;Math.random=()=>.99;window.__old=__kid.descendants[0].role;familyGrandchildApprenticeshipYearTick();");assert.equal(run("__kid.descendants[0].role"),run("__old"));assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].careerAccepted"),false);});
test("v67 only one training year does not force a career",()=>{const {run}=game();run(setup+v67Ready+"__kid.descendants[0].age=18;familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.careers"),0);});
test("v67 apprenticeship-based career never repeats at next tick",()=>{const {run}=game();run(setup+v67Two+"__kid.descendants[0].age=18;familyGrandchildApprenticeshipYearTick();familyGrandchildApprenticeshipYearTick();");assert.equal(run("ensureFamilyBranches().grandchildLearning.careers"),1);});
test("v67 apprentice outcome appears in family panel even without minors",()=>{const {run}=game();run(setup+v67Two+"__kid.descendants[0].age=18;__kid.descendants[1].age=18;familyGrandchildApprenticeshipYearTick();window.__html=familyGrandchildLearningHtml();");assert.ok(run("__html.includes('çıraklık mezunu')"));});
test("v67 manage controls appear in family panel",()=>{const {run}=game();run(setup+v67Mentor+"window.__html=familyGrandchildLearningHtml();");assert.ok(run("__html.includes('Çıraklığı bırak')"));assert.ok(run("__html.includes('Ustayı değiştir')"));});
test("v67 central guard blocks fake transfer",()=>{const {run}=game();run(setup+v67Ready+"window.__error=accessIssue({kind:'grandchildApprenticeManage',grandId:'fake',id:'change',mentorId:'fake'});");assert.ok(run("__error.length>0"));});
test("v67 save and load retains changed mentor history",()=>{const {run}=game();run(setup+v67Mentor+"familyGrandchildApprenticeManageAction(__kid.descendants[0].id,'change',__kid3.id);save();load();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].mentorHistory.length"),1);});
test("v67 career choices survive save and reload",()=>{const {run}=game();run(setup+v67Two+"__kid.descendants[0].age=18;familyGrandchildApprenticeshipYearTick();save();load();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].careerAccepted"),true);});
