test("v67 corrupt mentor history and counters are cleaned",()=>{const {run}=game();run(setup+v67Mentor+"s.familyBranches.grandchildLearning.apprenticeships[0].mentorHistory=[{id:2,year:'oops'}];s.familyBranches.grandchildLearning.apprenticeships[0].missed=Infinity;ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].mentorHistory.length"),0);assert.equal(run("ensureFamilyBranches().grandchildLearning.apprenticeships[0].missed"),0);});

/* v68: independent adult-grandchild livelihoods, careers, layoffs, and aid. */
const v68Adult=v65Family+"__kid.descendants[0].age=18;__kid.descendants[0].role='Demirci';__kid.descendants[0].skills.craft=40;__kid.descendants[0].wealth=10;Math.random=()=>.99;";
const v68First=v68Adult+"familyGrandchildCareersYearTick();";
const v68Graduate=v67Two+"__kid.descendants[0].age=18;familyGrandchildApprenticeshipYearTick();__kid.descendants[0].wealth=10;Math.random=()=>.99;";
const v68JobLoss=v68Adult+"__kid.descendants[0].role='Çoban';familyGrandchildCareerLedger(__kid.descendants[0]).years=3;Math.random=()=>0;familyGrandchildCareersYearTick();";
const v68Unemployed=v68First+"__kid.descendants[0].role='İşsiz';window.__record=ensureFamilyBranches().grandchildCareers.people[0];__record.lostYear=s.year+s.age;__record.priorRole='Demirci';";
test("v68 new game uses save version 68",()=>{const {run}=game();assert.equal(run('s.version'),73);});
test("v68 no adult grandchildren begin with no career records",()=>{const {run}=game();run(setup+v65Family);assert.equal(run('ensureFamilyBranches().grandchildCareers.people.length'),0);});
test("v68 adult grandchild creates genuine independent ledger",()=>{const {run}=game();run(setup+v68First);assert.equal(run('ensureFamilyBranches().grandchildCareers.people.length'),1);});
test("v68 working grandchild earns two units and pays one",()=>{const {run}=game();run(setup+v68First);assert.equal(run('__kid.descendants[0].wealth'),11);});
test("v68 career earnings never credit player directly",()=>{const {run}=game();run(setup+v68Adult+"window.__w=s.wealth;familyGrandchildCareersYearTick();");assert.equal(run('s.wealth'),run('__w'));});
test("v68 adult child's own wealth is unaffected by grandchild job",()=>{const {run}=game();run(setup+v68Adult+"window.__w=__kid.wealth;familyGrandchildCareersYearTick();");assert.equal(run('__kid.wealth'),run('__w'));});
test("v68 adult yearly career processes only once",()=>{const {run}=game();run(setup+v68First+"familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].earned'),2);assert.equal(run('__kid.descendants[0].wealth'),11);});
test("v68 next year creates another real salary and cost",()=>{const {run}=game();run(setup+v68First+"s.age++;familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].earned'),4);});
test("v68 grown household with spouse pays more than single adult",()=>{const {run}=game();run(setup+v68Adult+"__kid.descendants[0].partner={alive:true,wealth:7};familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].lastPaid'),2);});
test("v68 spouse wallet is not silently debited by grandchild spending",()=>{const {run}=game();run(setup+v68Adult+"__kid.descendants[0].partner={alive:true,wealth:7};familyGrandchildCareersYearTick();");assert.equal(run('__kid.descendants[0].partner.wealth'),7);});
test("v68 own young dependents add actual household expense",()=>{const {run}=game();run(setup+v68Adult+"__kid.descendants[0].descendants=[{id:'gg',alive:true,age:2}];familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].lastPaid'),2);});
test("v68 unemployed adult does not earn wages",()=>{const {run}=game();run(setup+v68Adult+"__kid.descendants[0].role='İşsiz';familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].lastIncome'),0);});
test("v68 jobless adult pays from own real savings",()=>{const {run}=game();run(setup+v68Adult+"__kid.descendants[0].role='İşsiz';familyGrandchildCareersYearTick();");assert.equal(run('__kid.descendants[0].wealth'),9);});
test("v68 low-wealth grandchild cannot spend negative currency",()=>{const {run}=game();run(setup+v68Adult+"__kid.descendants[0].role='İşsiz';__kid.descendants[0].wealth=0;familyGrandchildCareersYearTick();");assert.equal(run('__kid.descendants[0].wealth'),0);assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].shortfalls'),1);});
test("v68 unpaid household need is not invented as settled expense",()=>{const {run}=game();run(setup+v68Adult+"__kid.descendants[0].role='İşsiz';__kid.descendants[0].wealth=0;familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].lastPaid'),0);assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].lastShortfall'),1);});
test("v68 properly trained independent grandchild can be promoted",()=>{const {run}=game();run(setup+v68Adult+"familyGrandchildCareerLedger(__kid.descendants[0]).years=3;Math.random=()=>0;familyGrandchildCareersYearTick();");assert.equal(run('__kid.descendants[0].role'),"Usta Demirci");});
test("v68 promotion is written to real NPC role history",()=>{const {run}=game();run(setup+v68Adult+"familyGrandchildCareerLedger(__kid.descendants[0]).years=3;Math.random=()=>0;familyGrandchildCareersYearTick();");assert.equal(run('__kid.descendants[0].roleHistory.at(-1).source'),"grandchild_promotion");});
test("v68 promoted worker receives higher income next year",()=>{const {run}=game();run(setup+v68Adult+"familyGrandchildCareerLedger(__kid.descendants[0]).years=3;Math.random=()=>0;familyGrandchildCareersYearTick();s.age++;Math.random=()=>.99;familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].lastIncome'),3);});
test("v68 promotion cannot simultaneously trigger job loss",()=>{const {run}=game();run(setup+v68Adult+"familyGrandchildCareerLedger(__kid.descendants[0]).years=3;Math.random=()=>0;familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.layoffs'),0);});
test("v68 experienced employed grandchild can lose job",()=>{const {run}=game();run(setup+v68JobLoss);assert.equal(run('__kid.descendants[0].role'),"İşsiz");assert.equal(run('ensureFamilyBranches().grandchildCareers.layoffs'),1);});
test("v68 job loss records correct former role and no salary",()=>{const {run}=game();run(setup+v68JobLoss);assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].priorRole'),"Çoban");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].lastIncome'),0);});
test("v68 job loss does not create repeat losses in same year",()=>{const {run}=game();run(setup+v68JobLoss+"familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.layoffs'),1);});
test("v68 recovery cannot occur in same year as job loss",()=>{const {run}=game();run(setup+v68JobLoss+"familyGrandchildCareersYearTick();");assert.equal(run('__kid.descendants[0].role'),"İşsiz");});
test("v68 unemployed grandchild may independently return to former job",()=>{const {run}=game();run(setup+v68JobLoss+"s.age++;Math.random=()=>0;familyGrandchildCareersYearTick();");assert.equal(run('__kid.descendants[0].role'),"Çoban");assert.equal(run('ensureFamilyBranches().grandchildCareers.recoveries'),1);});
test("v68 recovery year earns only partial wage",()=>{const {run}=game();run(setup+v68JobLoss+"s.age++;Math.random=()=>0;familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].lastIncome'),1);});
test("v68 recovered worker is not immediately laid off again",()=>{const {run}=game();run(setup+v68JobLoss+"s.age++;Math.random=()=>0;familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.layoffs'),1);});
test("v68 protected NPC aspiration blocks new layoff",()=>{const {run}=game();run(setup+v68Adult+"__kid.descendants[0].aspiration={protectedRole:'Demirci'};familyGrandchildCareerLedger(__kid.descendants[0]).years=4;Math.random=()=>0;familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.layoffs'),0);});
test("v68 independent economic panel shows actual grown descendant",()=>{const {run}=game();run(setup+v68First+"window.__html=adultChildrenSummaryHtml();");assert.ok(run("__html.includes('Yetişkin Torunların Meslek ve Geçimi')"));});
test("v68 family summary includes real earned income and wealth",()=>{const {run}=game();run(setup+v68First+"window.__html=familyGrandchildCareersHtml();");assert.ok(run("__html.includes('Son gelir 2')"));assert.ok(run("__html.includes('kendi serveti 11')"));});
test("v68 relatives who did not graduate still have independent livelihood",()=>{const {run}=game();run(setup+v68First);assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].years'),1);});
test("v68 completed apprenticeship graduate starts same career ledger",()=>{const {run}=game();run(setup+v68Graduate+"familyGrandchildCareersYearTick();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].id'),run('__kid.descendants[0].id'));assert.ok(run('__kid.descendants[0].statusFlags.grandchildCareerTracked'));});
test("v68 emergency support transfers exactly three real coins",()=>{const {run}=game();run(setup+v68First+"window.__before=s.wealth;window.__own=__kid.descendants[0].wealth;familyGrandchildCareerAction(__kid.descendants[0].id,'relief');");assert.equal(run('s.wealth'),run('__before-3'));assert.equal(run('__kid.descendants[0].wealth'),run('__own+3'));});
test("v68 relief spends one of twelve action months",()=>{const {run}=game();run(setup+v68First+"familyGrandchildCareerAction(__kid.descendants[0].id,'relief');");assert.equal(run('s.monthsRemaining'),11);});
test("v68 one year permits no duplicate emergency aid",()=>{const {run}=game();run(setup+v68First+"familyGrandchildCareerAction(__kid.descendants[0].id,'relief');window.__before=s.wealth;window.__ok=familyGrandchildCareerAction(__kid.descendants[0].id,'relief');");assert.equal(run('__ok'),false);assert.equal(run('s.wealth'),run('__before'));});
test("v68 ghost grandchild cannot be supported",()=>{const {run}=game();run(setup+v68First+"window.__ok=familyGrandchildCareerAction('ghost','relief');");assert.equal(run('__ok'),false);assert.equal(run('s.monthsRemaining'),12);});
test("v68 direct permission guard rejects fake grandchild aid",()=>{const {run}=game();run(setup+v68First+"window.__error=accessIssue({kind:'grandchildCareer',grandId:'ghost',id:'relief'});");assert.ok(run('__error.length>0'));});
test("v68 job referral only available to unemployed grandchild",()=>{const {run}=game();run(setup+v68First+"window.__ok=familyGrandchildCareerAction(__kid.descendants[0].id,'referral');");assert.equal(run('__ok'),false);});
test("v68 unemployed grandchild can receive next year's referral",()=>{const {run}=game();run(setup+v68Unemployed+"familyGrandchildCareerAction(__kid.descendants[0].id,'referral');");assert.equal(run('ensureFamilyBranches().grandchildCareers.referrals'),1);assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].referralUntil'),run('s.year+s.age+1'));});
test("v68 referral does not immediately grant a fake job",()=>{const {run}=game();run(setup+v68Unemployed+"familyGrandchildCareerAction(__kid.descendants[0].id,'referral');");assert.equal(run('__kid.descendants[0].role'),"İşsiz");});
test("v68 referral spends a month but no player money",()=>{const {run}=game();run(setup+v68Unemployed+"window.__before=s.wealth;familyGrandchildCareerAction(__kid.descendants[0].id,'referral');");assert.equal(run('s.wealth'),run('__before'));assert.equal(run('s.monthsRemaining'),11);});
test("v68 absent adult grandchild cannot receive remote support",()=>{const {run}=game();run(setup+v68First+"__kid.descendants[0].place='away';window.__ok=familyGrandchildCareerAction(__kid.descendants[0].id,'relief');");assert.equal(run('__ok'),false);});
test("v68 completed earnings and aid survive save and reload",()=>{const {run}=game();run(setup+v68First+"familyGrandchildCareerAction(__kid.descendants[0].id,'relief');save();load();");assert.equal(run('ensureFamilyBranches().grandchildCareers.aid'),1);assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].earned'),2);});
test("v68 v67 save migrates without losing mature child",()=>{const {run,storage}=game();run(setup+v68First+"s.version=67;save();load();");assert.equal(run('s.version'),73);assert.ok(storage.has('yazgi_before_v68'));assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].earned'),2);});
test("v68 corrupt career income and rank sanitized on normalization",()=>{const {run}=game();run(setup+v68First+"s.familyBranches.grandchildCareers.people[0].rank=99;s.familyBranches.grandchildCareers.people[0].earned=-5;ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].rank'),1);assert.equal(run('ensureFamilyBranches().grandchildCareers.people[0].earned'),0);});
test("v68 tampered malformed record discarded",()=>{const {run}=game();run(setup+v68First+"s.familyBranches.grandchildCareers.people.push({id:5,lastIncome:Infinity});ensureFamilyBranches();");assert.equal(run('ensureFamilyBranches().grandchildCareers.people.length'),1);});

/* v69: real independent households, title ownership, fourth generation, family gift. */
const v69Adult=v68First+"familyGrandchildHomesYearTick();";
const v69Rent=v69Adult+"__kid.descendants[0].wealth=20;Math.random=()=>0;familyGrandchildHomeAction(__kid.descendants[0].id,'separate');";
const v69YearRent=v69Rent+"s.age++;Math.random=()=>.99;familyGrandchildCareersYearTick();familyGrandchildHomesYearTick();";
const v69Owned=v69YearRent+"familyGrandchildHomeAction(__kid.descendants[0].id,'purchase');";
const v69Birth=v69Adult+"window.__baby=normalizeNPC({id:'great-grandchild-v69',name:'Dördüncü Nesil',age:0,birthYear:s.year+s.age+1,alive:true,type:'Çocuk',parentIds:[__kid.descendants[0].id],realm:s.realm,place:s.place},'Çocuk');__kid.descendants[0].descendants.push(__baby);s.age++;familyGrandchildHomesYearTick();";
test("v69 fresh game is version 69",()=>{const {run}=game();assert.equal(run("s.version"),73);});
test("v69 new family housing ledger starts empty",()=>{const {run}=game();run(setup+v65Family);assert.equal(run("ensureFamilyBranches().grandchildHomes.people.length"),0);});
test("v69 grown grandchild receives one household record",()=>{const {run}=game();run(setup+v69Adult);assert.equal(run("ensureFamilyBranches().grandchildHomes.people.length"),1);});
test("v69 initial household is family yurt without existing property",()=>{const {run}=game();run(setup+v69Adult);assert.equal(run("ensureFamilyBranches().grandchildHomes.people[0].mode"),"family");});
test("v69 home tick once a year does not duplicate ledger",()=>{const {run}=game();run(setup+v69Adult+"familyGrandchildHomesYearTick();");assert.equal(run("ensureFamilyBranches().grandchildHomes.people.length"),1);});
test("v69 family household keeps original base living costs",()=>{const {run}=game();run(setup+v69Adult);assert.equal(run("familyGrandchildCareerExpense(__kid.descendants[0])"),1);});
test("v69 adult may voluntarily create separate rental home",()=>{const {run}=game();run(setup+v69Rent);assert.equal(run("ensureFamilyBranches().grandchildHomes.people[0].mode"),"rented");});
test("v69 separate home costs one month",()=>{const {run}=game();run(setup+v69Rent);assert.equal(run("s.monthsRemaining"),11);});
test("v69 voluntary housing discussion can be declined",()=>{const {run}=game();run(setup+v69Adult+"Math.random=()=>.99;familyGrandchildHomeAction(__kid.descendants[0].id,'separate');");assert.equal(run("ensureFamilyBranches().grandchildHomes.people[0].mode"),"family");assert.equal(run("ensureFamilyBranches().grandchildHomes.rejected"),1);});
test("v69 refusal still uses the monthly right",()=>{const {run}=game();run(setup+v69Adult+"Math.random=()=>.99;familyGrandchildHomeAction(__kid.descendants[0].id,'separate');");assert.equal(run("s.monthsRemaining"),11);});
test("v69 cannot demand second housing decision in same year",()=>{const {run}=game();run(setup+v69Rent+"window.__ok=familyGrandchildHomeAction(__kid.descendants[0].id,'return');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),11);});
test("v69 independent renter incurs higher annual expense",()=>{const {run}=game();run(setup+v69Rent);assert.equal(run("familyGrandchildCareerExpense(__kid.descendants[0])"),2);});
test("v69 rental expense comes from grandchild real assets",()=>{const {run}=game();run(setup+v69YearRent);assert.equal(run("ensureFamilyBranches().grandchildCareers.people[0].lastPaid"),2);assert.equal(run("__kid.descendants[0].wealth"),20);});
test("v69 rental does not bill grandmother or parent",()=>{const {run}=game();run(setup+v69Rent+"window.__player=s.wealth;window.__parent=__kid.wealth;s.age++;Math.random=()=>.99;familyGrandchildCareersYearTick();");assert.equal(run("s.wealth"),run("__player"));assert.equal(run("__kid.wealth"),run("__parent"));});
test("v69 purchase requires an actually separate household",()=>{const {run}=game();run(setup+v69Adult+"__kid.descendants[0].wealth=30;window.__ok=familyGrandchildHomeAction(__kid.descendants[0].id,'purchase');");assert.equal(run("__ok"),false);});
test("v69 purchase cannot happen without twelve real coins",()=>{const {run}=game();run(setup+v69YearRent+"__kid.descendants[0].wealth=11;window.__ok=familyGrandchildHomeAction(__kid.descendants[0].id,'purchase');");assert.equal(run("__ok"),false);});
test("v69 purchase spends twelve from grandchild not player",()=>{const {run}=game();run(setup+v69YearRent+"window.__before=__kid.descendants[0].wealth;window.__player=s.wealth;familyGrandchildHomeAction(__kid.descendants[0].id,'purchase');");assert.equal(run("__kid.descendants[0].wealth"),run("__before-12"));assert.equal(run("s.wealth"),run("__player"));});
test("v69 bought yurt becomes a real NPC estate asset",()=>{const {run}=game();run(setup+v69Owned);assert.ok(run("normalizeNPCEstate(__kid.descendants[0]).assets.includes('yurt')"));});
test("v69 owned yurt mode persists in family record",()=>{const {run}=game();run(setup+v69Owned);assert.equal(run("ensureFamilyBranches().grandchildHomes.people[0].mode"),"owned");});
test("v69 owned yurt removes rental surcharge",()=>{const {run}=game();run(setup+v69Owned);assert.equal(run("familyGrandchildCareerExpense(__kid.descendants[0])"),1);});
test("v69 owned yurt contributes actual NPC estate value",()=>{const {run}=game();run(setup+v69Owned+"window.__cash=__kid.descendants[0].wealth;");assert.ok(run("npcEstateValue(__kid.descendants[0])>__cash"));});
test("v69 home purchase cannot be duplicated",()=>{const {run}=game();run(setup+v69Owned+"s.age++;window.__ok=familyGrandchildHomeAction(__kid.descendants[0].id,'purchase');");assert.equal(run("__ok"),false);});
test("v69 family yurt return requires rental without own property",()=>{const {run}=game();run(setup+v69Adult+"window.__ok=familyGrandchildHomeAction(__kid.descendants[0].id,'return');");assert.equal(run("__ok"),false);});
test("v69 voluntary renter can return to shared family home",()=>{const {run}=game();run(setup+v69YearRent+"Math.random=()=>0;familyGrandchildHomeAction(__kid.descendants[0].id,'return');");assert.equal(run("ensureFamilyBranches().grandchildHomes.people[0].mode"),"family");});
test("v69 returning to family yurt ends recurring rent",()=>{const {run}=game();run(setup+v69YearRent+"Math.random=()=>0;familyGrandchildHomeAction(__kid.descendants[0].id,'return');");assert.equal(run("familyGrandchildCareerExpense(__kid.descendants[0])"),1);});
test("v69 family home sees independent years once per year",()=>{const {run}=game();run(setup+v69YearRent+"familyGrandchildHomesYearTick();");assert.equal(run("ensureFamilyBranches().grandchildHomes.people[0].yearsIndependent"),1);});
test("v69 new fourth-generation child is actual descendant not a duplicate",()=>{const {run}=game();run(setup+v69Birth);assert.equal(run("__kid.descendants[0].descendants.filter(n=>n.id===__baby.id).length"),1);});
