test("v69 descendant identity is retained in birth ledger",()=>{const {run}=game();run(setup+v69Birth);assert.ok(run("ensureFamilyBranches().grandchildHomes.people[0].children.includes(__baby.id)"));});
test("v69 great-grandchild is real heir under existing estate rules",()=>{const {run}=game();run(setup+v69Birth);assert.ok(run("npcEstateHeirs(__kid.descendants[0]).some(h=>h.id===__baby.id)"));});
test("v69 lifetime inheritance transfers exactly five from player to adult grandchild",()=>{const {run}=game();run(setup+v69Adult+"window.__p=s.wealth;window.__g=__kid.descendants[0].wealth;familyGrandchildHomeAction(__kid.descendants[0].id,'heritage');");assert.equal(run("s.wealth"),run("__p-5"));assert.equal(run("__kid.descendants[0].wealth"),run("__g+5"));});
test("v69 lifetime legacy gift records real estate provenance",()=>{const {run}=game();run(setup+v69Adult+"familyGrandchildHomeAction(__kid.descendants[0].id,'heritage');");assert.ok(run("normalizeNPCEstate(__kid.descendants[0]).inheritedFrom.some(r=>r.id===s.id&&r.wealth===5&&r.kind==='lifetime_gift')"));});
