test("v69 once-gifted torun cannot be gifted again same year",()=>{const {run}=game();run(setup+v69Adult+"familyGrandchildHomeAction(__kid.descendants[0].id,'heritage');window.__ok=familyGrandchildHomeAction(__kid.descendants[0].id,'heritage');");assert.equal(run("__ok"),false);});
test("v69 lifetime inheritance gift max three records for one grandchild",()=>{const {run}=game();run(setup+v69Adult+"s.wealth=30;familyGrandchildHomeAction(__kid.descendants[0].id,'heritage');s.age++;familyGrandchildHomeAction(__kid.descendants[0].id,'heritage');s.age++;familyGrandchildHomeAction(__kid.descendants[0].id,'heritage');s.age++;window.__ok=familyGrandchildHomeAction(__kid.descendants[0].id,'heritage');");assert.equal(run("ensureFamilyBranches().grandchildHomes.heritageGifts"),3);assert.equal(run("__ok"),false);});
