test("v69 fake grandchild cannot trigger home transfer",()=>{const {run}=game();run(setup+v69Adult+"window.__ok=familyGrandchildHomeAction('fake','heritage');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),12);});
test("v69 child below eighteen cannot create independent home",()=>{const {run}=game();run(setup+v69Adult+"__kid.descendants[0].age=17;window.__ok=familyGrandchildHomeAction(__kid.descendants[0].id,'separate');");assert.equal(run("__ok"),false);});
