/* v70 — fourth-generation NPC schooling, adult choice, family links and real tree. */
const v70Child=v69Birth+"__baby.age=6;__baby.birthYear=s.year+s.age-6;__baby.birthMonth=1;__baby.skills={riding:10,craft:10,literacy:10};__kid.descendants[0].goal='family';";
const v70Student=v70Child+"familyFourthGenerationYearTick();";
const v70Lesson=v70Student+"familyFourthGenerationLessonAction(__baby.id,'riding');";
const v70Older=v70Child+"__baby.age=16;__baby.birthYear=s.year+s.age-16;__baby.skills.riding=22;familyFourthGenerationYearTick();s.age++;__baby.age=17;familyFourthGenerationYearTick();s.age++;__baby.age=18;Math.random=()=>0;familyFourthGenerationYearTick();";
