test("v70 adulthood outcome does not repeat on annual tick",()=>{const {run}=game();run(setup+v70Older+"s.age++;familyFourthGenerationYearTick();");assert.equal(run("ensureFamilyBranches().fourthGenerationLearning.adulthood"),1);});
