/* v71 — true parent/child bonds, consent-based family mediation and next generation effects. */
const v71Kin=v70Student+"window.__older=__kid;window.__younger=__kid.descendants[0];familyIntergenerationalBondsYearTick();";
const v71Conflict=v71Kin+"window.__bond=familyIntergenerationalBond(__older,__younger);__bond.tension=65;__bond.warmth=20;__bond.status='strained';";
const v71Reconcile=v71Conflict+"Math.random=()=>0;familyIntergenerationalAction(__older.id,__younger.id,'reconcile');";
const v71Gather=v71Kin+"Math.random=()=>0;familyIntergenerationalAction(__older.id,__younger.id,'gather');";
const v71Pair="ensureFamilyBranches().intergenerationalBonds.pairs.find(r=>r.olderId===__older.id&&r.youngerId===__younger.id)";
test("v71 game saves report version 71",()=>{const {run}=game();assert.equal(run('s.version'),73);});
test("v71 fresh family bond ledger begins empty",()=>{const {run}=game();run(setup+v70Child);assert.equal(run('ensureFamilyBranches().intergenerationalBonds.pairs.length'),0);});
test("v71 generated kin pairs use real NPC parent and child",()=>{const {run}=game();run(setup+v71Kin);assert.ok(run("familyIntergenerationalPair(__older.id,__younger.id)"));});
test("v71 fourth generation parent and child is also a true kin pair",()=>{const {run}=game();run(setup+v71Kin);assert.ok(run("familyIntergenerationalPair(__younger.id,__baby.id)"));});
test("v71 pair lookup cannot connect unrelated fabricated NPCs",()=>{const {run}=game();run(setup+v71Kin);assert.equal(run("familyIntergenerationalPair('fake1','fake2')"),null);});
test("v71 pair set has no duplicate identities",()=>{const {run}=game();run(setup+v71Kin);assert.equal(run("familyIntergenerationalPairs().filter(p=>p.older.id===__older.id&&p.younger.id===__younger.id).length"),1);});
test("v71 annual family tick writes one record for first kin bond",()=>{const {run}=game();run(setup+v71Kin);assert.ok(run(v71Pair));});
test("v71 fourth generation bond ledger remains tied to genuine child",()=>{const {run}=game();run(setup+v71Kin);assert.ok(run("ensureFamilyBranches().intergenerationalBonds.pairs.some(r=>r.olderId===__younger.id&&r.youngerId===__baby.id)"));});
test("v71 annual bond update cannot fire twice in same year",()=>{const {run}=game();run(setup+v71Kin+"window.__previous=("+v71Pair+").warmth;familyIntergenerationalBondsYearTick();");assert.equal(run("("+v71Pair+").warmth"),run("__previous"));});
test("v71 kinship bond never mints NPCs",()=>{const {run}=game();run(setup+v71Kin+"window.__count=allNPCs().length;familyIntergenerationalBondsYearTick();");assert.equal(run("allNPCs().length"),run("__count"));});
test("v71 severe genuine relationship grudge generates tension",()=>{const {run}=game();run(setup+v71Kin+"const link=socialLinkBetween(__older,__younger,true);link.grudge=60;link.trust=10;window.__before=("+v71Pair+").tension;s.age++;familyIntergenerationalBondsYearTick();");assert.ok(run("("+v71Pair+").tension>__before"));});
test("v71 geographic separation strains closeness gradually",()=>{const {run}=game();run(setup+v71Kin+"__younger.place='other_place';window.__before=("+v71Pair+").warmth;s.age++;familyIntergenerationalBondsYearTick();");assert.ok(run("("+v71Pair+").warmth<__before"));});
test("v71 high-trust co-located relatives can grow closer",()=>{const {run}=game();run(setup+v71Kin+"const link=socialLinkBetween(__older,__younger,true);link.trust=90;link.grudge=0;window.__before=("+v71Pair+").warmth;s.age++;familyIntergenerationalBondsYearTick();");assert.ok(run("("+v71Pair+").warmth>=__before"));});
test("v71 severe tension creates a recorded family dispute once",()=>{const {run}=game();run(setup+v71Kin+"window.__r=familyIntergenerationalBond(__older,__younger);__r.warmth=30;__r.tension=45;const link=socialLinkBetween(__older,__younger,true);link.grudge=80;s.age++;familyIntergenerationalBondsYearTick();familyIntergenerationalBondsYearTick();");assert.equal(run("("+v71Pair+").status"),'strained');assert.equal(run("ensureFamilyBranches().intergenerationalBonds.disputes"),1);});
test("v71 natural strain does not directly confiscate money",()=>{const {run}=game();run(setup+v71Conflict+"window.__money=s.wealth;window.__other=__younger.wealth;s.age++;familyIntergenerationalBondsYearTick();");assert.equal(run("s.wealth"),run("__money"));assert.equal(run("__younger.wealth"),run("__other"));});
test("v71 consented reconciliation decreases genuine tension",()=>{const {run}=game();run(setup+v71Reconcile);assert.ok(run("("+v71Pair+").tension<65"));});
test("v71 successful reconciliation raises family warmth",()=>{const {run}=game();run(setup+v71Reconcile);assert.ok(run("("+v71Pair+").warmth>20"));});
test("v71 successful mediation affects actual NPC social graph",()=>{const {run}=game();run(setup+v71Conflict+"window.__before=socialLinkBetween(__older,__younger,true).trust;Math.random=()=>0;familyIntergenerationalAction(__older.id,__younger.id,'reconcile');");assert.ok(run("socialLinkBetween(__older,__younger).trust>__before"));});
test("v71 accepted reconciliation is durable in history",()=>{const {run}=game();run(setup+v71Reconcile);assert.equal(run("ensureFamilyBranches().intergenerationalBonds.reconciliations"),1);assert.equal(run("("+v71Pair+").reconciliations"),1);});
test("v71 reconciliation consumes exactly one month",()=>{const {run}=game();run(setup+v71Reconcile);assert.equal(run("s.monthsRemaining"),11);});
test("v71 rejected reconciliation cannot force peace",()=>{const {run}=game();run(setup+v71Conflict+"Math.random=()=>.99;familyIntergenerationalAction(__older.id,__younger.id,'reconcile');");assert.equal(run("("+v71Pair+").reconciliations"),0);assert.equal(run("ensureFamilyBranches().intergenerationalBonds.refusals"),1);});
test("v71 refused meeting still spends an action right",()=>{const {run}=game();run(setup+v71Conflict+"Math.random=()=>.99;familyIntergenerationalAction(__older.id,__younger.id,'reconcile');");assert.equal(run("s.monthsRemaining"),11);});
test("v71 gentle family gathering improves real warmth",()=>{const {run}=game();run(setup+v71Kin+"window.__old=("+v71Pair+").warmth;Math.random=()=>0;familyIntergenerationalAction(__older.id,__younger.id,'gather');");assert.ok(run("("+v71Pair+").warmth>__old"));assert.equal(run("ensureFamilyBranches().intergenerationalBonds.meetings"),1);});
test("v71 gathering lessens mild family tension",()=>{const {run}=game();run(setup+v71Conflict+"Math.random=()=>0;familyIntergenerationalAction(__older.id,__younger.id,'gather');");assert.ok(run("("+v71Pair+").tension<65"));});
test("v71 gathering can be refused without inventing goodwill",()=>{const {run}=game();run(setup+v71Kin+"Math.random=()=>.99;familyIntergenerationalAction(__older.id,__younger.id,'gather');");assert.equal(run("ensureFamilyBranches().intergenerationalBonds.meetings"),0);assert.equal(run("ensureFamilyBranches().intergenerationalBonds.refusals"),1);});
test("v71 one bond cannot be met twice in same year",()=>{const {run}=game();run(setup+v71Gather+"window.__ok=familyIntergenerationalAction(__older.id,__younger.id,'gather');");assert.equal(run("__ok"),false);assert.equal(run("ensureFamilyBranches().intergenerationalBonds.meetings"),1);});
test("v71 second meeting does not spend extra month",()=>{const {run}=game();run(setup+v71Gather+"familyIntergenerationalAction(__older.id,__younger.id,'gather');");assert.equal(run("s.monthsRemaining"),11);});
test("v71 no mediation can be scheduled without a dispute",()=>{const {run}=game();run(setup+v71Kin+"window.__rec=familyIntergenerationalBond(__older,__younger);__rec.tension=0;__rec.status='neutral';window.__ok=familyIntergenerationalAction(__older.id,__younger.id,'reconcile');");assert.equal(run("__ok"),false);});
