test("v71 deceased kin cannot be reconciled by action",()=>{const {run}=game();run(setup+v71Kin+"__older.alive=false;window.__ok=familyIntergenerationalAction(__older.id,__younger.id,'gather');");assert.equal(run("__ok"),false);});
test("v71 separated realm family action refused",()=>{const {run}=game();run(setup+v71Kin+"__younger.realm='other';window.__ok=familyIntergenerationalAction(__older.id,__younger.id,'gather');");assert.equal(run("__ok"),false);});
