test("v71 family main tab includes kinship panel",()=>{const {run}=game();run(setup+v71Kin+"window.__html=adultChildrenSummaryHtml();");assert.ok(run("__html.includes('Kuşaklar Arası Bağlar')"));});
test("v71 family actions generate NPC memory instead of synthetic NPC",()=>{const {run}=game();run(setup+v71Kin+"window.__before=allNPCs().length;Math.random=()=>0;familyIntergenerationalAction(__older.id,__younger.id,'gather');");assert.equal(run("allNPCs().length"),run("__before"));assert.ok(run("__younger.memories.some(m=>m.kind==='family'||m.kind==='bond')"));});
test("v71 save and load persists reconciliation and year cooldown",()=>{const {run}=game();run(setup+v71Reconcile+"save();load();");assert.equal(run("ensureFamilyBranches().intergenerationalBonds.reconciliations"),1);assert.ok(run("ensureFamilyBranches().intergenerationalBonds.pairs.some(r=>r.reconciliations===1&&r.lastTalkYear===s.year+s.age)"));});
test("v71 old v70 saves get safe backup and retain real people",()=>{const {run,storage}=game();run(setup+v71Kin+"s.version=70;save();load();");assert.equal(run("s.version"),73);assert.ok(storage.has('yazgi_before_v71'));assert.ok(run("fourthGenerationById('great-grandchild-v69')"));});
test("v71 migration drops malformed kin pairs",()=>{const {run}=game();run(setup+v71Kin+"window.__before=ensureFamilyBranches().intergenerationalBonds.pairs.length;s.familyBranches.intergenerationalBonds.pairs.push({olderId:5,youngerId:8});ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().intergenerationalBonds.pairs.length"),run("__before"));});
test("v71 migration repairs invalid tension and warmth values",()=>{const {run}=game();run(setup+v71Kin+"window.__r=familyIntergenerationalBond(__older,__younger);__r.warmth=200;__r.tension=Infinity;ensureFamilyBranches();");assert.equal(run("("+v71Pair+").warmth"),100);assert.equal(run("("+v71Pair+").tension"),5);});

/* v72: long-horizon voluntary family council and rotating actual responsibilities. */
const v72Family=v71Kin+"__kid.wealth=18;__kid2.wealth=2;__kid.place=s.place;__kid.realm=s.realm;__kid2.place=s.place;__kid2.realm=s.realm;__kid.bonds.trust=90;__kid2.bonds.trust=90;";
const v72Start=v72Family+"Math.random=()=>0;familyCouncilAction('start','education');";
const v72Education=v72Start+"s.age++;familyCouncilYearTick();";
const v72Relief=v72Family+"Math.random=()=>0;familyCouncilAction('start','relief');";
const v72ReliefTick=v72Relief+"s.age++;familyCouncilYearTick();";
const v72Harmony=v72Family+"window.__rift=familyIntergenerationalBond(__kid,__kid.descendants[0]);__rift.tension=65;__rift.warmth=25;__rift.status='strained';Math.random=()=>0;familyCouncilAction('start','harmony');window.__rift=familyIntergenerationalBond(__kid,__kid.descendants[0]);";
test("v72 fresh game uses save version 72",()=>{const {run}=game();assert.equal(run("s.version"),73);});
test("v72 normalizes empty council from older family branch",()=>{const {run}=game();run(setup+v72Family);assert.equal(run("ensureFamilyBranches().familyCouncil.charter"),null);});
test("v72 family council demands two adult real children",()=>{const {run}=game();run(setup+v72Family+"__kid2.alive=false;window.__ok=familyCouncilAction('start','education');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),12);});
test("v72 family council requires local available volunteers",()=>{const {run}=game();run(setup+v72Family+"__kid2.place='far';window.__ok=familyCouncilAction('start','relief');");assert.equal(run("__ok"),false);});
test("v72 council rejects fabricated agendas",()=>{const {run}=game();run(setup+v72Family+"window.__ok=familyCouncilAction('start','invented');");assert.equal(run("__ok"),false);});
test("v72 establishing a charter costs a monthly right",()=>{const {run}=game();run(setup+v72Start);assert.equal(run("s.monthsRemaining"),11);});
test("v72 valid charter has elected education agenda",()=>{const {run}=game();run(setup+v72Start);assert.equal(run("ensureFamilyBranches().familyCouncil.charter.agenda"),'education');assert.equal(run("ensureFamilyBranches().familyCouncil.established"),1);});
test("v72 charter includes only real consenting children",()=>{const {run}=game();run(setup+v72Start);assert.equal(run("ensureFamilyBranches().familyCouncil.charter.memberIds.length"),2);});
test("v72 signed charter lasts three calendar years",()=>{const {run}=game();run(setup+v72Start);assert.equal(run("ensureFamilyBranches().familyCouncil.charter.untilYear"),run("s.year+s.age+3"));});
test("v72 cannot start second charter with one still active",()=>{const {run}=game();run(setup+v72Start+"window.__ok=familyCouncilAction('start','relief');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),11);});
test("v72 consenting relatives may refuse charter without forced duty",()=>{const {run}=game();run(setup+v72Family+"Math.random=()=>.99;familyCouncilAction('start','relief');");assert.equal(run("ensureFamilyBranches().familyCouncil.charter"),null);assert.equal(run("ensureFamilyBranches().familyCouncil.declines"),1);});
test("v72 rejected charter still costs a month",()=>{const {run}=game();run(setup+v72Family+"Math.random=()=>.99;familyCouncilAction('start','relief');");assert.equal(run("s.monthsRemaining"),11);});
test("v72 one annual offer cannot be retried after refusal",()=>{const {run}=game();run(setup+v72Family+"Math.random=()=>.99;familyCouncilAction('start','relief');window.__ok=familyCouncilAction('start','education');");assert.equal(run("__ok"),false);assert.equal(run("ensureFamilyBranches().familyCouncil.offers"),1);});
test("v72 education rotation trains actual fourth generation",()=>{const {run}=game();run(setup+v72Start+"window.__skill=__baby.skills.riding;s.age++;familyCouncilYearTick();");assert.equal(run("__baby.skills.riding"),run("__skill+2"));});
test("v72 education rotation increments existing learning progress",()=>{const {run}=game();run(setup+v72Start+"window.__before=ensureFamilyBranches().fourthGenerationLearning.students.find(r=>r.id===__baby.id).progress;s.age++;familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().fourthGenerationLearning.students.find(r=>r.id===__baby.id).progress"),run("__before+2"));});
test("v72 education does not mint imaginary household income",()=>{const {run}=game();run(setup+v72Start+"window.__w=s.wealth;window.__p=__kid.wealth;s.age++;familyCouncilYearTick();");assert.equal(run("s.wealth"),run("__w"));assert.equal(run("__kid.wealth"),run("__p"));});
test("v72 annual education tick has exactly one responsibility",()=>{const {run}=game();run(setup+v72Education+"familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyFulfilled"),1);});
test("v72 first council year does not award advance service",()=>{const {run}=game();run(setup+v72Start+"familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyFulfilled"),0);});
test("v72 two-year service rotates council members",()=>{const {run}=game();run(setup+v72Education+"s.age++;familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.nextIndex"),0);});
test("v72 unavailable rotating member leads to a recorded missed duty",()=>{const {run}=game();run(setup+v72Start+"__kid.place='far';s.age++;familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyMissed"),1);});
test("v72 adult kin loss closes charter without imaginary service",()=>{const {run}=game();run(setup+v72Start+"__kid2.alive=false;s.age++;familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.active"),false);assert.equal(run("ensureFamilyBranches().familyCouncil.charter.finishedReason"),'bereaved');});
test("v72 voluntary end closes an active charter",()=>{const {run}=game();run(setup+v72Start+"familyCouncilAction('end');");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.active"),false);assert.equal(run("ensureFamilyBranches().familyCouncil.cancellations"),1);});
test("v72 voluntary end uses one month",()=>{const {run}=game();run(setup+v72Start+"familyCouncilAction('end');");assert.equal(run("s.monthsRemaining"),10);});
test("v72 ended council cannot end again for a free point",()=>{const {run}=game();run(setup+v72Start+"familyCouncilAction('end');window.__ok=familyCouncilAction('end');");assert.equal(run("__ok"),false);assert.equal(run("ensureFamilyBranches().familyCouncil.cancellations"),1);});
test("v72 education year number three completes charter once",()=>{const {run}=game();run(setup+v72Start+"s.age++;familyCouncilYearTick();s.age++;familyCouncilYearTick();s.age++;familyCouncilYearTick();familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.completed"),1);assert.equal(run("ensureFamilyBranches().familyCouncil.charter.active"),false);});
test("v72 completed charter can be proposed again in later year",()=>{const {run}=game();run(setup+v72Start+"s.age+=3;familyCouncilYearTick();s.age++;window.__issue=familyCouncilIssue('start','education');");assert.equal(run("__issue"),'');});
test("v72 relief treasury is transferred from real donor to real recipient",()=>{const {run}=game();run(setup+v72ReliefTick);assert.equal(run("__kid.wealth"),16);assert.equal(run("__kid2.wealth"),4);});
test("v72 relief preserves combined real NPC funds",()=>{const {run}=game();run(setup+v72Relief+"window.__total=__kid.wealth+__kid2.wealth;s.age++;familyCouncilYearTick();");assert.equal(run("__kid.wealth+__kid2.wealth"),run("__total"));});
test("v72 relief cannot debit player instead of donor",()=>{const {run}=game();run(setup+v72Relief+"window.__w=s.wealth;s.age++;familyCouncilYearTick();");assert.equal(run("s.wealth"),run("__w"));});
test("v72 relief does not withdraw protected donor reserve",()=>{const {run}=game();run(setup+v72Relief+"__kid.wealth=7;s.age++;familyCouncilYearTick();");assert.equal(run("__kid.wealth"),7);assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyMissed"),1);});
test("v72 recipient with sufficient wealth does not receive fake gift",()=>{const {run}=game();run(setup+v72Relief+"__kid2.wealth=11;s.age++;familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyFulfilled"),0);});
test("v72 one relief transfer per calendar year",()=>{const {run}=game();run(setup+v72ReliefTick+"familyCouncilYearTick();");assert.equal(run("__kid2.wealth"),4);});
test("v72 relief rotates obligation even when next member is broke",()=>{const {run}=game();run(setup+v72ReliefTick+"s.age++;familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyMissed"),1);});
test("v72 mediation reduces real ongoing intergenerational tension",()=>{const {run}=game();run(setup+v72Harmony+"window.__before=__rift.tension;s.age++;familyCouncilYearTick();");assert.ok(run("familyIntergenerationalBond(__kid,__kid.descendants[0]).tension<__before"));});
test("v72 mediation strengthens actual NPC trust link",()=>{const {run}=game();run(setup+v72Harmony+"window.__before=socialLinkBetween(__kid,__kid.descendants[0],true).trust;s.age++;familyCouncilYearTick();");assert.ok(run("socialLinkBetween(__kid,__kid.descendants[0]).trust>__before"));});
test("v72 calm bonds do not generate fictitious reconciliation",()=>{const {run}=game();run(setup+v72Harmony+"__rift.tension=0;__rift.status='neutral';s.age++;familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyMissed"),1);assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyFulfilled"),0);});
test("v72 refusal of scheduled mediation cannot force forgiveness",()=>{const {run}=game();run(setup+v72Harmony+"Math.random=()=>.99;s.age++;familyCouncilYearTick();");assert.equal(run("__rift.tension"),65);assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyMissed"),1);});
test("v72 annual council does not generate duplicate children",()=>{const {run}=game();run(setup+v72Start+"window.__before=allNPCs().length;s.age++;familyCouncilYearTick();");assert.equal(run("allNPCs().length"),run("__before"));});
test("v72 council UI appears in actual family tab",()=>{const {run}=game();run(setup+v72Start+"window.__html=adultChildrenSummaryHtml();");assert.ok(run("__html.includes('Aile Meclisi ve Uzun Dayanışma')"));});
test("v72 council agenda and members are shown by name",()=>{const {run}=game();run(setup+v72Start+"window.__html=familyCouncilHtml();");assert.ok(run("__html.includes(__kid.name)"));assert.ok(run("__html.includes('Kuşakların Eğitimi')"));});
test("v72 direct action guard rejects unsupported council mode",()=>{const {run}=game();run(setup+v72Family+"window.__issue=accessIssue({kind:'familyCouncil',id:'loot',agenda:'education'});");assert.ok(run("__issue.length>0"));});
test("v72 v71 save migrates with automatic safety backup",()=>{const {run,storage}=game();run(setup+v72Start+"s.version=71;save();load();");assert.equal(run("s.version"),73);assert.ok(storage.has("yazgi_before_v72"));assert.equal(run("ensureFamilyBranches().familyCouncil.charter.agenda"),'education');});
test("v72 save reload keeps charter progress and member IDs",()=>{const {run}=game();run(setup+v72Education+"save();load();");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.fulfilled"),1);assert.equal(run("ensureFamilyBranches().familyCouncil.charter.memberIds.length"),2);});
test("v72 malformed charter is cleaned while retaining valid history",()=>{const {run}=game();run(setup+v72Start+"s.familyBranches.familyCouncil.charter.memberIds=['x','x'];ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().familyCouncil.charter"),null);});
test("v72 impossible counters are normalized safely",()=>{const {run}=game();run(setup+v72Start+"s.familyBranches.familyCouncil.charter.fulfilled=Infinity;s.familyBranches.familyCouncil.offers=-4;ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.fulfilled"),0);assert.equal(run("ensureFamilyBranches().familyCouncil.offers"),0);});


/* v73 — annual voluntary council reviews, location-safe duties and persistence. */
const v73Ready=v72Start+"s.age++;";
const v73Review=v73Ready+"familyCouncilAction('review','relief');";
test("v73 new life uses version 73",()=>{const {run}=game();assert.equal(run("s.version"),73);});
test("v73 begins with no invented council reviews",()=>{const {run}=game();assert.equal(run("ensureFamilyBranches().familyCouncil.reviews"),0);assert.equal(run("ensureFamilyBranches().familyCouncil.lastReviewYear"),null);});
test("v73 cannot review nonexistent charter",()=>{const {run}=game();run(setup+v72Family+"window.__ok=familyCouncilAction('review','relief');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),12);});
test("v73 cannot rewrite charter on its founding year",()=>{const {run}=game();run(setup+v72Start+"window.__ok=familyCouncilAction('review','relief');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),11);});
test("v73 review rejects unchanged agenda without spending month",()=>{const {run}=game();run(setup+v73Ready+"window.__ok=familyCouncilAction('review','education');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),11);});
test("v73 review rejects fabricated agenda",()=>{const {run}=game();run(setup+v73Ready+"window.__ok=familyCouncilAction('review','invented');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),11);});
test("v73 review cannot override absentee signatory",()=>{const {run}=game();run(setup+v73Ready+"__kid2.place='remote';window.__ok=familyCouncilAction('review','relief');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),11);});
test("v73 review cannot override deceased signatory",()=>{const {run}=game();run(setup+v73Ready+"__kid2.alive=false;window.__ok=familyCouncilAction('review','relief');");assert.equal(run("__ok"),false);assert.equal(run("s.monthsRemaining"),11);});
test("v73 unanimous review changes real active council agenda",()=>{const {run}=game();run(setup+v73Review);assert.equal(run("ensureFamilyBranches().familyCouncil.charter.agenda"),"relief");assert.equal(run("ensureFamilyBranches().familyCouncil.reviews"),1);});
test("v73 successful review costs one month",()=>{const {run}=game();run(setup+v73Review);assert.equal(run("s.monthsRemaining"),10);});
test("v73 unanimous review preserves original membership and year bounds",()=>{const {run}=game();run(setup+v73Ready+"window.__ids=ensureFamilyBranches().familyCouncil.charter.memberIds.join(',');window.__until=ensureFamilyBranches().familyCouncil.charter.untilYear;familyCouncilAction('review','relief');");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.memberIds.join(',')"),run("__ids"));assert.equal(run("ensureFamilyBranches().familyCouncil.charter.untilYear"),run("__until"));});
test("v73 review never awards an extra annual service",()=>{const {run}=game();run(setup+v73Review);assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyFulfilled"),0);assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyMissed"),0);});
test("v73 review preserves next annual volunteer rotation",()=>{const {run}=game();run(setup+v73Ready+"window.__next=ensureFamilyBranches().familyCouncil.charter.nextIndex;familyCouncilAction('review','harmony');");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.nextIndex"),run("__next"));});
test("v73 unanimous review stays locked for the rest of the year",()=>{const {run}=game();run(setup+v73Review+"window.__ok=familyCouncilAction('review','harmony');");assert.equal(run("__ok"),false);assert.equal(run("ensureFamilyBranches().familyCouncil.reviewOffers"),1);assert.equal(run("s.monthsRemaining"),10);});
test("v73 council signatories may refuse a new agenda",()=>{const {run}=game();run(setup+v73Ready+"Math.random=()=>.99;familyCouncilAction('review','relief');");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.agenda"),"education");assert.equal(run("ensureFamilyBranches().familyCouncil.reviewDeclines"),1);});
test("v73 refused review still costs one month",()=>{const {run}=game();run(setup+v73Ready+"Math.random=()=>.99;familyCouncilAction('review','relief');");assert.equal(run("s.monthsRemaining"),10);});
test("v73 review refusal cannot be rerolled in the same year",()=>{const {run}=game();run(setup+v73Ready+"Math.random=()=>.99;familyCouncilAction('review','relief');window.__ok=familyCouncilAction('review','harmony');");assert.equal(run("__ok"),false);assert.equal(run("ensureFamilyBranches().familyCouncil.reviewOffers"),1);});
test("v73 review refusal leaves original responsibilities in place",()=>{const {run}=game();run(setup+v73Ready+"Math.random=()=>.99;familyCouncilAction('review','relief');s.age++;familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.agenda"),"education");assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyFulfilled"),1);});
test("v73 changing relief agenda transfers actual NPC funds in next tick",()=>{const {run}=game();run(setup+v73Review+"window.__sum=__kid.wealth+__kid2.wealth;s.age++;familyCouncilYearTick();");assert.equal(run("__kid.wealth+__kid2.wealth"),run("__sum"));assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyFulfilled"),1);});
test("v73 council donor living elsewhere cannot transfer funds remotely",()=>{const {run}=game();run(setup+v72Relief+"__kid.place='remote';window.__sum=__kid.wealth+__kid2.wealth;s.age++;familyCouncilYearTick();");assert.equal(run("__kid.wealth+__kid2.wealth"),run("__sum"));assert.equal(run("__kid2.wealth"),2);assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyMissed"),1);});
test("v73 offsite teaching is not counted as a fulfilled duty",()=>{const {run}=game();run(setup+v72Start+"__kid.place='remote';window.__before=__baby.skills.riding;s.age++;familyCouncilYearTick();");assert.equal(run("__baby.skills.riding"),run("__before"));assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyMissed"),1);});
test("v73 repeated yearly tick cannot debit twice after offsite miss",()=>{const {run}=game();run(setup+v72Relief+"__kid.place='remote';s.age++;familyCouncilYearTick();familyCouncilYearTick();");assert.equal(run("ensureFamilyBranches().familyCouncil.yearlyMissed"),1);});
test("v73 family tab explains council reviews and next signatory",()=>{const {run}=game();run(setup+v73Ready+"window.__html=familyCouncilHtml();");assert.ok(run("__html.includes('Gündemi görüş')"));assert.ok(run("__html.includes('Sıradaki yıllık sorumluluk')"));});
test("v73 successful review is preserved after saving and reloading",()=>{const {run}=game();run(setup+v73Review+"save();load();");assert.equal(run("ensureFamilyBranches().familyCouncil.charter.agenda"),"relief");assert.equal(run("ensureFamilyBranches().familyCouncil.reviews"),1);});
test("v73 rejected review cooldown persists across reload",()=>{const {run}=game();run(setup+v73Ready+"Math.random=()=>.99;familyCouncilAction('review','relief');save();load();");assert.equal(run("familyCouncilIssue('review','harmony')").includes('bu yıl'),true);});
test("v73 normalization clamps review counters and rejects invalid year",()=>{const {run}=game();run(setup+v73Review+"s.familyBranches.familyCouncil.reviewOffers=-2;s.familyBranches.familyCouncil.lastReviewYear=Infinity;ensureFamilyBranches();");assert.equal(run("ensureFamilyBranches().familyCouncil.reviewOffers"),0);assert.equal(run("ensureFamilyBranches().familyCouncil.lastReviewYear"),null);});
test("v73 prior v72 saves receive a distinct backup",()=>{const {run,storage}=game();run(setup+v73Review+"s.version=72;save();load();");assert.equal(run("s.version"),73);assert.ok(storage.has("yazgi_before_v73"));assert.equal(run("ensureFamilyBranches().familyCouncil.charter.agenda"),"relief");});
test("v73 review cannot reactivate canceled charter",()=>{const {run}=game();run(setup+v73Ready+"familyCouncilAction('end');window.__ok=familyCouncilAction('review','relief');");assert.equal(run("__ok"),false);assert.equal(run("ensureFamilyBranches().familyCouncil.charter.active"),false);});
test("v73 reviews do not generate synthetic family members",()=>{const {run}=game();run(setup+v73Ready+"window.__size=allNPCs().length;familyCouncilAction('review','relief');");assert.equal(run("allNPCs().length"),run("__size"));});
